def now_kst():
    return datetime.now(ZoneInfo(TIMEZONE))
def r(x, n=4):
    try:
        return round(float(x), n)
    except Exception:
        return 0.0
def safe_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return default
def fmt_price(x):
    try:
        x = float(x)
    except Exception:
        return "0"
    if x >= 1000:
        return f"{x:,.0f}"
    elif x >= 100:
        return f"{x:,.1f}"
    elif x >= 1:
        return f"{x:,.2f}"
    elif x >= 0.1:
        return f"{x:,.3f}"
    elif x >= 0.01:
        return f"{x:,.4f}"
    else:
        return f"{x:,.6f}"
def fmt_pct(x):
    try:
        return f"{float(x):.2f}%"
    except Exception:
        return "0.00%"
def fmt_price_detail(x):
    try:
        x = float(x)
    except Exception:
        return "0"
    ax = abs(x)
    if ax >= 1000:
        return f"{x:,.0f}"
    if ax >= 100:
        return f"{x:,.1f}"
    if ax >= 10:
        return f"{x:,.2f}"
    if ax >= 1:
        return f"{x:,.3f}"
    if ax >= 0.1:
        return f"{x:,.4f}"
    if ax >= 0.01:
        return f"{x:,.5f}"
    return f"{x:,.6f}"
def format_ts_hm(ts: float) -> str:
    try:
        return datetime.fromtimestamp(float(ts), ZoneInfo(TIMEZONE)).strftime("%H:%M:%S")
    except Exception:
        return "--:--:--"
def format_ts_mdhm(ts: float) -> str:
    try:
        return datetime.fromtimestamp(float(ts), ZoneInfo(TIMEZONE)).strftime("%m-%d %H:%M:%S")
    except Exception:
        return "--:--:--"
def floor_minute_ts(ts: float) -> float:
    ts = safe_float(ts, 0)
    if ts <= 0:
        return 0.0
    return math.floor(ts / 60.0) * 60.0
def ceil_minute_ts(ts: float) -> float:
    ts = safe_float(ts, 0)
    if ts <= 0:
        return 0.0
    return math.ceil(ts / 60.0) * 60.0
def get_file_io_lock(path: str):
    norm = os.path.abspath(path)
    with FILE_IO_MASTER_LOCK:
        lock = FILE_IO_LOCKS.get(norm)
        if lock is None:
            lock = threading.Lock()
            FILE_IO_LOCKS[norm] = lock
    return lock
def get_api_cache_entry(cache: dict, key, ttl_sec: float, copy_dataframe: bool = False):
    now_ts = time.time()
    with API_CACHE_LOCK:
        row = cache.get(key)
        if not isinstance(row, dict):
            return None
        saved_ts = safe_float(row.get("ts", 0), 0)
        if saved_ts <= 0 or (now_ts - saved_ts) > max(float(ttl_sec), 0.0):
            return None
        value = row.get("value")
    if copy_dataframe and value is not None:
        try:
            return value.copy(deep=True)
        except Exception:
            return value
    return value
def set_api_cache_entry(cache: dict, key, value, copy_dataframe: bool = False):
    stored = value
    if copy_dataframe and value is not None:
        try:
            stored = value.copy(deep=True)
        except Exception:
            stored = value
    with API_CACHE_LOCK:
        cache[key] = {"ts": time.time(), "value": stored}
def get_ohlcv_cache_ttl(interval: str) -> float:
    key = str(interval or "").lower().strip()
    if key in {"minute1", "minute3", "minute5", "minute10"}:
        return API_OHLCV_FAST_TTL_SEC
    if key == "minute15":
        return max(API_OHLCV_SLOW_TTL_SEC, 90.0)
    if key == "minute30":
        return max(API_OHLCV_SLOW_TTL_SEC, 150.0)
    if key == "minute60":
        return max(API_OHLCV_SLOW_TTL_SEC, 300.0)
    if key == "minute240":
        return max(API_OHLCV_SLOW_TTL_SEC, 1200.0)
    if key == "day":
        return max(API_OHLCV_SLOW_TTL_SEC, 3600.0)
    return API_OHLCV_SLOW_TTL_SEC
def _runtime_log_ts() -> str:
    try:
        return now_kst().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")
def _runtime_safe_preview(value, limit: int = RUNTIME_LOG_PREVIEW_CHARS) -> str:
    try:
        text = str(value)
    except Exception:
        text = repr(value)
    if len(text) > limit:
        return text[:limit] + " ...(truncated)"
    return text
def get_runtime_context_snapshot() -> dict:
    try:
        return {
            "loop_stage": str(last_main_loop_stage or ""),
            "loop_error": str(last_main_loop_error or ""),
            "loop_heartbeat_age_sec": round(max(0.0, time.time() - safe_float(last_main_loop_heartbeat_ts, 0)), 1) if safe_float(last_main_loop_heartbeat_ts, 0) > 0 else -1,
            "market_refresh_in_progress": bool(market_refresh_in_progress),
            "market_refresh_reason": str(last_market_refresh_reason or ""),
            "market_refresh_result": str(last_market_refresh_result or ""),
            "market_refresh_age_sec": round(max(0.0, time.time() - safe_float(market_refresh_started_ts, 0)), 1) if safe_float(market_refresh_started_ts, 0) > 0 else 0.0,
            "market_refresh_stuck_suppressed": int(safe_float(last_market_refresh_stuck_suppressed, 0)),
            "cache_size": len(shared_market_cache) if isinstance(shared_market_cache, dict) else -1,
            "universe_size": len(market_universe) if isinstance(market_universe, list) else -1,
            "active_positions": len(active_positions) if isinstance(active_positions, dict) else -1,
            "pending_sells": len(pending_sells) if isinstance(pending_sells, dict) else -1,
            "pending_buys": len(pending_buy_candidates) if isinstance(pending_buy_candidates, dict) else -1,
            "scan_runtime_reset_count": int(scan_runtime_reset_count),
            "scan_runtime_reset_reason": str(scan_runtime_reset_reason or ""),
        }
    except Exception as e:
        return {"snapshot_error": str(e)}
def _maybe_rotate_runtime_error_log():
    global ERROR_LOG_LAST_ROTATE_CHECK_TS
    try:
        now_ts = time.time()
        if now_ts - safe_float(ERROR_LOG_LAST_ROTATE_CHECK_TS, 0) < ERROR_LOG_ROTATE_CHECK_INTERVAL_SEC:
            return
        ERROR_LOG_LAST_ROTATE_CHECK_TS = now_ts
        if not os.path.exists(RUNTIME_ERROR_LOG_FILE):
            return
        if os.path.getsize(RUNTIME_ERROR_LOG_FILE) <= ERROR_LOG_ROTATE_MAX_BYTES:
            return
        rows = []
        with open(RUNTIME_ERROR_LOG_FILE, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                rows.append(line)
                if len(rows) > ERROR_LOG_ROTATE_KEEP_LINES:
                    rows.pop(0)
        with open(RUNTIME_ERROR_LOG_FILE, 'w', encoding='utf-8') as f:
            f.write(''.join(rows).rstrip() + "\n")
    except Exception:
        pass
def _append_error_tail_cache(text: str):
    try:
        chunk = str(text or '').strip()
        if not chunk:
            return
        with ERROR_LOG_TAIL_CACHE_LOCK:
            for line in chunk.splitlines():
                ERROR_LOG_TAIL_CACHE.append(line)
            ERROR_LOG_TAIL_CACHE.append('')
    except Exception:
        pass
def _read_runtime_error_log_tail_from_file(max_lines: int = RUNTIME_ERROR_LOG_TAIL_LINES, max_bytes: int = None) -> str:
    try:
        if not os.path.exists(RUNTIME_ERROR_LOG_FILE):
            return ""
        max_lines = max(1, int(max_lines))
        max_bytes = int(max_bytes or globals().get("ERROR_LOG_FAST_TAIL_BYTES", 80_000))
        size = os.path.getsize(RUNTIME_ERROR_LOG_FILE)
        with open(RUNTIME_ERROR_LOG_FILE, 'rb') as f:
            if size > max_bytes:
                f.seek(max(0, size - max_bytes))
            raw = f.read(max_bytes + 1024)
        text = raw.decode('utf-8', errors='ignore')
        lines = text.splitlines()[-max_lines:]
        return '\n'.join(lines).strip()
    except Exception:
        return ""
def append_runtime_error_log(tag: str, message: str, exc: Exception = None, extra: dict = None, include_traceback: bool = False):
    try:
        lines = [f"[{_runtime_log_ts()}] [{str(tag or 'runtime')}] {str(message or '').strip()}"]
        if extra:
            lines.append("- extra: " + json.dumps(extra, ensure_ascii=False, default=str))
        lines.append("- context: " + json.dumps(get_runtime_context_snapshot(), ensure_ascii=False, default=str))
        if exc is not None:
            lines.append(f"- exc_type: {exc.__class__.__name__}")
            lines.append(f"- exc_msg: {_runtime_safe_preview(exc)}")
        if include_traceback:
            if exc is not None:
                tb_text = ''.join(traceback.format_exception(type(exc), exc, exc.__traceback__))
            else:
                tb_text = traceback.format_exc()
            tb_text = tb_text.strip()
            if tb_text and tb_text != 'NoneType: None':
                lines.append('- traceback:\n' + tb_text)
        lines.append('')
        body = '\n'.join(lines)
        _append_error_tail_cache(body)
        try:
            with ERROR_LOG_TAIL_CACHE_LOCK:
                for line in body.splitlines():
                    ERROR_LOG_CURRENT_BOOT_CACHE.append(line)
                ERROR_LOG_CURRENT_BOOT_CACHE.append('')
        except Exception:
            pass
        _maybe_rotate_runtime_error_log()
        with open(RUNTIME_ERROR_LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(body)
    except Exception:
        pass
def log_exception_details(tag: str, exc: Exception, extra: dict = None, prefix: str = ""):
    label = prefix or f"[{tag}]"
    try:
        print(f"{label} {exc}", flush=True)
    except Exception:
        pass
    append_runtime_error_log(tag, str(exc), exc=exc, extra=extra, include_traceback=True)
def read_runtime_error_log_tail(max_lines: int = RUNTIME_ERROR_LOG_TAIL_LINES) -> str:
    try:
        max_lines = max(1, int(max_lines))
        with ERROR_LOG_TAIL_CACHE_LOCK:
            cached = list(ERROR_LOG_TAIL_CACHE)[-max_lines:]
        if cached:
            return '\n'.join(cached).strip()
        return _read_runtime_error_log_tail_from_file(max_lines=max_lines)
    except Exception as e:
        append_runtime_error_log('errorlog_read', str(e), exc=e, include_traceback=True)
        return ""
def read_runtime_error_log_current_boot(max_lines: int = 80) -> str:
    try:
        max_lines = max(1, int(max_lines))
        with ERROR_LOG_TAIL_CACHE_LOCK:
            cached = list(ERROR_LOG_CURRENT_BOOT_CACHE)[-max_lines:]
        return '\n'.join(cached).strip()
    except Exception:
        return ""
def _split_runtime_error_records(text: str) -> list:
    try:
        records = []
        current = []
        for line in str(text or '').splitlines():
            if line.startswith('[') and '] [' in line:
                if current:
                    records.append(current)
                current = [line]
            else:
                if current:
                    current.append(line)
        if current:
            records.append(current)
        return records
    except Exception:
        return []
def summarize_runtime_error_tail_v250(text: str, max_items: int = None) -> str:
    try:
        max_items = max(1, int(max_items or globals().get('ERROR_LOG_SUMMARY_MAX_ITEMS', 5)))
        records = _split_runtime_error_records(text)[-max_items:]
        lines = []
        for rec in records:
            if not rec:
                continue
            head = rec[0].strip()[:180]
            exc_type = ''
            exc_msg = ''
            for ln in rec:
                st = ln.strip()
                if st.startswith('- exc_type:'):
                    exc_type = st.replace('- exc_type:', '').strip()[:60]
                elif st.startswith('- exc_msg:'):
                    exc_msg = st.replace('- exc_msg:', '').strip()[:140]
            brief = head
            if exc_type or exc_msg:
                brief += f" / {exc_type or 'Error'}: {exc_msg}"
            lines.append('- ' + brief)
        return '\n'.join(lines).strip()
    except Exception:
        return ""
def build_errorlog_text_v246() -> str:
    return build_errorlog_text_v250(full=False, batch_short=False)
def _threading_runtime_excepthook(args):
    try:
        exc = args.exc_value if getattr(args, 'exc_value', None) is not None else Exception(str(getattr(args, 'exc_type', 'ThreadError')))
        extra = {
            "thread_name": getattr(getattr(args, 'thread', None), 'name', ''),
            "thread_ident": getattr(getattr(args, 'thread', None), 'ident', None),
        }
        append_runtime_error_log('thread_excepthook', '백그라운드 스레드 미처리 예외', exc=exc, extra=extra, include_traceback=True)
    except Exception:
        pass
    try:
        if hasattr(threading, '__excepthook__'):
            threading.__excepthook__(args)
    except Exception:
        pass
def _sys_runtime_excepthook(exc_type, exc_value, exc_tb):
    try:
        tb_text = ''.join(traceback.format_exception(exc_type, exc_value, exc_tb)).strip()
        append_runtime_error_log('sys_excepthook', str(exc_value), exc=exc_value, extra=None, include_traceback=False)
        if tb_text and tb_text != 'NoneType: None':
            with open(RUNTIME_ERROR_LOG_FILE, 'a', encoding='utf-8') as f:
                f.write('- traceback:\n' + tb_text + '\n\n')
    except Exception:
        pass
    try:
        if hasattr(sys, '__excepthook__'):
            sys.__excepthook__(exc_type, exc_value, exc_tb)
    except Exception:
        pass
threading.excepthook = _threading_runtime_excepthook
sys.excepthook = _sys_runtime_excepthook
def _send_single_message(chat_id, text: str, reply_markup=None, reply_to_message_id=None):
    return bot.send_message(
        chat_id=chat_id,
        text=text,
        reply_markup=reply_markup,
        reply_to_message_id=reply_to_message_id,
    )
def send_to_chat_chunks(chat_id, text: str, prefix: str = "", reply_markup=None, reply_to_message_id=None, limit: int = TG_MESSAGE_SOFT_LIMIT):
    body = str(text or "").strip()
    if prefix:
        body = prefix.strip() + ("\n\n" + body if body else "")
    if not body:
        return None
    chunks = split_text_chunks(body, limit=limit)
    last_sent = None
    for idx, chunk in enumerate(chunks, start=1):
        try:
            chunk_markup = reply_markup if idx == 1 else None
            chunk_reply_to = reply_to_message_id if idx == 1 else None
            last_sent = _send_single_message(chat_id, chunk, reply_markup=chunk_markup, reply_to_message_id=chunk_reply_to)
        except Exception as e:
            log_exception_details("telegram_send", e, extra={
                "reply_to_message_id": reply_to_message_id,
                "message_preview": _runtime_safe_preview(chunk),
                "chunk_index": idx,
                "chunk_total": len(chunks),
            }, prefix="[텔레그램 오류]")
            return None
    return last_sent
def send(msg: str, reply_markup=None, reply_to_message_id=None):
    text = str(msg or "").strip()
    if not text:
        return None
    return send_to_chat_chunks(CHAT_ID, text, reply_markup=reply_markup, reply_to_message_id=reply_to_message_id, limit=TG_MESSAGE_SOFT_LIMIT)
def send_text_chunks(text: str, prefix: str = "", reply_markup=None, reply_to_message_id=None, limit: int = TG_MESSAGE_SOFT_LIMIT):
    body = str(text or "").strip()
    if not body and not prefix:
        return None
    return send_to_chat_chunks(CHAT_ID, body, prefix=prefix, reply_markup=reply_markup, reply_to_message_id=reply_to_message_id, limit=limit)
def format_hms(ts: float) -> str:
    try:
        return datetime.fromtimestamp(float(ts), ZoneInfo(TIMEZONE)).strftime("%H:%M:%S")
    except Exception:
        return "--:--:--"
def format_elapsed_text(sec: float) -> str:
    try:
        sec = max(0, int(sec))
    except Exception:
        return "0초"
    m, s = divmod(sec, 60)
    h, m = divmod(m, 60)
    if h > 0:
        return f"{h}시간 {m}분 {s}초"
    if m > 0:
        return f"{m}분 {s}초"
    return f"{s}초"
def format_tier_badge(tier: str) -> str:
    t = str(tier or "B").upper().strip()
    return {
        "S": "🔥 S",
        "A": "⭐ A",
        "B": "👀 B",
        "C": "⛔ C",
    }.get(t, f"👀 {t}")
def format_entry_gap_text(gap_pct: float) -> str:
    gap_pct = safe_float(gap_pct, 0)
    if gap_pct >= 0.70:
        return f"알림가보다 {gap_pct:+.2f}% 늦게 체결"
    if gap_pct >= 0.15:
        return f"알림가보다 {gap_pct:+.2f}% 불리하게 체결"
    if gap_pct <= -0.15:
        return f"알림가보다 {gap_pct:+.2f}% 유리하게 체결"
    return f"알림가와 거의 비슷하게 체결 ({gap_pct:+.2f}%)"
def is_valid_rank_value(v) -> bool:
    try:
        rank = int(safe_float(v, 0))
    except Exception:
        return False
    return 0 < rank < 900
def format_rank_item(label: str, v) -> str:
    if not is_valid_rank_value(v):
        return ""
    return f"{label} {int(safe_float(v, 0))}위"
def get_minute1_sample_note(candles: int) -> str:
    try:
        candles = int(candles)
    except Exception:
        return ""
    if candles <= 0:
        return ""
    if candles <= 2:
        return "minute1 표본 매우 적음"
    if candles < 10:
        return "minute1 표본 적음"
    return ""
def get_minute1_sample_trust(candles: int) -> str:
    try:
        candles = int(candles)
    except Exception:
        return "none"
    if candles <= 0:
        return "none"
    if candles <= 2:
        return "very_low"
    if candles < 5:
        return "low"
    if candles < 10:
        return "mid"
    return "normal"
def get_minute1_sample_confidence_text(candles: int) -> str:
    trust = get_minute1_sample_trust(candles)
    if trust == "very_low":
        return "minute1 표본이 너무 적어서 결과는 참고만"
    if trust == "low":
        return "minute1 표본이 적어서 결과는 약하게 참고"
    if trust == "mid":
        return "minute1 표본이 조금 적어서 과신 금지"
    return ""
def get_reference_high_gap_pct(item: dict) -> float:
    current_price = safe_float(item.get("current_price", item.get("price", 0)), 0)
    reference_high = safe_float(item.get("reference_high", 0), 0)
    if current_price <= 0 or reference_high <= 0:
        return 999.0
    return ((reference_high - current_price) / reference_high) * 100.0
def get_reference_low_rise_pct(item: dict) -> float:
    current_price = safe_float(item.get("current_price", item.get("price", 0)), 0)
    reference_low = safe_float(item.get("reference_low", 0), 0)
    if current_price <= 0 or reference_low <= 0:
        return 0.0
    return ((current_price - reference_low) / reference_low) * 100.0
def get_recent_30m_high_gap_pct(item: dict) -> float:
    snap = ensure_pre_alert_snapshot(item)
    return safe_float(snap.get("below_30m_high_pct", 999), 999)
def get_recent_60m_high_gap_pct(item: dict) -> float:
    return safe_float(item.get("below_60m_high_pct", 999), 999)
def get_short_retest_gap_pct(item: dict) -> float:
    vals = [
        safe_float(item.get("rebreakout_gap_pct", 999), 999),
        get_reference_high_gap_pct(item),
    ]
    usable = [v for v in vals if 0 <= v < 900]
    if not usable:
        return 999.0
    return min(usable)
def get_primary_high_gap_pct(item: dict) -> float:
    profile = get_item_chart_profile(item)
    vals = [
        get_recent_30m_high_gap_pct(item),
        get_reference_high_gap_pct(item),
        safe_float(profile.get("chart_gap_pct", 999), 999),
        get_recent_60m_high_gap_pct(item),
    ]
    usable = [v for v in vals if 0 <= v < 900]
    if not usable:
        return 999.0
    return usable[0]
def get_gap_context_snapshot(item: dict) -> dict:
    return {
        "short_gap_pct": get_short_retest_gap_pct(item),
        "gap_30m_pct": get_recent_30m_high_gap_pct(item),
        "gap_60m_pct": get_recent_60m_high_gap_pct(item),
        "gap_4h_pct": safe_float(item.get("htf_gap_pct", 999), 999),
        "gap_day_pct": safe_float(item.get("daily_gap_pct", 999), 999),
    }
def format_gap_context_line(item_or_row: dict, prefix: str = "- 거리값") -> str:
    if not isinstance(item_or_row, dict):
        return ""
    has_saved_gaps = any(k in item_or_row for k in ["rebreakout_gap_pct", "below_30m_high_pct", "below_60m_high_pct", "htf_gap_pct", "daily_gap_pct"])
    if has_saved_gaps:
        ctx = {
            "short_gap_pct": safe_float(item_or_row.get("rebreakout_gap_pct", item_or_row.get("high_gap_pct", 999)), 999),
            "gap_30m_pct": safe_float(item_or_row.get("below_30m_high_pct", item_or_row.get("below_high", 999)), 999),
            "gap_60m_pct": safe_float(item_or_row.get("below_60m_high_pct", 999), 999),
            "gap_4h_pct": safe_float(item_or_row.get("htf_gap_pct", 999), 999),
            "gap_day_pct": safe_float(item_or_row.get("daily_gap_pct", 999), 999),
        }
    else:
        ctx = get_gap_context_snapshot(item_or_row)
    labels = [
        ("직전단기고점", ctx.get("short_gap_pct", 999)),
        ("최근30분", ctx.get("gap_30m_pct", 999)),
        ("최근60분", ctx.get("gap_60m_pct", 999)),
        ("4시간", ctx.get("gap_4h_pct", 999)),
        ("일봉", ctx.get("gap_day_pct", 999)),
    ]
    parts = []
    for label, value in labels:
        v = safe_float(value, 999)
        if 0 <= v < 900:
            if abs(v) <= 0.000001:
                parts.append(f"{label} 고점 바로 근처")
            else:
                parts.append(f"{label} {v:.2f}%")
    if not parts:
        return ""
    return f"{prefix}: " + " / ".join(parts)
def compute_chart_position_profile(df, current_price: float, lookback: int = CHART_POS_LOOKBACK_1M) -> dict:
    profile = {
        "chart_low": 0.0,
        "chart_high": 0.0,
        "chart_rise_pct": 0.0,
        "chart_gap_pct": 999.0,
        "chart_zone_ratio": -1.0,
        "chart_swing_pct": 0.0,
    }
    try:
        if df is None or len(df) < 8 or current_price <= 0:
            return profile
        recent = df.tail(min(len(df), max(int(lookback), 8)))
        low_v = safe_float(recent["low"].min(), 0)
        high_v = safe_float(recent["high"].max(), 0)
        if low_v <= 0 or high_v <= low_v:
            return profile
        rise_pct = ((current_price - low_v) / low_v) * 100.0
        gap_pct = ((high_v - current_price) / current_price) * 100.0 if current_price > 0 else 999.0
        swing_pct = ((high_v - low_v) / low_v) * 100.0
        zone_ratio = (current_price - low_v) / (high_v - low_v) if high_v > low_v else -1.0
        profile.update({
            "chart_low": low_v,
            "chart_high": high_v,
            "chart_rise_pct": round(rise_pct, 2),
            "chart_gap_pct": round(gap_pct, 2),
            "chart_zone_ratio": round(zone_ratio, 4),
            "chart_swing_pct": round(swing_pct, 2),
        })
    except Exception:
        return profile
    return profile
def apply_chart_position_profile(item: dict, df, lookback: int = CHART_POS_LOOKBACK_1M) -> dict:
    if not isinstance(item, dict):
        return item
    profile = compute_chart_position_profile(df, safe_float(item.get("current_price", item.get("price", 0)), 0), lookback=lookback)
    item.update(profile)
    return item
def get_item_chart_profile(item: dict) -> dict:
    snap = ensure_pre_alert_snapshot(item)
    chart_rise = safe_float(item.get("chart_rise_pct", 0), 0)
    chart_gap = safe_float(item.get("chart_gap_pct", 999), 999)
    chart_zone = safe_float(item.get("chart_zone_ratio", -1), -1)
    chart_swing = safe_float(item.get("chart_swing_pct", 0), 0)
    if chart_rise <= 0:
        chart_rise = max(get_reference_low_rise_pct(item), safe_float(snap.get("from_30m_low_pct", 0), 0))
    if chart_gap >= 900:
        chart_gap = min(get_reference_high_gap_pct(item), safe_float(snap.get("below_30m_high_pct", 999), 999))
    return {
        "chart_rise_pct": chart_rise,
        "chart_gap_pct": chart_gap,
        "chart_zone_ratio": chart_zone,
        "chart_swing_pct": chart_swing,
    }
def is_chart_position_extended(item: dict) -> bool:
    profile = get_item_chart_profile(item)
    chart_ctx = ensure_alert_chart_context(item)
    rise_pct = safe_float(profile.get("chart_rise_pct", 0), 0)
    gap_pct = safe_float(profile.get("chart_gap_pct", 999), 999)
    zone_ratio = safe_float(profile.get("chart_zone_ratio", -1), -1)
    swing_pct = safe_float(profile.get("chart_swing_pct", 0), 0)
    if 0 <= gap_pct <= CHART_POS_LATE_NEAR_HIGH_PCT:
        return True
    if zone_ratio >= CHART_POS_VERY_HIGH_ZONE_RATIO and rise_pct >= 1.8:
        return True
    if zone_ratio >= CHART_POS_HIGH_ZONE_RATIO and rise_pct >= max(2.2, swing_pct * 0.55) and gap_pct <= CHART_POS_EXTENDED_NEAR_HIGH_PCT:
        return True
    if rise_pct >= 5.5 and gap_pct <= 2.0:
        return True
    return False
def is_chart_position_good_for_live(item: dict) -> bool:
    profile = get_item_chart_profile(item)
    chart_ctx = ensure_alert_chart_context(item)
    rise_pct = safe_float(profile.get("chart_rise_pct", 0), 0)
    gap_pct = safe_float(profile.get("chart_gap_pct", 999), 999)
    zone_ratio = safe_float(profile.get("chart_zone_ratio", -1), -1)
    swing_pct = safe_float(profile.get("chart_swing_pct", 0), 0)
    ctx = ensure_alert_chart_context(item)
    snap = ensure_pre_alert_snapshot(item)
    if bool(ctx.get("is_fading_after_spike", False)) and safe_float(snap.get("chg_30m", 0), 0) < 0.40:
        return False
    if str(ctx.get("chart_state_code", "")) == "HIGH_WOBBLE" and safe_float(snap.get("chg_30m", 0), 0) < 0.60:
        return False
    if 0 <= gap_pct <= 0.55:
        return False
    if rise_pct >= CHART_POS_LIVE_MAX_RISE_PCT and gap_pct <= 2.20:
        return False
    if rise_pct >= max(3.00, swing_pct * 0.58) and gap_pct <= 1.60:
        return False
    if zone_ratio >= CHART_POS_HIGH_ZONE_RATIO and rise_pct >= 1.80 and gap_pct <= CHART_POS_EXTENDED_NEAR_HIGH_PCT:
        return False
    if zone_ratio >= CHART_POS_VERY_HIGH_ZONE_RATIO and gap_pct <= 1.60:
        return False
    return True
def is_chart_position_good_for_restart(item: dict) -> bool:
    profile = get_item_chart_profile(item)
    chart_ctx = ensure_alert_chart_context(item)
    rise_pct = safe_float(profile.get("chart_rise_pct", 0), 0)
    gap_pct = safe_float(profile.get("chart_gap_pct", 999), 999)
    zone_ratio = safe_float(profile.get("chart_zone_ratio", -1), -1)
    ctx = ensure_alert_chart_context(item)
    if bool(ctx.get("is_fading_after_spike", False)) and safe_float(ctx.get("recent_pullback_pct", 0), 0) >= ALERT_PULLBACK_RESTART_BLOCK_PCT:
        return False
    if 0 <= gap_pct <= 0.55:
        return False
    if rise_pct >= CHART_POS_RESTART_MAX_RISE_PCT and gap_pct <= 1.4:
        return False
    if rise_pct >= 3.00 and gap_pct <= 1.80:
        return False
    if zone_ratio >= 0.85 and rise_pct >= 2.0 and gap_pct <= 1.2:
        return False
    if zone_ratio >= CHART_POS_HIGH_ZONE_RATIO and rise_pct >= 1.8 and gap_pct <= 0.95:
        return False
    return True
def get_restart_quality_status(item: dict) -> tuple[bool, str]:
    if not is_chart_position_good_for_restart(item):
        return False, "재출발 자리로 보기엔 이미 위쪽"
    snap = ensure_pre_alert_snapshot(item)
    profile = get_item_chart_profile(item)
    chart_ctx = ensure_alert_chart_context(item)
    chg_5 = safe_float(snap.get("chg_5m", 0), 0)
    chg_30 = safe_float(snap.get("chg_30m", 0), 0)
    from_low = safe_float(snap.get("from_30m_low_pct", 0), 0)
    high_gap_pct = get_effective_high_gap_pct(item)
    vol_ratio = safe_float(item.get("vol_ratio", 0), 0)
    leader_score = safe_float(item.get("leader_score", 0), 0)
    rise_pct = safe_float(profile.get("chart_rise_pct", 0), 0)
    zone_ratio = safe_float(profile.get("chart_zone_ratio", -1), -1)
    tags = set(item.get("pattern_tags", []))
    higher_low_hint = bool(snap.get("higher_low_hint", False))
    recovery_profile = get_recovery_profile_snapshot(item)
    recovery_quality = safe_float(recovery_profile.get("recovery_quality_score", 0), 0)
    low_zone_stay = int(recovery_profile.get("low_zone_stay_bars", 0))
    low_reclaim = int(recovery_profile.get("low_zone_reclaim_count", 0))
    turnover_persist = safe_float(recovery_profile.get("turnover_persistence_score", 0), 0)
    recovery_promising = bool(recovery_profile.get("recovery_profile_promising", False))
    if high_gap_pct < 1.15:
        return False, "최근 고점이 너무 가까워서 재출발 자리로 애매"
    if high_gap_pct < 1.50 and max(chg_30, from_low) >= 0.95:
        return False, "조금 반등했어도 이미 많이 올라와서 재출발 자리로 늦음"
    if chg_5 <= 0.20 and chg_30 <= 0.40 and not (recovery_quality >= 1.10 and (low_zone_stay >= 2 or low_reclaim >= 1)):
        return False, "재출발 힘이 아직 거의 안 보임"
    if vol_ratio < 3.20 and max(chg_5, chg_30, from_low) < 1.20 and not recovery_promising:
        return False, "거래량과 반등 힘이 약해서 더 지켜봐야 함"
    if from_low >= RESTART_DISPLAY_MAX_FROM_LOW_PCT and high_gap_pct < 1.70:
        return False, "저점에서 이미 꽤 올라와서 재출발 자리로는 늦음"
    if rise_pct >= RESTART_DISPLAY_MAX_RISE_PCT and high_gap_pct < 2.30:
        return False, "차트상 이미 많이 올라온 뒤라 재출발로 보기 어려움"
    if zone_ratio >= CHART_POS_HIGH_ZONE_RATIO and high_gap_pct < 1.50:
        return False, "상단 구역에 가까워서 재출발 여유가 부족"
    if chg_5 < 0.00 and chg_30 < 1.60 and vol_ratio < 3.80 and turnover_persist < 0.90:
        return False, "방금 흐름이 다시 꺾여서 재출발 후보로는 약함"
    if vol_ratio < 2.20 and turnover_persist < 0.95 and recovery_quality < 1.25:
        return False, "거래량이 너무 약해서 재출발 후보로 올리기엔 부족"
    if leader_score < 1.10 and max(chg_5, chg_30, from_low) < 1.40 and not recovery_promising:
        return False, "주도 힘이 약해서 재출발 후보로 보기엔 부족"
    strength = 0
    if chg_5 >= RESTART_DISPLAY_MIN_5M_PCT:
        strength += 1
    if chg_30 >= 0.28:
        strength += 1
    if 0.22 <= from_low <= RESTART_DISPLAY_MAX_FROM_LOW_PCT:
        strength += 1
    if vol_ratio >= RESTART_DISPLAY_MIN_VOL_RATIO:
        strength += 1
    if leader_score >= RESTART_DISPLAY_MIN_LEADER_SCORE:
        strength += 1
    if high_gap_pct >= RESTART_DISPLAY_MIN_HIGH_GAP_PCT:
        strength += 1
    if max(chg_30, from_low) >= RESTART_DISPLAY_MIN_COMBINED_MOTION_PCT:
        strength += 1
    if higher_low_hint or tags.intersection({"저점높임", "가짜하락회복", "하락복구", "눌림재확인", "저가회복"}):
        strength += 1
    if recovery_quality >= 1.15:
        strength += 1
    if low_zone_stay >= 2 or low_reclaim >= 1:
        strength += 1
    if turnover_persist >= 0.85:
        strength += 1
    if strength < 7:
        return False, "재출발 힘이 아직 약해서 더 확인이 필요"
    return True, ""
def is_restart_candidate_strong(item: dict) -> bool:
    ok, _reason = get_restart_quality_status(item)
    return ok
def compute_pre_alert_snapshot_from_df(df, current_price: float = 0.0) -> dict:
    snap = {
        "chg_5m": 0.0,
        "chg_10m": 0.0,
        "chg_20m": 0.0,
        "chg_30m": 0.0,
        "from_30m_low_pct": 0.0,
        "below_30m_high_pct": 0.0,
        "recent_30m_high_price": 0.0,
        "recent_30m_low_price": 0.0,
        "recent_30m_window_bars": 30,
        "vol_5v20_ratio": 0.0,
        "had_recent_spike": False,
        "higher_low_hint": False,
    }
    try:
        if df is None or len(df) < 12:
            return snap
        close = df["close"].astype(float).dropna()
        volume = df["volume"].astype(float).fillna(0)
        if close.empty:
            return snap
        price = current_price if current_price > 0 else float(close.iloc[-1])
        def back_change(n: int) -> float:
            if len(close) <= n:
                return 0.0
            base = float(close.iloc[-n - 1])
            if base <= 0:
                return 0.0
            return ((price - base) / base) * 100.0
        snap["chg_5m"] = round(back_change(5), 2)
        snap["chg_10m"] = round(back_change(10), 2)
        snap["chg_20m"] = round(back_change(20), 2)
        snap["chg_30m"] = round(back_change(30), 2)
        high_series = df["high"].astype(float).dropna() if "high" in df.columns else close
        low_series = df["low"].astype(float).dropna() if "low" in df.columns else close
        tail_30_high = high_series.tail(min(len(high_series), 31))
        tail_30_low = low_series.tail(min(len(low_series), 31))
        if not tail_30_high.empty and not tail_30_low.empty:
            low30 = float(tail_30_low.min())
            high30 = float(tail_30_high.max())
            snap["recent_30m_low_price"] = round(low30, 8) if low30 > 0 else 0.0
            snap["recent_30m_high_price"] = round(high30, 8) if high30 > 0 else 0.0
            if low30 > 0:
                snap["from_30m_low_pct"] = round(((price - low30) / low30) * 100.0, 2)
            if high30 > 0:
                snap["below_30m_high_pct"] = round(((high30 - price) / high30) * 100.0, 2)
        vol_short = float(volume.tail(min(len(volume), 5)).mean()) if len(volume) >= 1 else 0.0
        vol_long_series = volume.tail(min(len(volume), 25))
        if len(vol_long_series) > 5:
            vol_long = float(vol_long_series.head(len(vol_long_series) - 5).mean())
        else:
            vol_long = float(volume.tail(min(len(volume), 20)).mean()) if len(volume) >= 1 else 0.0
        if vol_long > 0:
            snap["vol_5v20_ratio"] = round(vol_short / vol_long, 2)
        recent_spike_ref = max(
            abs(snap["chg_5m"]),
            abs(snap["chg_10m"]),
            abs(snap["chg_20m"]),
            abs(snap["chg_30m"]),
            snap["from_30m_low_pct"],
        )
        snap["had_recent_spike"] = recent_spike_ref >= 4.0
        lows = list(close.tail(min(len(close), 6)))
        if len(lows) >= 4:
            snap["higher_low_hint"] = lows[-1] >= min(lows[-4:-1])
    except Exception:
        return snap
    return snap
def compute_pre_alert_snapshot(ticker: str, current_price: float = 0.0) -> dict:
    try:
        df = get_ohlcv(ticker, "minute1")
        return compute_pre_alert_snapshot_from_df(df, current_price=current_price)
    except Exception:
        return compute_pre_alert_snapshot_from_df(None, current_price=current_price)
def ensure_pre_alert_snapshot(item: dict) -> dict:
    snap = item.get("pre_alert_snapshot")
    if isinstance(snap, dict):
        return snap
    ticker = item.get("ticker", "")
    current_price = safe_float(item.get("current_price", item.get("price", 0)), 0)
    snap = compute_pre_alert_snapshot(ticker, current_price=current_price)
    item["pre_alert_snapshot"] = snap
    return snap
def compute_low_defense_context_v195(df1, current_price: float = 0.0) -> dict:
    ctx = {
        "low_defense_v2_score": 0.0, "low_defense_v2_label": "저점방어 확인중", "low_defense_v2_grade": "확인중",
        "low_retest_count_v2": 0, "low_near_stay_bars_v2": 0,
        "low_rising_score_v2": 0.0, "low_rising_label_v2": "저점높임 확인중",
        "low_fake_reclaim_score_v2": 0.0, "low_fake_reclaim_label_v2": "저점 이탈 회복 확인중",
        "low_dead_stay_flag_v2": False, "low_break_weak_reclaim_flag_v2": False,
        "low_structure_score_v2": 0.0, "low_structure_summary_v2": "저점 구조 확인중",
        "low_structure_good_v2": False, "low_structure_warning_v2": "",
        "low_ref_price_v2": 0.0, "low_prev_support_v2": 0.0, "low_from_ref_pct_v2": 0.0,
        "low_higher_low_steps_v244": 0, "low_rising_pct_v244": 0.0,
        "low_recent_reclaim_bars_v244": 0, "low_structure_route_v244": "저점 구조 확인중",
        "low_structure_penalty_v244": "",
    }
    try:
        if df1 is None or len(df1) < 12:
            return ctx
        df = df1.tail(min(len(df1), 36)).copy()
        if len(df) < 12:
            return ctx
        price = safe_float(current_price, 0)
        if price <= 0:
            price = safe_float(df["close"].iloc[-1], 0)
        if price <= 0:
            return ctx
        lows = df["low"].astype(float); closes = df["close"].astype(float)
        vols = df["volume"].astype(float).fillna(0) if "volume" in df.columns else None
        low_ref = safe_float(lows.min(), 0)
        if low_ref <= 0:
            return ctx
        from_ref_pct = ((price - low_ref) / low_ref) * 100.0
        recent12 = df.tail(min(len(df), 12)); low12 = safe_float(recent12["low"].min(), low_ref)
        near_low_low = recent12["low"].astype(float) <= low12 * 1.0045
        near_low_close = recent12["close"].astype(float) <= low12 * 1.0075
        near_stay_bars = int((near_low_low | near_low_close).sum())
        retest_count = 0; in_touch = False
        for v in list(near_low_low.astype(bool).values):
            if v and not in_touch:
                retest_count += 1; in_touch = True
            elif not v:
                in_touch = False
        low_rising_score = 0.0
        last6_low = prev6_low = prev12_low = last3_low = 0.0
        try:
            last6_low = safe_float(df.tail(6)["low"].min(), 0)
            prev6_low = safe_float(df.iloc[-12:-6]["low"].min(), 0) if len(df) >= 12 else 0
            prev12_low = safe_float(df.iloc[-24:-12]["low"].min(), 0) if len(df) >= 24 else 0
            last3_low = safe_float(df.tail(3)["low"].min(), 0)
            if prev6_low > 0 and last6_low >= prev6_low * 1.0015:
                low_rising_score += 0.85
            if prev12_low > 0 and prev6_low > 0 and last6_low >= prev6_low * 0.999 and prev6_low >= prev12_low * 1.001:
                low_rising_score += 0.65
            if last3_low > 0 and last6_low > 0 and last3_low >= last6_low * 1.001:
                low_rising_score += 0.35
            try:
                if detect_higher_lows(df, bars=min(len(df), 18)):
                    low_rising_score += 0.45
            except Exception:
                pass
        except Exception:
            pass
        fake_reclaim_score = 0.0; fake_label = "저점 이탈 회복 없음"; weak_reclaim = False; prev_support = 0.0
        try:
            prev_support = safe_float(df.iloc[:-6].tail(18)["low"].min(), 0) if len(df) >= 14 else safe_float(df.iloc[:-3]["low"].min(), 0)
            recent_low = safe_float(df.tail(6)["low"].min(), 0)
            close1 = safe_float(closes.iloc[-1], price); close3_pos = _avg_close_position_ratio(df, 3)
            if prev_support > 0 and recent_low < prev_support * 0.997:
                if close1 >= prev_support * 1.002 and close3_pos >= 0.50:
                    fake_reclaim_score += 0.75; fake_label = "저점 깬 뒤 다시 회복"
                else:
                    weak_reclaim = True; fake_reclaim_score -= 0.55; fake_label = "저점 깼지만 회복 약함"
        except Exception:
            pass
        chg5 = 0.0
        try:
            if len(closes) > 5:
                base5 = safe_float(closes.iloc[-6], 0)
                if base5 > 0:
                    chg5 = ((price - base5) / base5) * 100.0
        except Exception:
            pass
        vol_recent_ratio = 0.0
        try:
            if vols is not None and len(vols) >= 12:
                v3 = safe_float(vols.tail(3).mean(), 0); vbase = safe_float(vols.iloc[:-3].tail(12).mean(), 0)
                if vbase > 0: vol_recent_ratio = v3 / vbase
        except Exception:
            pass
        higher_low_steps_v244 = 0
        low_rising_pct_v244 = 0.0
        recent_reclaim_bars_v244 = 0
        low_structure_penalty_v244 = ""
        try:
            if prev6_low > 0 and last6_low > 0:
                low_rising_pct_v244 = ((last6_low - prev6_low) / prev6_low) * 100.0
                if last6_low >= prev6_low * 1.0010:
                    higher_low_steps_v244 += 1
            if prev12_low > 0 and prev6_low > 0 and prev6_low >= prev12_low * 1.0008:
                higher_low_steps_v244 += 1
            if last3_low > 0 and last6_low > 0 and last3_low >= last6_low * 1.0008:
                higher_low_steps_v244 += 1
            last5 = df.tail(min(len(df), 5))
            for _row in last5.itertuples():
                op = safe_float(getattr(_row, "open", 0), 0)
                cl = safe_float(getattr(_row, "close", 0), 0)
                hi = safe_float(getattr(_row, "high", 0), 0)
                lo = safe_float(getattr(_row, "low", 0), 0)
                close_pos = ((cl - lo) / max(hi - lo, 1e-9)) if hi > lo else 0.0
                if low12 > 0 and lo <= low12 * 1.010 and cl >= low12 * 1.005 and close_pos >= 0.50 and cl >= op * 0.999:
                    recent_reclaim_bars_v244 += 1
            if higher_low_steps_v244 >= 2:
                low_rising_score += 0.30
            if recent_reclaim_bars_v244 >= int(safe_float(globals().get("LOW_STRUCTURE_V244_RECLAIM_BARS_MIN", 2), 2)):
                fake_reclaim_score += 0.20
            if from_ref_pct >= safe_float(globals().get("LOW_STRUCTURE_V244_OVEREXTENDED_FROM_LOW", 4.20), 4.20) and low_rising_score < 0.70:
                low_structure_penalty_v244 = "저점대비 이미 진행됐는데 저점높임 근거 약함"
        except Exception:
            pass
        dead_flag = bool(near_stay_bars >= 7 and from_ref_pct <= 0.35 and abs(chg5) <= 0.12 and vol_recent_ratio < 1.15)
        defense_score = 0.0
        if retest_count >= 3: defense_score += 1.05
        elif retest_count == 2: defense_score += 0.65
        elif retest_count == 1: defense_score += 0.25
        if 2 <= near_stay_bars <= 6: defense_score += min(0.75, 0.12 * near_stay_bars)
        elif near_stay_bars >= 7: defense_score += 0.20
        defense_score += min(1.10, low_rising_score * 0.70) + fake_reclaim_score
        if dead_flag: defense_score -= 0.75
        if weak_reclaim: defense_score -= 0.45
        if from_ref_pct >= 4.50: defense_score -= 0.20
        if higher_low_steps_v244 >= 2:
            defense_score += min(0.45, 0.18 * higher_low_steps_v244)
        if recent_reclaim_bars_v244 >= 2:
            defense_score += 0.22
        if low_structure_penalty_v244:
            defense_score -= 0.28
        defense_score = max(-1.0, min(3.25, defense_score))
        if dead_flag:
            label, grade, warning = "저점 근처 죽은 흐름", "나쁨", "저점은 보이지만 가격과 돈이 못 붙어서 아직 죽은 흐름일 수 있음"
        elif weak_reclaim:
            label, grade, warning = "저점 이탈 후 회복 약함", "주의", "저점 깨고 다시 붙는 힘이 약해서 가짜 회복일 수 있음"
        elif defense_score >= 2.00:
            label, grade, warning = "저점방어 좋음", "좋음", ""
        elif defense_score >= 1.10:
            label, grade, warning = "저점방어 무난", "보통", ""
        elif defense_score >= 0.45:
            label, grade, warning = "저점방어 확인중", "확인중", "저점을 지키는지 한 번 더 확인 필요"
        else:
            label, grade, warning = "저점방어 약함", "약함", "저점 방어 근거가 아직 부족함"
        if low_rising_score >= 1.30: rising_label = "저점이 계단식으로 높아짐"
        elif low_rising_score >= 0.70: rising_label = "저점 조금 높임"
        else: rising_label = "저점높임 약함"
        route_label_v244 = "저점 구조 확인중"
        if dead_flag:
            route_label_v244 = "죽은 저점 주의"
        elif weak_reclaim:
            route_label_v244 = "약한 회복 주의"
        elif (
            defense_score >= safe_float(globals().get("LOW_STRUCTURE_V244_RESTART_SCORE_MIN", 1.45), 1.45)
            and low_rising_score >= safe_float(globals().get("LOW_STRUCTURE_V244_RISING_SCORE_MIN", 0.70), 0.70)
            and from_ref_pct <= safe_float(globals().get("LOW_STRUCTURE_V244_MAX_FROM_LOW_FOR_RESTART", 3.20), 3.20)
        ):
            route_label_v244 = "저점높임 재출발형"
        elif defense_score >= 1.20 and recent_reclaim_bars_v244 >= 2 and from_ref_pct <= 3.60:
            route_label_v244 = "저점방어 재출발형"
        elif defense_score >= 0.80:
            route_label_v244 = "저점방어 관찰형"
        summary = label
        if rising_label != "저점높임 약함": summary += f" / {rising_label}"
        if fake_label != "저점 이탈 회복 없음": summary += f" / {fake_label}"
        if route_label_v244 not in {"저점 구조 확인중", label}:
            summary += f" / {route_label_v244}"
        if low_structure_penalty_v244:
            warning = (warning + " / " if warning else "") + low_structure_penalty_v244
        ctx.update({
            "low_defense_v2_score": round(defense_score, 2), "low_defense_v2_label": label, "low_defense_v2_grade": grade,
            "low_retest_count_v2": int(retest_count), "low_near_stay_bars_v2": int(near_stay_bars),
            "low_rising_score_v2": round(low_rising_score, 2), "low_rising_label_v2": rising_label,
            "low_fake_reclaim_score_v2": round(fake_reclaim_score, 2), "low_fake_reclaim_label_v2": fake_label,
            "low_dead_stay_flag_v2": bool(dead_flag), "low_break_weak_reclaim_flag_v2": bool(weak_reclaim),
            "low_structure_score_v2": round(defense_score, 2), "low_structure_summary_v2": summary,
            "low_structure_good_v2": bool(defense_score >= 1.10 and not dead_flag and not weak_reclaim),
            "low_structure_warning_v2": warning, "low_ref_price_v2": round(low_ref, 8), "low_prev_support_v2": round(prev_support, 8),
            "low_from_ref_pct_v2": round(from_ref_pct, 2),
            "low_higher_low_steps_v244": int(higher_low_steps_v244),
            "low_rising_pct_v244": round(low_rising_pct_v244, 3),
            "low_recent_reclaim_bars_v244": int(recent_reclaim_bars_v244),
            "low_structure_route_v244": route_label_v244,
            "low_structure_penalty_v244": low_structure_penalty_v244,
        })
    except Exception:
        return ctx
    return ctx
def _candle_body_ratio_and_pct(op: float, cl: float, hi: float, lo: float) -> tuple[float, float, float]:
    rng = max(hi - lo, 0.0)
    base = max(abs(op), abs(cl), abs(hi), abs(lo), 1e-9)
    body = abs(cl - op)
    body_ratio = (body / rng) if rng > 0 else 0.0
    body_pct = (body / base) * 100.0
    range_pct = (rng / base) * 100.0
    return body_ratio, body_pct, range_pct
def _is_flat_or_doji_candle(op: float, cl: float, hi: float, lo: float) -> bool:
    body_ratio, body_pct, range_pct = _candle_body_ratio_and_pct(op, cl, hi, lo)
    if range_pct <= CHART_MICRO_RANGE_PCT_MAX:
        return True
    if body_pct <= CHART_FLAT_BODY_PCT_MAX and body_ratio <= CHART_DOJI_BODY_RATIO_MAX:
        return True
    return False
def _last_upper_wick_pct(df) -> float:
    try:
        if df is None or len(df) < 1:
            return 0.0
        row = df.iloc[-1]
        op = safe_float(row.get("open", 0), 0)
        cl = safe_float(row.get("close", 0), 0)
        hi = safe_float(row.get("high", 0), 0)
        base = max(op, cl, 1e-9)
        if hi <= base:
            return 0.0
        return ((hi - base) / base) * 100.0
    except Exception:
        return 0.0
def _last_lower_wick_pct(df) -> float:
    try:
        if df is None or len(df) < 1:
            return 0.0
        row = df.iloc[-1]
        op = safe_float(row.get("open", 0), 0)
        cl = safe_float(row.get("close", 0), 0)
        lo = safe_float(row.get("low", 0), 0)
        base = min(op, cl)
        if lo <= 0 or base <= 0 or lo >= base:
            return 0.0
        return ((base - lo) / base) * 100.0
    except Exception:
        return 0.0
def _avg_candle_body_ratio(df, bars: int = 3) -> float:
    try:
        if df is None or len(df) < 1:
            return 0.0
        recent = df.tail(min(len(df), max(int(bars), 1)))
        vals = []
        for _idx, row in recent.iterrows():
            op = safe_float(row.get("open", 0), 0)
            cl = safe_float(row.get("close", 0), 0)
            hi = safe_float(row.get("high", 0), 0)
            lo = safe_float(row.get("low", 0), 0)
            rng = hi - lo
            if rng <= 0:
                continue
            vals.append(abs(cl - op) / rng)
        if not vals:
            return 0.0
        return float(sum(vals) / len(vals))
    except Exception:
        return 0.0
