    warning = str(item.get("chart_lifecycle_warning", ctx.get("chart_lifecycle_warning", "")) or "").strip()
    bits = [f"- 위치판독: {label}", f"초입 {early:.2f}", f"재출발 {restart:.2f}", f"늦음위험 {late:.2f}"]
    if gap < 900:
        bits.append(f"고점거리 {gap:.2f}%")
