    upper = safe_float(item.get("current_candle_upper_wick_pct", ctx.get("current_candle_upper_wick_pct", 0)), 0)
    lower = safe_float(item.get("current_candle_lower_wick_pct", ctx.get("current_candle_lower_wick_pct", 0)), 0)
