    bear_streak = int(safe_float(item.get("bearish_streak_5", 0), 0))
    strong_bulls = int(safe_float(item.get("strong_bullish_count_5", 0), 0))
    pullback = safe_float(item.get("pullback_pct_18", 0), 0)
    recovery = safe_float(item.get("recovery_from_low_pct", 0), 0)
    recovery_speed = safe_float(item.get("recovery_speed_pct", 0), 0)
    pullback_bars = int(safe_float(item.get("pullback_duration_bars", 0), 0))
    comp_score = safe_float(item.get("compression_score", 0), 0)
    re_text = format_rebreakout_stat_text(item, compact=compact)
