def _paper_v259_group_lines(rows: list, field: str, title: str, max_groups: int = 8) -> list:
    groups = {}
    for r in list(rows or []):
        key = str((r or {}).get(field, "") or "-")
        groups.setdefault(key, []).append(r)
    if not groups:
        return [f"[{title}] 거래 없음"]
    out = [f"[{title}]"]
    items = sorted(groups.items(), key=lambda kv: len(kv[1]), reverse=True)[:max_groups]
