def _v286_join(items, limit=10, empty='없음'):
    try:
        arr=list(items or [])[:max(1,int(limit))]
        return ', '.join(str(x) for x in arr) if arr else empty
    except Exception:
        return empty
def _v286_format_app_item(ticker, info=None, include_reason=False):
    try:
        t=_v286_norm(ticker)
        if not isinstance(info,dict): return t
        row=info.get('row') if isinstance(info.get('row'),dict) else {}
        frames='/'.join(list(info.get('frames') or [])[:5])
        best=safe_float(info.get('best_change',0),0)
        out=f"{t} {best:+.2f}%" + (f"·{frames}" if frames else '')
        src=str(row.get('cache_source','') or row.get('latest_price_source',''))
        if 'snapshot3m' in src: out+='·snapshot3m'
        elif str(row.get('latest_price_source',''))=='ws_trade': out+='·체결보완'
        cs=str(row.get('candle_summary_v286','') or _v286_candle_summary(row))
        if cs:
            PAPER_V286_STATS['candle_summary']=int(safe_float(PAPER_V286_STATS.get('candle_summary',0),0))+1
            out += f"·{cs}"
        if include_reason:
            reason=str(row.get('exclude_reason_v286','') or _v286_exclude_reason(row))
            if reason:
                PAPER_V286_STATS['reason_attached']=int(safe_float(PAPER_V286_STATS.get('reason_attached',0),0))+1
                out += f" / 제외이유 {reason}"
        return out
    except Exception:
        return str(ticker)
def _v286_app_signal_note(ticker):
    try:
        t=_v286_norm(ticker)
        data=_v286_get_compare_data()
        row=(data.get('row_by_ticker') or {}).get(t)
        info=(data.get('app_counts') or {}).get(t)
        if isinstance(info,dict):
            PAPER_V286_STATS['signal_hint']=int(safe_float(PAPER_V286_STATS.get('signal_hint',0),0))+1
            return '- 매수 후보에는 없음 / 봇계산 앱식순위: ' + _v286_format_app_item(t, info) + ' / 매수신호 아님'
        if isinstance(row,dict):
            c1=safe_float(row.get('change_1',0),0); c3=safe_float(row.get('change_3',0),0)
            r1='가능' if row.get('change_1_ready') else '기준가부족'; r3='가능' if row.get('change_3_ready') else '기준가부족'
            src=str(row.get('latest_price_source','') or row.get('cache_source','') or '-')
            return f"- 매수 후보에는 없음 / 전체 앱식 히스토리 있음: 1분 {c1:+.2f}%({r1}) / 3분 {c3:+.2f}%({r3}) / 최신가 {src} / 매수신호 아님"
        return '- 매수 후보에는 없음 / 전체 앱식 히스토리에도 최근 표본 없음 / 티커명 또는 상장명 확인 필요'
    except Exception:
        return ''
