def _paper_v301_easy_reason(v: str) -> str:
    raw = str(v or "-")
    low = raw.lower()
    pairs = [
        ("early_pending_cancel", "대기 중 신호악화 취소"),
        ("entry_precheck_cancel", "진입 직전 힘빠짐 취소"),
        ("now_prepare_cancel", "바로 진입 준비 중 힘빠짐 취소"),
        ("pending_timeout", "진입 대기 시간초과"),
        ("chase_over", "추격금지 초과"),
        ("preview_command_only", "관심 후보라 기록만"),
        ("v276_prepare_sell", "진입준비 후 매도반전"),
        ("v276_prepare_high", "진입준비 후 고점유지 실패"),
        ("now_recheck_exit", "바로 진입 후 힘 부족 정리"),
        ("open_recheck_exit", "보유 중 신호악화 정리"),
        ("protect_recheck_exit", "수익 후 신호약화 보호청산"),
        ("stop_loss", "손절"),
        ("protect_stop_after_tp", "수익보호 손절"),
        ("time_exit", "시간 만료 청산"),
        ("slow_no_progress_exit", "시간 대비 힘 부족 정리"),
        ("tp3_full_exit", "3차 익절 완료"),
        ("partial_all_taken", "분할익절 완료"),
    ]
    for needle, label in pairs:
        if needle in low:
            return label
    return raw.replace("strict_signal", "실전급 후보").replace("loose_threshold_test", "문턱 낮춘 실험 후보")
def _paper_v301_key(prefix: str, row: dict) -> str:
    row = row if isinstance(row, dict) else {}
    ticker = str(row.get("ticker", "?") or "?").upper().strip()
    pid = str(row.get("id", row.get("pos_id", "")) or "")
    if prefix == "entry":
        ts = safe_float(row.get("entered_ts", row.get("created_ts", 0)), 0)
        price = safe_float(row.get("entry_price", 0), 0)
    else:
        ts = safe_float(row.get("close_ts", row.get("cancel_ts", 0)), 0)
        price = safe_float(row.get("close_price", row.get("last_price", 0)), 0)
    return f"{prefix}:{ticker}:{pid}:{int(ts)}:{round(price, 8)}"
def paper_alert_sync_v301():
    if not PAPER_ALERTS_V301_ON:
        return
    _v301_inc("sync_calls")
    try:
        now_ts = time.time()
        state = _paper_v301_load_alert_state()
        sent_entries = set(str(x) for x in (state.get("sent_entries") or []))
        sent_exits = set(str(x) for x in (state.get("sent_exits") or []))
        new_entry_keys = []
        new_exit_keys = []
        start_guard = safe_float(globals().get("BOT_START_TS", now_ts), now_ts) - 10
        with PAPER_STATE_LOCK:
            open_rows = [dict(p) for p in (paper_positions or {}).values()
                         if isinstance(p, dict) and str(p.get("status", "")).upper() == "OPEN"]
            logs = [dict(r) for r in list(paper_trade_log or [])[-80:] if isinstance(r, dict)]
        for pos in open_rows:
            entered_ts = safe_float(pos.get("entered_ts", pos.get("created_ts", 0)), 0)
            if entered_ts <= 0 or entered_ts < start_guard:
                continue
            key = _paper_v301_key("entry", pos)
            if key not in sent_entries:
                _paper_v301_send_entry_alert(pos)
                sent_entries.add(key)
                new_entry_keys.append(key)
        for row in logs:
            if str(row.get("status", "")).upper() != "CLOSED":
                continue
            close_ts = safe_float(row.get("close_ts", 0), 0)
            if close_ts <= 0 or close_ts < start_guard:
                continue
            key = _paper_v301_key("exit", row)
            if key not in sent_exits:
                _paper_v301_send_exit_alert(row)
                sent_exits.add(key)
                new_exit_keys.append(key)
        if new_entry_keys or new_exit_keys:
            state["sent_entries"] = list(sent_entries)[-PAPER_ALERT_MAX_KEYS_V301:]
            state["sent_exits"] = list(sent_exits)[-PAPER_ALERT_MAX_KEYS_V301:]
            _paper_v301_save_alert_state(state)
    except Exception as e:
        try:
            append_runtime_error_log("paper_alert_sync_v301", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
def _paper_flow_rows_v301(minutes: int = PAPER_FLOW_DEFAULT_MINUTES_V301):
    now_ts = time.time()
    start = now_ts - max(1, int(minutes)) * 60
    with PAPER_STATE_LOCK:
        pos_rows = [dict(p) for p in (paper_positions or {}).values() if isinstance(p, dict)]
        log_rows = [dict(r) for r in list(paper_trade_log or []) if isinstance(r, dict)]
    current_pending = [p for p in pos_rows if str(p.get("status", "")).upper() == "PENDING"]
    current_open = [p for p in pos_rows if str(p.get("status", "")).upper() == "OPEN"]
    registered_recent = []
    for p in pos_rows:
        if safe_float(p.get("created_ts", 0), 0) >= start:
            registered_recent.append(p)
    for r in log_rows:
        if safe_float(r.get("created_ts", 0), 0) >= start:
            registered_recent.append(r)
    entered_recent = []
    for p in current_open:
        if safe_float(p.get("entered_ts", p.get("created_ts", 0)), 0) >= start:
            entered_recent.append(p)
    for r in log_rows:
        if safe_float(r.get("entered_ts", 0), 0) >= start and str(r.get("status", "")).upper() == "CLOSED":
            entered_recent.append(r)
    closed_recent = [r for r in log_rows if str(r.get("status", "")).upper() == "CLOSED" and safe_float(r.get("close_ts", 0), 0) >= start]
    cancel_recent = [r for r in log_rows if str(r.get("status", "")).upper() == "CANCELLED" and safe_float(r.get("close_ts", r.get("cancel_ts", 0)), 0) >= start]
    return {
        "minutes": minutes,
        "start": start,
        "now": now_ts,
        "positions": pos_rows,
        "logs": log_rows,
        "current_pending": current_pending,
        "current_open": current_open,
        "registered_recent": registered_recent,
        "entered_recent": entered_recent,
        "closed_recent": closed_recent,
        "cancel_recent": cancel_recent,
    }
