def _v304_errorlog_summary_from_text(body: str) -> list:
    lines = []
    try:
        txt = str(body or "")
        cur_new_none = "현재 부팅 이후 새 오류 없음" in txt
        turnover_hits = txt.count("'turnover_score'") + txt.count("turnover_score")
        v302_hits = txt.count("v302_cancel") + txt.count("PAPER_CANCEL_WATCH")
        if cur_new_none:
            lines.append("- 현재 부팅 이후 새 오류 없음: 기본 화면에서는 과거 tail만 참고")
        if turnover_hits:
            lines.append(f"- 과거/현재 tail에 turnover_score 관련 기록 {turnover_hits}건 감지: v304 허브 row 표준화로 재발 방지 대상")
        if v302_hits:
            lines.append(f"- v302 취소추적 관련 기록 {v302_hits}건 감지: v303 저장 보정 + v304 분류 대상")
        if not lines:
            lines.append("- 현재 기본 화면 기준으로 새로 분류할 핵심 오류 없음")
    except Exception:
        lines = ["- 오류 분류 요약 생성 실패"]
    return lines
def build_errorlog_text_v250(full: bool = False, batch_short: bool = False) -> str:
    base = str(_BASE_BUILD_ERRORLOG_TEXT_V304(full=full, batch_short=batch_short)) if callable(_BASE_BUILD_ERRORLOG_TEXT_V304) else ""
    try:
        if full:
            return base
        if "🧩 v2.5.304 오류 분류" not in base:
            summary = _v304_errorlog_summary_from_text(base)
            base = base.rstrip() + "\n\n🧩 v2.5.304 오류 분류\n" + "\n".join(summary)
            _v304_inc("errorlog_classified", "errorlog 기본 분류 표시")
    except Exception:
        pass
    return base
