def _v306_direct_entry_risk_reason(row: dict, cls: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        cls = cls if isinstance(cls, dict) else {}
        grade = str(cls.get("grade", row.get("grade", "")) or "").upper().strip()
        if grade != "BUY_OK":
            return ""
        score = safe_float(cls.get("score", row.get("score", 0)), 0)
        trade_count = int(safe_float(cls.get("trade_count", row.get("trade_count", row.get("trade_count_60s", 0))), 0))
        buy_ratio = safe_float(cls.get("buy_ratio", row.get("buy_ratio", row.get("buy_ratio_60s", 0))), 0)
        pressure = safe_float(row.get("current_candle_pressure_score", row.get("candle_pressure_score", cls.get("current_candle_pressure_score", 0))), 0)
        text_blob = _v306_row_text_blob(row, cls)
        candle_weak = any(x in text_blob for x in ["막판강밀림", "막판 밀림", "위꼬리강밀림", "위꼬리 밀림", "현재봉 밀림", "신호악화"])
        sell_heavy = any(x in text_blob for x in ["매도우세", "매도 우세", "돈은 크지만 매도우세"])
        if score > 0 and score < V306_PAPER_DIRECT_LOW_SCORE_HARD:
            _v306_inc("paper_direct_low_score_block", f"낮은점수 바로진입 보류 {score:.2f}")
            return f"점수 {score:.2f}라 바로진입보다 준비대기가 맞음"
        if trade_count > 0 and trade_count < V306_PAPER_DIRECT_TINY_SAMPLE_COUNT:
            _v306_inc("paper_direct_thin_sample_block", f"체결표본 매우적음 {trade_count}건")
            return f"체결 {trade_count}건뿐이라 매수비율 과신 금지"
        if score > 0 and score < V306_PAPER_DIRECT_MIN_SCORE and trade_count < V306_PAPER_DIRECT_LOW_SCORE_SAMPLE_MIN:
            _v306_inc("paper_direct_low_score_block", f"점수/표본 부족 {score:.2f}/{trade_count}건")
            return f"점수 {score:.2f}·체결 {trade_count}건이라 바로진입 보류"
        if pressure >= V306_PAPER_DIRECT_PRESSURE_BLOCK or candle_weak or sell_heavy:
            _v306_inc("paper_direct_candle_block", f"현재봉/매도우세 보류 {pressure:.2f}")
            return "현재봉 밀림/매도우세가 있어 바로진입 금지"
        if trade_count > 0 and trade_count < V306_PAPER_DIRECT_MIN_TRADE_COUNT and buy_ratio >= 80:
            _v306_inc("paper_direct_thin_sample_block", f"매수비율 표본부족 {trade_count}건/{buy_ratio:.0f}%")
            return f"매수비율 {buy_ratio:.0f}%지만 체결 {trade_count}건이라 표본 부족"
        return ""
    except Exception as e:
        try:
            append_runtime_error_log("v306_direct_entry_risk", str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return ""
