        txt = _v307_text_blob(row, cls)
        has_sell_heavy = any(x in txt for x in ["매도우세", "매도 우세", "돈은 크지만 매도우세"])
        has_candle_weak = any(x in txt for x in ["막판강밀림", "막판 밀림", "위꼬리강밀림", "위꼬리 밀림", "현재봉 밀림", "위꼬리/현재봉 밀림"])
        has_flash = any(x in txt for x in ["반짝형", "식는중", "반짝/식는중"])
