V311_MIN_KEEP_RATIO = 0.45          # 최고 상승분의 최소 45% 이상 유지하면 완전 사망은 아님
V311_STRONG_MISS_UP = 1.50          # 취소 후 +1.5% 이상은 재감시 후보
V311_BIG_MISS_UP = 3.00             # +3% 이상은 강한 놓침
V311_REENTRY_CUR_UP = 0.70          # 현재도 +0.7% 이상 남아 있으면 재감시 가치
V311_DIRECT_COMMON_SCORE = 6.80
V311_DIRECT_COMMON_TRADES = 10
V311_DIRECT_COMMON_BUY_RATIO = 52
V311_MIN_TURNOVER_EOK = 1.00
def _v311_inc(key: str, note: str = ""):
    try:
        if key in V311_STATS:
            V311_STATS[key] = int(safe_float(V311_STATS.get(key, 0), 0)) + 1
        if note:
            V311_STATS["last_note"] = str(note)[:220]
    except Exception:
        pass
def _v311_get(row: dict, cls: dict, *keys, default=0):
    try:
        row = row if isinstance(row, dict) else {}
        cls = cls if isinstance(cls, dict) else {}
        for src in (cls, row):
            for k in keys:
                if isinstance(src, dict) and src.get(k) not in (None, ""):
                    return src.get(k)
    except Exception:
        pass
    return default
def _v311_text(row: dict, cls: dict = None) -> str:
    try:
        base = _v310_text_blob(row, cls) if callable(globals().get('_v310_text_blob')) else ""
    except Exception:
        base = ""
    try:
        row = row if isinstance(row, dict) else {}
        cls = cls if isinstance(cls, dict) else {}
        extra = []
        for src in (row, cls):
            if not isinstance(src, dict):
                continue
            for k in ("close_reason", "cancel_reason", "register_reason", "easy_lane", "lane", "decision", "v310_route_tag"):
                v = src.get(k)
                if v:
                    extra.append(str(v))
        return (base + " " + " ".join(extra)).strip()
    except Exception:
        return base
def _v311_turnover_eok(row: dict, cls: dict) -> float:
    v = _v311_get(row, cls, "turnover_eok", "turnover_recent_eok", "turnover_krw_eok", default=0)
    eok = safe_float(v, 0)
    if eok > 0:
        return eok
    won = safe_float(_v311_get(row, cls, "turnover", "turnover_recent", "turnover_krw", "money_krw", default=0), 0)
    if won > 10000000:
        return won / 100000000.0
    return eok
def _v311_common_context(row: dict, cls: dict) -> dict:
    row = row if isinstance(row, dict) else {}
    cls = cls if isinstance(cls, dict) else {}
    txt = _v311_text(row, cls)
    ch1 = safe_float(_v311_get(row, cls, "change_1m", "change_1", "chg_1m", default=0), 0)
    ch3 = safe_float(_v311_get(row, cls, "change_3m", "change_3", "chg_3m", default=0), 0)
    ch5 = safe_float(_v311_get(row, cls, "change_5m", "change_5", "chg_5m", default=0), 0)
    score = safe_float(_v311_get(row, cls, "score", "final_score", default=0), 0)
    trades = int(safe_float(_v311_get(row, cls, "trade_count_60s", "trade_count", "trades_60s", default=0), 0))
    buy_ratio = safe_float(_v311_get(row, cls, "buy_ratio_60s", "buy_ratio", default=0), 0)
    pressure = safe_float(_v311_get(row, cls, "current_candle_pressure_score", "candle_pressure_score", default=0), 0)
    live = safe_float(_v311_get(row, cls, "current_candle_live_score", "candle_live_score", default=0), 0)
    turnover_eok = _v311_turnover_eok(row, cls)
    max_up = safe_float(_v311_get(row, cls, "max_up_after_cancel_pct", "cancel_after_max_pct", "missed_max_pct", default=0), 0)
    cur_up = safe_float(_v311_get(row, cls, "current_after_cancel_pct", "cancel_after_current_pct", "missed_current_pct", default=0), 0)
    keep_ratio = (cur_up / max_up) if max_up > 0 else 0
    weak_words = ["위꼬리강", "막판강밀림", "현재봉 밀림", "매도우세", "돈은 크지만 매도", "반짝/식는중", "고점 앞 밀림"]
    weak_now = any(w in txt for w in weak_words) or pressure >= 1.20
    trend_count = sum(1 for x in (ch1, ch3, ch5) if x >= 0.10)
    common_confirm = (
        trend_count >= 2
        and turnover_eok >= V311_MIN_TURNOVER_EOK
        and (trades >= 5 or buy_ratio >= 70 or turnover_eok >= 10)
        and not weak_now
    )
    return {
        "txt": txt,
        "ch1": ch1, "ch3": ch3, "ch5": ch5,
        "score": score, "trades": trades, "buy_ratio": buy_ratio,
        "pressure": pressure, "live": live, "turnover_eok": turnover_eok,
        "max_up": max_up, "cur_up": cur_up, "keep_ratio": keep_ratio,
        "weak_now": weak_now, "trend_count": trend_count,
        "common_confirm": common_confirm,
    }
def _v311_direct_guard_reason(row: dict, cls: dict) -> str:
    try:
        cls = cls if isinstance(cls, dict) else {}
        grade = str(cls.get("grade", row.get("grade", "")) or "").upper().strip() if isinstance(row, dict) else str(cls.get("grade", "")).upper().strip()
        if grade != "BUY_OK":
            return ""
        c = _v311_common_context(row, cls)
        if c["score"] >= V311_DIRECT_COMMON_SCORE and c["trades"] >= V311_DIRECT_COMMON_TRADES and c["buy_ratio"] >= V311_DIRECT_COMMON_BUY_RATIO and c["common_confirm"]:
            _v311_inc("common_confirm_pass", f"바로진입 공통확인 통과 {row.get('ticker', cls.get('ticker','?')) if isinstance(row, dict) else cls.get('ticker','?')}")
            return ""
        reasons = []
        if c["score"] < V311_DIRECT_COMMON_SCORE:
            reasons.append(f"점수 {c['score']:.2f}")
        if c["trades"] < V311_DIRECT_COMMON_TRADES:
            reasons.append(f"체결 {c['trades']}건")
        if c["buy_ratio"] and c["buy_ratio"] < V311_DIRECT_COMMON_BUY_RATIO:
            reasons.append(f"매수비율 {c['buy_ratio']:.0f}%")
        if c["trend_count"] < 2:
            reasons.append("1m/3m/5m 동시유지 부족")
        if c["weak_now"]:
            reasons.append("현재봉 밀림/매도우세")
        if not reasons:
            reasons.append("공통 추세확인 부족")
        _v311_inc("weak_direct_to_prepare", "바로진입→준비 " + ", ".join(reasons[:3]))
        return "공통 추세확인 부족: " + ", ".join(reasons[:4])
    except Exception as e:
        try: append_runtime_error_log("v311_direct_guard_reason", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return ""
def _v311_cancel_reentry_decision(row: dict, cls: dict, lane: str, reason: str) -> tuple[str, str]:
    try:
        c = _v311_common_context(row, cls)
        txt = c["txt"] + " " + str(lane or "") + " " + str(reason or "")
        if c["max_up"] < V311_STRONG_MISS_UP:
            return "", ""
        has_cancel_context = any(x in txt for x in ["취소", "놓침", "추격금지", "힘빠짐", "chase", "cancel", "miss"])
        if not has_cancel_context:
            has_cancel_context = c["max_up"] >= V311_BIG_MISS_UP
        if not has_cancel_context:
            return "", ""
        if c["max_up"] >= V311_BIG_MISS_UP and (c["cur_up"] <= 0 or c["keep_ratio"] < V311_MIN_KEEP_RATIO or c["weak_now"]):
            _v311_inc("strong_miss_pullback_watch", f"강한놓침 눌림감시 {row.get('ticker', cls.get('ticker','?')) if isinstance(row, dict) else cls.get('ticker','?')}/{c['max_up']:+.2f}%")
            return "pullback_watch", f"취소 후 +{c['max_up']:.2f}% 갔지만 현재 추격은 위험. 눌림 재진입 감시"
        if c["cur_up"] >= V311_REENTRY_CUR_UP and c["keep_ratio"] >= V311_MIN_KEEP_RATIO:
            _v311_inc("strong_miss_reentry_watch", f"강한놓침 복귀감시 {row.get('ticker', cls.get('ticker','?')) if isinstance(row, dict) else cls.get('ticker','?')}/{c['cur_up']:+.2f}%")
            return "reentry_watch", f"취소 후 +{c['max_up']:.2f}% / 현재 +{c['cur_up']:.2f}% 유지. 재감시 복귀 후보"
        return "", ""
    except Exception as e:
        try: append_runtime_error_log("v311_cancel_reentry_decision", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return "", ""
