def _v322_reason_is_soft_profit(reason: str) -> bool:
    r = str(reason or "").lower()
    soft_words = ["protect", "profit", "신호약화", "보호", "익절", "weakening"]
    hard_words = ["hard", "stop_loss", "fast_cut", "손절", "v322_common", "v322_weak", "v322_strong"]
    return any(w in r for w in soft_words) and not any(w in r for w in hard_words)
def _v322_closed_rows(hours: float = None):
    try:
        rows = _paper_closed_logs_v258(include_cancelled=False)
        rows = list(rows or [])
        if hours is not None:
            cutoff = _v322_now() - safe_float(hours, 6.0) * 3600
            rows = [r for r in rows if safe_float(r.get("close_ts", 0), 0) >= cutoff]
        rows.sort(key=lambda r: safe_float(r.get("close_ts", 0), 0), reverse=True)
        return rows
    except Exception:
        return []
def _v322_stats_line(label: str, rows: list) -> str:
    try:
        return _paper_stats_line_v258(label, rows)
    except Exception:
        try:
            n = len(rows or [])
            wins = sum(1 for r in rows if safe_float(r.get("pnl_pct", 0), 0) > 0)
            total = sum(safe_float(r.get("pnl_pct", 0), 0) for r in rows or [])
            return f"📊 {label}\n- 거래: {n}전 {wins}승 {n-wins}패\n- 누적: {total:+.2f}%"
        except Exception:
            return f"📊 {label}\n- 거래: 없음"
def _v322_recovery_rate_line(row: dict) -> str:
    try:
        pnl = safe_float(row.get("pnl_pct", 0), 0)
        best = safe_float(row.get("max_up_pct", row.get("max_profit_pct", 0)), 0)
        worst = safe_float(row.get("min_down_pct", 0), 0)
        if best > 0 and pnl > 0:
            rec = max(0.0, min(999.0, (pnl / best) * 100.0))
            return f"최고 {best:+.2f}% / 청산 {pnl:+.2f}% / 회수율 {rec:.0f}%"
        if best > 0 and pnl <= 0:
            return f"최고 {best:+.2f}% / 청산 {pnl:+.2f}% / 회수 실패"
        return f"최고 {best:+.2f}% / 최저 {worst:+.2f}% / 청산 {pnl:+.2f}%"
    except Exception:
        return "회수율 계산불가"
