def _v302_recent_closed_lines(limit: int = 4) -> list:
    try:
        rows = _v322_closed_rows()
        out = []
        for i, r in enumerate(rows[:max(1, int(limit))], start=1):
            ticker = str(r.get("ticker", "?") or "?").upper()
            pnl = safe_float(r.get("pnl_pct", 0), 0)
            reason = _paper_v301_easy_reason(r.get("close_reason", "")) if callable(globals().get("_paper_v301_easy_reason")) else str(r.get("close_reason", ""))
            lane = _paper_v301_easy_lane(r.get("lane", "")) if callable(globals().get("_paper_v301_easy_lane")) else str(r.get("lane", ""))
            out.append(f"{i}. {ticker} / {pnl:+.2f}% / {reason} / {lane} / {_v322_recovery_rate_line(r)}")
        if out:
            _v322_inc("recovery_lines")
            return out
    except Exception:
        pass
    if callable(_BASE_V302_RECENT_CLOSED_LINES_V322):
        return _BASE_V302_RECENT_CLOSED_LINES_V322(limit=limit)
    return []
