def _v327_current_price_for_pos(ticker: str, pos: dict) -> float:
    try:
        price = 0.0
        if ticker and callable(globals().get("get_price_for_tracking")):
            p2 = get_price_for_tracking(ticker, caller="v327_preclose", allow_api_fallback=False)
            if safe_float(p2, 0) > 0:
                price = safe_float(p2, 0)
        if price <= 0:
            price = safe_float((pos or {}).get("last_price", (pos or {}).get("current_price", 0)), 0)
        return price
    except Exception:
        return safe_float((pos or {}).get("last_price", (pos or {}).get("current_price", 0)), 0)
try:
    _BASE_V322_PRECLOSE_V327 = globals().get('_v322_preclose_positions_once')
except Exception:
    _BASE_V322_PRECLOSE_V327 = None
def _v322_preclose_positions_once():
    now_ts = _v322_now() if callable(globals().get("_v322_now")) else time.time()
    closed_ids = set()
    try:
        with PAPER_STATE_LOCK:
            items = [(pid, dict(pos)) for pid, pos in (paper_positions or {}).items() if isinstance(pos, dict) and str(pos.get("status", "")).upper() == "OPEN"]
    except Exception:
        items = []
    for pid, pos in items:
        try:
            ticker = str(pos.get("ticker", "") or "").upper().strip()
            if not ticker:
                continue
            cls = _v327_route_class(pos)
            price = _v327_current_price_for_pos(ticker, pos)
            if price <= 0:
                continue
            pnl = _v322_current_pnl(pos, price) if callable(globals().get("_v322_current_pnl")) else safe_float(pos.get("pnl_pct", 0), 0)
            best = _v322_max_profit(pos, pnl) if callable(globals().get("_v322_max_profit")) else max(pnl, safe_float(pos.get("max_up_pct", 0), 0))
            strong = _v327_is_strong_class(cls)
            if strong:
                _v327_inc("strong_preclose_seen", f"강한라인 preclose {ticker}/{cls}")
                trail_floor = max(safe_float(globals().get("V322_STRONG_BREAKEVEN_FLOOR", 0.08), 0.08), best * safe_float(globals().get("V322_STRONG_TRAIL_KEEP_RATIO", 0.55), 0.55))
                if best >= safe_float(globals().get("V322_STRONG_TRAIL_AFTER", 0.95), 0.95) and pnl <= trail_floor:
                    _v327_inc("strong_trailing_hard_guard", f"v327 트레일링 {ticker}/{pnl:+.2f} 최고{best:+.2f}")
                    try:
                        if callable(globals().get("_v322_close_position")):
                            _v322_close_position(pid, pos, price, "v327_strong_trailing_hard_guard", now_ts)
                            closed_ids.add(pid)
                            continue
                    except Exception as e:
                        try: append_runtime_error_log("v327_trailing_close", str(e), exc=e, include_traceback=False)
                        except Exception: pass
                floor = safe_float(globals().get("V322_STRONG_BREAKEVEN_FLOOR", 0.08), 0.08)
                hard_floor = max(0.03, floor)
                if best >= safe_float(globals().get("V322_STRONG_BREAKEVEN_AFTER", 0.50), 0.50) and pnl <= hard_floor:
                    if pnl < 0:
                        _v327_inc("strong_late_guard", f"v327 늦은 본전보호 {ticker}/{pnl:+.2f} 최고{best:+.2f}")
                    else:
                        _v327_inc("strong_breakeven_hard_guard", f"v327 본전보호 {ticker}/{pnl:+.2f} 최고{best:+.2f}")
                    try:
                        if callable(globals().get("_v322_close_position")):
                            _v322_close_position(pid, pos, price, "v327_strong_breakeven_hard_guard", now_ts)
                            closed_ids.add(pid)
                            continue
                    except Exception as e:
                        try: append_runtime_error_log("v327_breakeven_close", str(e), exc=e, include_traceback=False)
                        except Exception: pass
            elif _v327_is_common_class(cls):
                _v327_inc("common_bridge")
            elif _v327_is_weak_class(cls):
                _v327_inc("weak_bridge")
        except Exception as e:
            try: append_runtime_error_log("v327_preclose", str(e), exc=e, include_traceback=False)
            except Exception: pass
    if callable(_BASE_V322_PRECLOSE_V327):
        try:
            return _BASE_V322_PRECLOSE_V327()
        except Exception as e:
            try: append_runtime_error_log("v327_base_preclose", str(e), exc=e, include_traceback=False)
            except Exception: pass
    return None
def _v325_exit_diag(pos: dict, price: float, reason: str = "") -> dict:
    try:
        p = dict(pos or {})
        pnl = _v322_current_pnl(p, safe_float(price, 0)) if callable(globals().get("_v322_current_pnl")) else safe_float(p.get("pnl_pct", 0), 0)
        best = _v322_max_profit(p, pnl) if callable(globals().get("_v322_max_profit")) else max(pnl, safe_float(p.get("max_up_pct", 0), 0))
        cls = _v327_route_class(p)
        common = _v327_is_common_class(cls)
        strong = _v327_is_strong_class(cls)
        weak = _v327_is_weak_class(cls) and not strong and not common
        opened = _v322_open_ts(p) if callable(globals().get("_v322_open_ts")) else safe_float(p.get("opened_ts", p.get("entered_ts", 0)), 0)
        hold = max(0.0, (_v322_now() if callable(globals().get("_v322_now")) else time.time()) - opened) if opened > 0 else 0.0
        should_common = bool(common and pnl <= safe_float(globals().get("V322_FAST_CUT_COMMON_LOSS", -0.62), -0.62))
        should_weak = bool((weak and not strong) and pnl <= safe_float(globals().get("V322_FAST_CUT_WEAK_LOSS", -0.75), -0.75))
        should_be = bool(strong and best >= safe_float(globals().get("V322_STRONG_BREAKEVEN_AFTER", 0.5), 0.5) and pnl <= max(0.03, safe_float(globals().get("V322_STRONG_BREAKEVEN_FLOOR", 0.08), 0.08)))
        trail_floor = max(safe_float(globals().get("V322_STRONG_BREAKEVEN_FLOOR", 0.08), 0.08), best * safe_float(globals().get("V322_STRONG_TRAIL_KEEP_RATIO", 0.55), 0.55))
        should_trail = bool(strong and best >= safe_float(globals().get("V322_STRONG_TRAIL_AFTER", 0.95), 0.95) and pnl <= trail_floor)
        if strong and (should_be or should_trail):
            _v327_inc("v322_counter_bridge", f"v322 카운터 연결 {str(p.get('ticker','?')).upper()}/{cls}")
        return {
            "ts": (_v322_now() if callable(globals().get("_v322_now")) else time.time()),
            "ticker": str(p.get("ticker", "?")).upper(), "lane": str(p.get("lane", ""))[:90],
            "reason": str(reason or "")[:120], "pnl": round(pnl, 3), "best": round(best, 3), "hold_sec": round(hold, 1),
            "route_class": cls, "common": common, "weak": weak, "strong": strong,
            "should_common": should_common, "should_weak": should_weak, "should_breakeven": should_be, "should_trailing": should_trail,
            "trail_floor": round(trail_floor, 3), "route_hint": _v327_blob(p)[:220],
        }
    except Exception as e:
        return {"ts": (_v322_now() if callable(globals().get("_v322_now")) else time.time()), "ticker": str((pos or {}).get("ticker", "?")), "error": f"{e.__class__.__name__}: {str(e)[:100]}"}
