def _v328_chart_quality(obj: dict) -> dict:
    base = _BASE_V328_CHART_QUALITY_V329(obj) if callable(_BASE_V328_CHART_QUALITY_V329) else {"code": "MISSING", "reason": "base 없음"}
    try:
        if _v329_need_repair(obj if isinstance(obj, dict) else {}, base):
            q = _v329_repair_chart_quality(obj if isinstance(obj, dict) else {}, base, reason="v328_quality")
            if q.get("ok"):
                try:
                    _v329_apply_repair_to_row(obj, q)
                except Exception:
                    pass
                if str(q.get("code")) == "REST_FLAT_CONFIRMED":
                    _v329_inc("repair_flat_confirmed")
                merged = dict(base)
                merged.update(q)
                return merged
            else:
                merged = dict(base)
                merged.update({"v329_repair_failed": True, "v329_repair_reason": q.get("reason", "복구 실패"), "code": q.get("code", base.get("code", "MISSING")), "reason": q.get("reason", base.get("reason", "복구 실패"))})
                return merged
    except Exception as e:
        try: append_runtime_error_log("v329_chart_quality_patch", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return base
