def _v332_inc(key: str, note: str = ""):
    try:
        if key in V332_STATS:
            V332_STATS[key] = int(safe_float(V332_STATS.get(key, 0), 0)) + 1
        if note:
            V332_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v332_ticker(obj: dict) -> str:
    try:
        return str((obj or {}).get("ticker", "") or "").upper().strip()
    except Exception:
        return ""
def _v332_row_blob(obj: dict) -> str:
    try:
        if not isinstance(obj, dict):
            return ""
        keys = [
            "lane", "trigger", "register_reason", "close_reason", "reason", "signal_grade", "original_grade",
            "entry_rule", "route", "v331_route", "v332_route", "final_class", "final_judgement", "pattern_tag",
            "signal_decision", "note", "v312_judgement", "next_judgement",
        ]
        return " ".join(str(obj.get(k, "") or "") for k in keys).lower()
    except Exception:
        return ""
def _v332_route_from_row(row: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in ["v332_route", "v331_route", "paper_route", "watch_route", "route", "lane", "trigger", "final_class", "final_judgement", "pattern_tag"]:
            v = str(row.get(k, "") or "").strip()
            if v:
                return v[:140]
        blob = _v332_row_blob(row)
        if any(x in blob for x in ["cancel_reentry", "strong_reentry", "강한놓침", "강한 놓침", "복귀감시", "눌림감시", "v313", "v314"]):
            return "cancel_reentry_strong_watch"
        if any(x in blob for x in ["interest", "관심", "preview", "v274", "v275"]):
            return "interest_prepare"
        if any(x in blob for x in ["strict", "실전급"]):
            return "strict_signal"
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v332_chart_from_row(row: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in ["v330_chart_repair_code", "v329_chart_repair_code", "chart_quality_v330", "chart_quality_v329", "chart_quality_code", "v328_chart_quality_code", "v328_chart_quality", "chart_quality"]:
            v = str(row.get(k, "") or "").strip()
            if v:
                return v[:100]
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v332_grade_from_row(row: dict) -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in ["signal_grade", "grade", "final_grade", "original_grade", "paper_original_grade"]:
            v = str(row.get(k, "") or "").strip()
            if v:
                return v[:80]
    except Exception:
        pass
    return "UNKNOWN_EXPLICIT"
def _v332_enrich_position_dict(pos: dict, row: dict, note: str = "") -> tuple[dict, bool]:
    try:
        if not isinstance(pos, dict):
            return pos, False
        row = row if isinstance(row, dict) else {}
        route = _v332_route_from_row({**row, **pos})
        chart = _v332_chart_from_row({**row, **pos})
        grade = _v332_grade_from_row({**row, **pos})
        changed = False
        fields = {
            "v332_route": route,
            "v331_route": route,
            "v332_chart_code": chart,
            "v331_chart_code": chart,
            "v332_grade": grade,
            "v331_grade": grade,
            "v332_entry_saved": True,
            "v331_entry_saved": True,
            "v332_entry_saved_ts": time.time(),
            "v332_schema": V332_SCHEMA_VERSION,
        }
        default_only = {
            "signal_grade": grade,
            "original_grade": grade,
            "route": route,
            "chart_quality_code": chart,
        }
        for k, v in fields.items():
            if pos.get(k) != v:
                pos[k] = v
                changed = True
        for k, v in default_only.items():
            if not str(pos.get(k, "") or "").strip() or "미저장" in str(pos.get(k, "") or ""):
                pos[k] = v
                changed = True
        snap = {
            "route": route,
            "chart_code": chart,
            "grade": grade,
            "score": safe_float(row.get("score", row.get("final_score", pos.get("score", 0))), 0),
            "price": safe_float(row.get("price", row.get("current_price", pos.get("last_price", pos.get("entry_price", 0)))), 0),
            "v330_chart_repair_code": str(row.get("v330_chart_repair_code", pos.get("v330_chart_repair_code", "")) or ""),
            "v330_chart_verified": bool(row.get("v330_chart_verified", pos.get("v330_chart_verified", False))),
            "note": str(note or "")[:120],
        }
        pos["v332_row_snapshot"] = snap
        pos["v331_row_snapshot"] = snap
        if route == "UNKNOWN_EXPLICIT":
            _v332_inc("entry_force_unknown_route", f"route강제 {pos.get('ticker')}")
        if chart == "UNKNOWN_EXPLICIT":
            _v332_inc("entry_force_unknown_chart", f"chart강제 {pos.get('ticker')}")
        return pos, changed
    except Exception as e:
        try: append_runtime_error_log("v332_enrich_position_dict", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return pos, False
def _v332_enrich_active_positions(ticker: str, row: dict, before_ids=None, reason: str = "register") -> int:
    ticker = str(ticker or "").upper().strip()
    if not ticker:
        return 0
    before_ids = set(before_ids or [])
    now_ts = time.time()
    changed_n = 0
    try:
        with PAPER_STATE_LOCK:
            candidates = []
            for pid, pos in list((paper_positions or {}).items()):
                if not isinstance(pos, dict):
                    continue
                if str(pos.get("ticker", "") or "").upper().strip() != ticker:
                    continue
                if str(pos.get("status", "") or "").upper() not in {"PENDING", "OPEN"}:
                    continue
                created = safe_float(pos.get("created_ts", pos.get("entered_ts", now_ts)), now_ts)
                age = now_ts - created
                is_new = str(pid) not in before_ids
                missing = not bool(pos.get("v332_entry_saved", pos.get("v331_entry_saved", False))) or "미저장" in str(pos)
                if is_new or missing or age <= 2 * 3600:
                    candidates.append((0 if is_new else 1, age, str(pid), dict(pos)))
            candidates.sort(key=lambda x: (x[0], x[1]))
            for _new_flag, _age, pid, pos in candidates[:3]:
                enriched, changed = _v332_enrich_position_dict(pos, row, note=reason)
                paper_positions[pid] = enriched
                changed_n += 1
        if changed_n:
            try: save_paper_state_v258()
            except Exception: pass
            _v332_inc("entry_enriched", f"paper기록강제 {ticker}/{changed_n}")
            if not (set([c[2] for c in candidates[:3]]) - before_ids):
                _v332_inc("entry_enriched_active", f"기존active보정 {ticker}")
        return changed_n
    except Exception as e:
        try: append_runtime_error_log("v332_enrich_active_positions", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return 0
