def _v332_recompute_closed_row_pnl(row: dict, close_price: float, close_reason: str, now_ts: float = None) -> dict:
    try:
        row = dict(row or {})
        now_ts = safe_float(now_ts, row.get("close_ts", time.time()))
        entry = safe_float(row.get("entry_price", 0), 0)
        remaining = max(0.0, min(1.0, safe_float(row.get("remaining_ratio", 1.0), 1.0)))
        realized = safe_float(row.get("realized_pct", 0), 0)
        pnl_now = _paper_pct_v258(entry, close_price) if callable(globals().get("_paper_pct_v258")) else _v331_calc_pct(entry, close_price)
        gross = realized + remaining * pnl_now
        net = gross - safe_float(globals().get("PAPER_FEE_ROUND_TRIP_PCT", 0.10), 0.10)
        row.update({
            "status": "CLOSED",
            "close_ts": now_ts,
            "close_price": safe_float(close_price, 0),
            "close_reason": str(close_reason or row.get("close_reason", "close")),
            "gross_pnl_pct": round(gross, 4),
            "pnl_pct": round(net, 4),
            "fee_assumed_pct": safe_float(globals().get("PAPER_FEE_ROUND_TRIP_PCT", 0.10), 0.10),
            "v332_recomputed_pnl": True,
        })
        return row
    except Exception:
        return row
