def _v332_fix_recent_bypassed_closed_logs(before_len: int = 0, limit: int = 12) -> int:
    fixed = 0
    try:
        before_len = max(0, int(before_len or 0))
        now_ts = time.time()
        with PAPER_STATE_LOCK:
            rows = list(paper_trade_log or [])
            start = min(len(rows), before_len)
            idxs = list(range(start, len(rows)))
            if not idxs:
                idxs = list(range(max(0, len(rows) - int(limit)), len(rows)))
            changed = False
            for idx in idxs[-int(limit):]:
                if idx < 0 or idx >= len(paper_trade_log):
                    continue
                row = paper_trade_log[idx]
                if not isinstance(row, dict):
                    continue
                if str(row.get("status", "") or "").upper() != "CLOSED":
                    continue
                cts = safe_float(row.get("close_ts", 0), 0)
                if cts > 0 and cts < V332_MODULE_TS - 3:
                    continue
                if row.get("v332_guard_checked") or row.get("v332_retro_checked"):
                    continue
                ticker = str(row.get("ticker", "") or "").upper().strip()
                _v332_inc("close_bypass_detected", f"우회청산감지 {ticker}")
                price = safe_float(row.get("close_price", row.get("last_price", 0)), 0)
                reason = str(row.get("close_reason", "close") or "close")
                adj_price, adj_reason, applied, meta = _v331_central_exit_guard(dict(row), price, reason, cts or now_ts, phase="v332_retro") if callable(globals().get("_v331_central_exit_guard")) else (price, reason, False, {})
                row["v332_guard_checked"] = True
                row["v332_retro_checked"] = True
                row["v332_guard_meta"] = dict(meta or {})
                if applied:
                    row["v332_retro_original_close_price"] = price
                    row["v332_retro_original_close_reason"] = reason
                    row = _v332_recompute_closed_row_pnl(row, adj_price, adj_reason, cts or now_ts)
                    row["v332_guard_applied"] = True
                    _v332_inc("close_bypass_fixed", f"우회청산보정 {ticker}")
                    fixed += 1
                paper_trade_log[idx] = row
                changed = True
            if changed:
                paper_trade_log[:] = list(paper_trade_log or [])[-PAPER_TRADE_LOG_MAX:]
        if fixed or 'changed' in locals() and changed:
            try: save_paper_state_v258()
            except Exception: pass
    except Exception as e:
        try: append_runtime_error_log("v332_fix_recent_bypassed_closed_logs", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return fixed
def _v332_cancel_strength(row: dict) -> tuple[bool, str]:
    try:
        row = row if isinstance(row, dict) else {}
        blob = _v332_row_blob(row)
        ticker = _v332_ticker(row)
        score = safe_float(row.get("score", row.get("final_score", 0)), 0)
        money = safe_float(row.get("money_amount", row.get("turnover", row.get("turnover_krw", 0))), 0)
        trade_count = int(safe_float(row.get("trade_count", row.get("ws_trade_count_60s", 0)), 0))
        buy_ratio = safe_float(row.get("buy_ratio", row.get("ws_trade_buy_ratio_60s", 0)), 0)
        max_up = safe_float(row.get("max_up_after_cancel_pct", 0), 0)
        cur_up = safe_float(row.get("current_after_cancel_pct", 0), 0)
        strong_route = any(x in blob for x in ["cancel_reentry", "강한놓침", "강한 놓침", "복귀감시", "눌림감시", "v313", "v314", "strong_return"])
        strong_money = money >= 1_000_000_000 and buy_ratio >= 65 and trade_count >= 5
        decent_money = money >= 300_000_000 and buy_ratio >= 70 and trade_count >= 5
        if max_up >= 3.0 or cur_up >= 1.2:
            return True, f"취소후상승 max{max_up:+.2f}/cur{cur_up:+.2f}"
        if strong_route and (score >= 2.4 or decent_money):
            return True, f"강한놓침경로 score{score:.2f}/money{money/100000000:.1f}억/buy{buy_ratio:.0f}%"
        if score >= 5.0 and decent_money:
            return True, f"고점수취소 score{score:.2f}/money{money/100000000:.1f}억/buy{buy_ratio:.0f}%"
        if strong_money:
            return True, f"돈체결강함 money{money/100000000:.1f}억/buy{buy_ratio:.0f}%"
        return False, f"약함 {ticker}/score{score:.2f}/money{money/100000000:.1f}억/buy{buy_ratio:.0f}%"
    except Exception:
        return False, "판단실패"
def _v332_force_rewatch_from_row(row: dict, source: str = "cancel") -> bool:
    try:
        row = dict(row or {})
        ticker = _v332_ticker(row)
        if not ticker:
            return False
        now_ts = time.time()
        cancel_ts = safe_float(row.get("cancel_ts", row.get("close_ts", row.get("created_ts", now_ts))), now_ts)
        age = now_ts - cancel_ts if cancel_ts > 0 else 0.0
        max_up = safe_float(row.get("max_up_after_cancel_pct", 0), 0)
        cur_up = safe_float(row.get("current_after_cancel_pct", 0), 0)
        if age > 60 * 60 and max_up < 6.0:
            _v332_inc("cancel_fast_rewatch_skip_old", f"오래된 재감시 제외 {ticker}/{age/60:.0f}분")
            return False
        strong, why = _v332_cancel_strength(row)
        if not strong:
            _v332_inc("cancel_fast_rewatch_skip_weak", why)
            return False
        if callable(globals().get("_paper_has_active_ticker_v258")) and _paper_has_active_ticker_v258(ticker):
            _v332_inc("cancel_fast_rewatch_skip_active", f"이미진행중 {ticker}")
            return False
        if max_up >= 5.0 or cur_up >= 2.0 or "힘빠짐" in str(row.get("close_reason", row.get("cancel_reason", ""))):
            mode = "pullback"
        else:
            mode = "breakout" if cur_up >= 0.8 else "pullback"
        row["key"] = f"v332:{ticker}:{int(cancel_ts)}:{source}"
        old_cd = globals().get("V313_READD_COOLDOWN_SEC", 8 * 60)
        try:
            globals()["V313_READD_COOLDOWN_SEC"] = min(int(old_cd), 90)
        except Exception:
            pass
        try:
            ok = _v313_register_forced_pending(row, mode, f"v332 빠른재감시: {why} / {source}") if callable(globals().get("_v313_register_forced_pending")) else False
        finally:
            try: globals()["V313_READD_COOLDOWN_SEC"] = old_cd
            except Exception: pass
        if ok:
            _v332_inc("cancel_fast_rewatch_registered", f"빠른재감시등록 {ticker}/{mode}/{why}")
            return True
        return False
    except Exception as e:
        try: append_runtime_error_log("v332_force_rewatch_from_row", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
