def force_cancel_reentry_queue_v332(max_register: int = 4) -> int:
    added = 0
    try:
        _v332_inc("missed_scan", "큰놓침 재감시 스캔")
        rows = _v313_cancel_rows(limit=120) if callable(globals().get("_v313_cancel_rows")) else []
        now_ts = time.time()
        picked = []
        for row in list(rows or []):
            if not isinstance(row, dict):
                continue
            ticker = _v332_ticker(row)
            if not ticker:
                continue
            max_up = safe_float(row.get("max_up_after_cancel_pct", 0), 0)
            cur_up = safe_float(row.get("current_after_cancel_pct", 0), 0)
            cancel_ts = safe_float(row.get("cancel_ts", row.get("created_ts", 0)), 0)
            age = now_ts - cancel_ts if cancel_ts > 0 else 0.0
            if age > 60 * 60:
                continue
            strong, why = _v332_cancel_strength(row)
            if strong or max_up >= 3.0 or cur_up >= 1.2:
                picked.append((max_up, cur_up, -age, row, why))
        picked.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
        for _m, _c, _age_neg, row, _why in picked[:max(1, int(max_register))]:
            if added >= max(1, int(max_register)):
                break
            if _v332_force_rewatch_from_row(row, source="missed_scan"):
                added += 1
        if added:
            _v332_inc("missed_scan_registered", f"큰놓침 재감시등록 {added}")
        elif picked:
            _v332_inc("missed_scan_no_target", f"큰놓침 후보 {len(picked)}개 / active·recent 등으로 미등록")
    except Exception as e:
        try: append_runtime_error_log("force_cancel_reentry_queue_v332", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return added
