def _v324_entry_trace_from_row(row: dict, trigger: str = "", pos: dict = None) -> dict:
    try:
        trace = _BASE_ENTRY_TRACE_FROM_ROW_V333(row, trigger=trigger, pos=pos) if callable(_BASE_ENTRY_TRACE_FROM_ROW_V333) else {}
        if not isinstance(trace, dict):
            trace = {}
        row = row if isinstance(row, dict) else {}
        pos = pos if isinstance(pos, dict) else {}
        ticker = _v333_ticker(pos or row or trace)
        if ticker:
            trace["ticker"] = ticker
        grade = _v333_grade_from_any({**row, **trace}, pos)
        chart = _v333_chart_from_any({**row, **trace}, pos)
        route = _v333_route_from_any({**row, **trace}, pos)
        if not str(trace.get("grade", "") or "").strip() or "미저장" in str(trace.get("grade", "")):
            _v333_inc("entry_trace_grade_fixed", f"trace등급보정 {ticker}/{grade}")
        if not str(trace.get("chart_status", "") or "").strip() or "미저장" in str(trace.get("chart_status", "")):
            _v333_inc("entry_trace_chart_fixed", f"trace차트보정 {ticker}/{chart}")
        trace.update({
            "schema_v333": V333_SCHEMA_VERSION,
            "version": BOT_VERSION,
            "grade": grade,
            "entry_grade": grade,
            "signal_grade": grade,
            "chart_status": chart,
            "minute1_status": chart,
            "chart_check": chart,
            "v333_route": route,
            "v333_trace_forced": True,
        })
        return trace
    except Exception as e:
        return {"schema_v333": V333_SCHEMA_VERSION, "error": f"{e.__class__.__name__}: {str(e)[:100]}", "ticker": str((row or {}).get("ticker", "?"))}
