def _v325_recent_entry_trace_lines(limit: int = V325_ENTRY_TRACE_SHOW_LIMIT) -> list:
    try:
        path = globals().get("V323_ENTRY_TRACE_FILE", "")
        if not path or not os.path.exists(path):
            return _BASE_RECENT_ENTRY_TRACE_LINES_V333(limit) if callable(_BASE_RECENT_ENTRY_TRACE_LINES_V333) else []
        with open(path, "r", encoding="utf-8") as f:
            raw = f.readlines()[-max(20, int(limit) * 6):]
        rows = []
        for line in raw:
            try:
                obj = json.loads(line)
                if isinstance(obj, dict):
                    rows.append(obj)
            except Exception:
                continue
        rows = rows[-max(1, int(limit)):]
        out = []
        for r in reversed(rows):
            t = str(r.get("ticker", "?")).upper()
            lane = str(r.get("easy_lane", r.get("pos_lane", r.get("lane", r.get("v333_route", "")))))[:36] or "진입경로 미저장"
            grade = str(r.get("grade", r.get("entry_grade", "")) or "").strip()
            chart = str(r.get("chart_status", r.get("minute1_status", r.get("chart_check", ""))) or "").strip()
            if not grade or "미저장" in grade:
                grade = _v333_grade_from_any(r, r)
                _v333_inc("entry_trace_grade_fixed", f"출력등급보정 {t}/{grade}")
            if not chart or "미저장" in chart:
                chart = _v333_chart_from_any(r, r)
                _v333_inc("entry_trace_chart_fixed", f"출력차트보정 {t}/{chart}")
            cls = str(r.get("v326_route_class", r.get("route_class", r.get("v333_route", ""))) or "")
            try:
                if not cls and callable(globals().get("_v327_route_class")):
                    cls = _v327_route_class(r)
            except Exception:
                pass
            risk = "의심" if r.get("pola_like_risk") or r.get("weak_entry_risk") or (cls == "strong_reentry_breakout" and "반짝" in _v333_blob(r)) else "일반"
            out.append(f"- {t}: {lane} / {grade[:16]} / {chart[:24]} / {cls or 'unknown'} / {risk}")
        return out
    except Exception:
        try:
            return _BASE_RECENT_ENTRY_TRACE_LINES_V333(limit) if callable(_BASE_RECENT_ENTRY_TRACE_LINES_V333) else []
        except Exception:
            return []
