def _v333_retouch_recent_closed_logs(limit: int = 35) -> int:
    marked = 0
    try:
        _v333_inc("close_recent_retro_scan", "최근청산 retro scan")
        with PAPER_STATE_LOCK:
            rows = paper_trade_log if isinstance(paper_trade_log, list) else []
            start = max(0, len(rows) - max(1, int(limit)))
            for idx in range(start, len(rows)):
                row = rows[idx]
                if not isinstance(row, dict):
                    continue
                if str(row.get("status", "") or "").upper() != "CLOSED":
                    continue
                if row.get("v333_guard_checked") or row.get("v332_guard_checked") or row.get("v331_central_exit_checked"):
                    continue
                enriched, _ = _v333_enrich_position_dict(dict(row), row, note="retro_closed")
                enriched["v333_guard_checked"] = True
                enriched["v333_retro_checked"] = True
                rows[idx] = enriched
                marked += 1
        if marked:
            try: save_paper_state_v258()
            except Exception: pass
            _v333_inc("close_recent_retro_marked", f"최근청산표식 {marked}")
    except Exception as e:
        try: append_runtime_error_log("v333_retouch_recent_closed_logs", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return marked
def _v333_is_rewatch_row_strong(row: dict) -> tuple[bool, str, str]:
    try:
        row = row if isinstance(row, dict) else {}
        ticker = _v333_ticker(row)
        max_up = safe_float(row.get("max_up_after_cancel_pct", row.get("max_up_pct", 0)), 0)
        cur_up = safe_float(row.get("current_after_cancel_pct", row.get("current_up_pct", 0)), 0)
        money = safe_float(row.get("money_amount", row.get("turnover", row.get("money", 0))), 0)
        buy = safe_float(row.get("buy_ratio", row.get("ws_trade_buy_ratio_60s", 0)), 0)
        cnt = int(safe_float(row.get("trade_count", row.get("ws_trade_count_60s", 0)), 0))
        blob = _v333_blob(row)
        strong = False
        why = []
        if max_up >= V333_BIG_MISS_STRONG_MAX_UP:
            strong = True; why.append(f"최고+{max_up:.2f}%")
        if max_up >= V333_BIG_MISS_MIN_MAX_UP and cur_up >= V333_BIG_MISS_MIN_CUR_UP:
            strong = True; why.append(f"현재+{cur_up:.2f}%유지")
        if any(x in blob for x in ["강한 놓침", "강한놓침", "복귀감시 연결 대상", "눌림감시 대상"]):
            strong = True; why.append("v312강한놓침")
        if money >= 1_000_000_000 and (buy >= 60 or cnt >= 6) and max_up >= 1.2:
            strong = True; why.append("돈/체결강함")
        if not strong:
            return False, ticker, "약함"
        mode = "pullback" if max_up >= 3.0 or "힘빠짐" in blob or "눌림" in blob else "breakout"
        return True, ticker, "/".join(why[:4]) + f"/{mode}"
    except Exception:
        return False, "", "오류"
def _v333_force_rewatch_from_row(row: dict, source: str = "scan") -> bool:
    try:
        row = dict(row or {})
        strong, ticker, why = _v333_is_rewatch_row_strong(row)
        if not ticker:
            return False
        if not strong:
            _v333_inc("rewatch_skip_weak", f"약함스킵 {ticker}/{why}")
            return False
        now_ts = time.time()
        cancel_ts = safe_float(row.get("cancel_ts", row.get("close_ts", row.get("created_ts", now_ts))), now_ts)
        age = now_ts - cancel_ts if cancel_ts > 0 else 0
        max_up = safe_float(row.get("max_up_after_cancel_pct", row.get("max_up_pct", 0)), 0)
        cur_up = safe_float(row.get("current_after_cancel_pct", row.get("current_up_pct", 0)), 0)
        if age > V333_BIG_MISS_LATE_MAX_AGE_SEC and cur_up < 1.5:
            _v333_inc("rewatch_skip_too_late", f"너무늦음복기 {ticker}/{age/60:.0f}분")
            return False
        if callable(globals().get("_paper_has_active_ticker_v258")) and _paper_has_active_ticker_v258(ticker):
            _v333_inc("rewatch_skip_active", f"이미진행중 {ticker}")
            return False
        mode = "pullback" if max_up >= 3.0 or cur_up >= 1.4 or "힘빠짐" in _v333_blob(row) else "breakout"
        row["key"] = f"v333:{ticker}:{int(cancel_ts)}:{source}"
        old_cd = globals().get("V313_READD_COOLDOWN_SEC", 8 * 60)
        try:
            globals()["V313_READD_COOLDOWN_SEC"] = min(int(old_cd), 75 if age <= V333_BIG_MISS_FAST_MAX_AGE_SEC else 120)
        except Exception:
            pass
        _v333_inc("rewatch_try", f"재감시시도 {ticker}/{why}/{age/60:.1f}분")
        try:
            ok = _v313_register_forced_pending(row, mode, f"v333 빠른재감시: {why} / {source} / {age/60:.1f}분") if callable(globals().get("_v313_register_forced_pending")) else False
        finally:
            try: globals()["V313_READD_COOLDOWN_SEC"] = old_cd
            except Exception: pass
        if ok:
            _v333_inc("rewatch_registered", f"재감시등록 {ticker}/{mode}/{why}")
            return True
        return False
    except Exception as e:
        try: append_runtime_error_log("v333_force_rewatch", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
try:
    _BASE_PAPER_CANCEL_PENDING_V333 = globals().get('_paper_cancel_pending_v258')
except Exception:
    _BASE_PAPER_CANCEL_PENDING_V333 = None
def force_cancel_reentry_queue_v333(max_register: int = 6) -> int:
    added = 0
    try:
        _v333_inc("rewatch_scan", "큰놓침/지연 재감시 스캔")
        rows = _v313_cancel_rows(limit=180) if callable(globals().get("_v313_cancel_rows")) else []
        now_ts = time.time()
        picked = []
        for row in list(rows or []):
            if not isinstance(row, dict):
                continue
            ticker = _v333_ticker(row)
            if not ticker:
                continue
            cancel_ts = safe_float(row.get("cancel_ts", row.get("created_ts", 0)), 0)
            age = now_ts - cancel_ts if cancel_ts > 0 else 0
            if age <= 0 or age > V333_BIG_MISS_LATE_MAX_AGE_SEC:
                continue
            strong, _ticker, why = _v333_is_rewatch_row_strong(row)
            max_up = safe_float(row.get("max_up_after_cancel_pct", row.get("max_up_pct", 0)), 0)
            cur_up = safe_float(row.get("current_after_cancel_pct", row.get("current_up_pct", 0)), 0)
            if strong and (age <= V333_BIG_MISS_FAST_MAX_AGE_SEC or cur_up >= 1.0 or max_up >= 4.0):
                picked.append((age <= V333_BIG_MISS_FAST_MAX_AGE_SEC, max_up, cur_up, -age, row, why))
        picked.sort(key=lambda x: (x[0], x[1], x[2], x[3]), reverse=True)
        for *_rest, row, why in picked[:max(1, int(max_register))]:
            if added >= max(1, int(max_register)):
                break
            if _v333_force_rewatch_from_row(row, source="missed_scan"):
                added += 1
        if added:
            _v333_inc("rewatch_registered", f"스캔등록 {added}")
    except Exception as e:
        try: append_runtime_error_log("force_cancel_reentry_queue_v333", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return added
