def _v335_sanitize_close_reason(reason: str) -> str:
    try:
        text = str(reason or "").strip()
        if not text:
            return text
        for marker in [" / 원래 ", " / before ", " / original "]:
            if text.count(marker) > 1:
                head, rest = text.split(marker, 1)
                first = rest.split(marker, 1)[0]
                text = head + marker + first
        while "원래 원래" in text:
            text = text.replace("원래 원래", "원래")
        if text.count("v331_no_progress_crash_cut") > 1:
            first = text.find("v331_no_progress_crash_cut")
            tail = text[first:]
            end = tail.find(" / ")
            text = tail[:end] if end > 0 else tail
        if len(text) > 280:
            text = text[:280] + " ...(중복정리)"
        return text
    except Exception:
        return str(reason or "")
