def _v335_sanitize_recent_closed_logs(limit: int = 100) -> int:
    changed = 0
    try:
        with PAPER_STATE_LOCK:
            rows = paper_trade_log if isinstance(paper_trade_log, list) else []
            start = max(0, len(rows) - max(1, int(limit)))
            for idx in range(start, len(rows)):
                row = rows[idx]
                if not isinstance(row, dict):
                    continue
                cr = str(row.get("close_reason", row.get("cancel_reason", "")) or "")
                clean = _v335_sanitize_close_reason(cr)
                if clean and clean != cr:
                    row["close_reason"] = clean
                    row["cancel_reason"] = clean if str(row.get("status", "")).upper() == "CANCELLED" else row.get("cancel_reason", "")
                    row["v335_close_reason_sanitized"] = True
                    changed += 1
                if str(row.get("status", "") or "").upper() in {"PENDING", "OPEN", "CLOSED"} and not isinstance(row.get("v335_entry_context"), dict):
                    ctx, merged, _invalid = _v335_build_entry_context(row, trigger="retro_log")
                    row["v335_entry_context"] = ctx
                    row["v335_entry_context_retro"] = True
                    changed += 1
                rows[idx] = row
        if changed:
            try: save_paper_state_v258()
            except Exception: pass
            _v335_inc("closed_log_sanitized", f"최근로그정리 {changed}")
    except Exception as e:
        try: append_runtime_error_log("v335_sanitize_recent_closed_logs", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return changed
