def get_light_snapshot_rank_rows(limit: int = REALTIME_RANK_DISPLAY_LIMIT, min_move_pct: float = REALTIME_RANK_MIN_RECORD_MOVE_PCT) -> list:
    _v335_inc("rank_source_call", "rank_source 호출")
    now_ts = time.time()
    safe_limit = max(20, min(int(safe_float(limit, 70)), 70))
    try:
        v333_cache = globals().get("V333_RANK_SOURCE_CACHE", {})
        rows = v333_cache.get("rows", []) if isinstance(v333_cache, dict) else []
        ts = safe_float(v333_cache.get("ts", 0), 0) if isinstance(v333_cache, dict) else 0
        sec = safe_float(v333_cache.get("sec", 0), 0) if isinstance(v333_cache, dict) else 0
        age = now_ts - ts if ts > 0 else 999999
        if rows and age <= V335_RANK_REUSE_SEC:
            _v335_inc("rank_source_fast_reuse", f"v333캐시재사용 {len(rows)}개/{age:.0f}s/{sec:.1f}s")
            return list(rows)[:safe_limit]
        last_rows = globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS", []) or []
        last_ts = safe_float(globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS", 0), 0)
        last_age = now_ts - last_ts if last_ts > 0 else 999999
        if last_rows and last_age <= V335_RANK_LAST_ROWS_REUSE_SEC:
            _v335_inc("rank_source_last_rows_reuse", f"last_rank_rows재사용 {len(last_rows)}개/{last_age:.0f}s")
            return list(last_rows)[:safe_limit]
    except Exception:
        pass
    t0 = time.time()
    try:
        rows = _BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V335(limit=safe_limit, min_move_pct=min_move_pct) if callable(_BASE_GET_LIGHT_SNAPSHOT_RANK_ROWS_V335) else []
        sec = time.time() - t0
        _v335_inc("rank_source_refresh", f"rank_source갱신 {sec:.2f}s/{len(rows or [])}개")
        if sec >= V335_RANK_SLOW_SEC:
            _v335_inc("rank_source_slow", f"rank_source느림 {sec:.2f}s")
        return list(rows or [])[:safe_limit]
    except Exception as e:
        try: append_runtime_error_log("v335_rank_source", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return []
