def _v336_context_risk_reasons(ctx: dict, row: dict = None, merged: dict = None) -> list:
    reasons = []
    try:
        if callable(globals().get("_v335_entry_risk_reasons")):
            reasons.extend(list(_v335_entry_risk_reasons(ctx or {}, row or {}, merged or {}) or []))
    except Exception:
        pass
    blob = " ".join(str(x or "").lower() for x in [
        (ctx or {}).get("route"), (ctx or {}).get("grade"), (ctx or {}).get("chart_status"),
        (ctx or {}).get("final_decision"), (ctx or {}).get("source"), (ctx or {}).get("context_source"),
    ])
    if not str((ctx or {}).get("ticker", "") or "").strip():
        reasons.append("ticker_missing")
    if safe_float((ctx or {}).get("price", 0), 0) <= 0:
        reasons.append("price_missing")
    if str((ctx or {}).get("grade", "")).upper().strip() in {"C", "DISCARD", "BLOCK", "REJECT"}:
        reasons.append("grade_not_buy")
    if any(k in blob for k in ["반짝", "관찰", "복기", "discard", "watch_only", "command_only"]):
        reasons.append("final_decision_not_buy")
    if any(k in blob for k in ["미검증", "unverified", "ws_light_snapshot_pseudo", "light_snapshot", "unknown_explicit"]):
        if any(k in blob for k in ["strict", "실전급", "buy_ok", "바로"]):
            reasons.append("strict_with_unverified_context")
    chgs = [safe_float((ctx or {}).get(k, 0), 0) for k in ["change_1m", "change_3m", "change_5m", "change_15m"]]
    if len(chgs) == 4 and all(v < 0 for v in chgs) and any(k in blob for k in ["strict", "실전급", "buy_ok", "바로"]):
        reasons.append("strict_negative_short_flow")
    out = []
    for r in reasons:
        r = str(r or "").strip()
        if r and r not in out:
            out.append(r)
    return out
def _v336_append_attempt(ctx: dict, row: dict = None, trigger: str = "", result: str = "attempt", reasons: list = None, pos_id: str = ""):
    global paper_entry_attempts_v336
