def _v336_sanitize_close_reason(reason: str) -> str:
    text = str(reason or "close").strip()
    try:
        while " / 원래 " in text and text.count(" / 원래 ") > 1:
            first = text.find(" / 원래 ")
            second = text.find(" / 원래 ", first + 1)
            if second <= first:
                break
            text = text[:second]
        for key in ["v331_no_progress_crash_cut", "v331_live_no_progress_cut", "v332_before", "v333"]:
            if text.count(key) > 1:
                parts = text.split(" / 원래 ")
                text = parts[0]
                break
    except Exception:
        pass
    return text[:300]
def _paper_close_position_v258(pos_id: str, pos: dict, price: float, reason: str, now_ts: float = None):
    now_ts = safe_float(now_ts, _v336_now())
    pos = dict(pos or {})
    try:
        if not isinstance(pos.get("v336_entry_context"), dict):
            ctx, merged, _invalid = _v336_build_entry_context(pos, trigger="close_retro")
            pos["v336_entry_context"] = ctx
            pos["v336_context_retro"] = True
            _v336_inc("bypass_repaired", f"청산전 context보정 {pos.get('ticker')}")
        entry = safe_float(pos.get("entry_price", 0), 0)
        remaining = max(0.0, min(1.0, safe_float(pos.get("remaining_ratio", 1.0), 1.0)))
        realized = safe_float(pos.get("realized_pct", 0), 0)
        pnl_now = _paper_pct_v258(entry, price) if entry > 0 else 0.0
        gross = realized + remaining * pnl_now
        net = gross - safe_float(PAPER_FEE_ROUND_TRIP_PCT, 0.10)
        clean_reason = _v336_sanitize_close_reason(reason)
        if clean_reason != str(reason or ""):
            _v336_inc("close_reason_sanitized", f"청산사유정리 {pos.get('ticker')}")
        row = dict(pos)
        row.update({
            "status": "CLOSED",
            "close_ts": now_ts,
            "close_price": safe_float(price, 0),
            "close_reason": clean_reason,
            "gross_pnl_pct": round(gross, 4),
            "pnl_pct": round(net, 4),
            "fee_assumed_pct": PAPER_FEE_ROUND_TRIP_PCT,
            "held_sec": int(max(0, now_ts - safe_float(pos.get("entered_ts", pos.get("created_ts", now_ts)), now_ts))),
            "v336_clean_engine": True,
        })
        with PAPER_STATE_LOCK:
            paper_positions.pop(pos_id, None)
            paper_trade_log.append(row)
            _v336_trim(paper_trade_log, PAPER_V336_MAX_LOG)
        PAPER_V258_STATS["closed"] = int(safe_float(PAPER_V258_STATS.get("closed", 0), 0)) + 1
        PAPER_V258_STATS["last_note"] = f"v336 청산 {row.get('ticker')}/{net:+.2f}%"
        _v336_inc("closed", f"청산 {row.get('ticker')}/{net:+.2f}%")
        save_paper_state_v258()
    except Exception as e:
        append_runtime_error_log("paper_close_v336", str(e), exc=e, include_traceback=True)
def _paper_cancel_pending_v258(pos_id: str, pos: dict, reason: str, now_ts: float = None):
    now_ts = safe_float(now_ts, _v336_now())
