def build_paper_text_v258(limit: int = 10) -> str:
    try:
        paper_update_positions_once_v258()
        with PAPER_STATE_LOCK:
            rows = [dict(p) for p in (paper_positions or {}).values() if isinstance(p, dict) and str(p.get("status", "")).upper() in {"PENDING", "OPEN"}]
        lines = ["🧪 모의매매 /paper", "- v336 새 paper 엔진 기준 / 실제 주문 아님", ""]
        if not rows:
            lines.append("- 현재 v336 보유가정/진입대기 없음")
        for i, pos in enumerate(rows[:max(1, int(limit))], start=1):
            ticker = str(pos.get("ticker", "?") or "?")
            status = str(pos.get("status", "") or "")
            price = safe_float(pos.get("last_price", pos.get("entry_price", 0)), 0)
            entry = safe_float(pos.get("entry_price", 0), 0)
            pnl = _paper_pct_v258(entry, price) if status.upper() == "OPEN" and entry > 0 else 0.0
            ctx = pos.get("v336_entry_context") if isinstance(pos.get("v336_entry_context"), dict) else {}
            lines.append(f"{i}. {ticker} / {status} / {pnl:+.2f}% / {pos.get('lane','')} / ctx {str((ctx or {}).get('context_source',''))}")
        return "\n".join(lines)
    except Exception as e:
        return f"🧪 모의매매 /paper\n- v336 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
def _v336_stats_for_rows(rows: list) -> dict:
    closed = [r for r in rows if str(r.get("status", "") or "").upper() == "CLOSED"]
    wins = [r for r in closed if safe_float(r.get("pnl_pct", 0), 0) > 0]
    losses = [r for r in closed if safe_float(r.get("pnl_pct", 0), 0) <= 0]
    total = sum(safe_float(r.get("pnl_pct", 0), 0) for r in closed)
    gross_win = sum(max(0.0, safe_float(r.get("pnl_pct", 0), 0)) for r in closed)
    gross_loss = abs(sum(min(0.0, safe_float(r.get("pnl_pct", 0), 0)) for r in closed))
    pf = gross_win / gross_loss if gross_loss > 0 else (999.0 if gross_win > 0 else 0.0)
    return {"n": len(closed), "wins": len(wins), "losses": len(losses), "total": total, "pf": pf}
