def _v337_inc(key: str, note: str = ""):
    try:
        V337_STATS[key] = int(safe_float(V337_STATS.get(key, 0), 0)) + 1
        if note:
            V337_STATS["last_note"] = str(note)[:220]
    except Exception:
        pass
def _v337_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v337_ticker(row=None) -> str:
    try:
        if isinstance(row, str):
            t = row
        elif callable(globals().get("_v336_ticker")):
            t = _v336_ticker(row if isinstance(row, dict) else {})
        elif callable(globals().get("_v335_ticker")):
            t = _v335_ticker(row if isinstance(row, dict) else {})
        else:
            t = str((row or {}).get("ticker", (row or {}).get("symbol", "")) or "")
        t = str(t or "").upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        if t.endswith("_KRW"):
            t = t[:-4]
        return t.strip()
    except Exception:
        return ""
def _v337_price(row: dict) -> float:
    try:
        if callable(globals().get("_v336_price")):
            return safe_float(_v336_price(row), 0)
    except Exception:
        pass
    try:
        if callable(globals().get("_v335_price")):
            return safe_float(_v335_price(row), 0)
    except Exception:
        pass
    return safe_float((row or {}).get("current_price", (row or {}).get("price", (row or {}).get("last_price", 0))), 0)
def _v337_row_ts(row: dict) -> float:
    try:
        if not isinstance(row, dict):
            return 0.0
        for k in [
            "latest_ts", "updated_ts", "hub_ts", "snapshot_rank_detected_ts", "ts", "built_ts",
            "factory_ts", "row_ts", "price_ts", "created_ts", "snapshot_ts"
        ]:
            v = safe_float(row.get(k, 0), 0)
            if v > 0:
                return v
    except Exception:
        pass
    return 0.0
def _v337_rank_cache_like(row: dict) -> bool:
    try:
        if not isinstance(row, dict):
            return False
        blob = " ".join(str(row.get(k, "") or "").lower() for k in [
            "source", "cache_source", "snapshot_source", "row_source", "data_source", "v335_hub_pool", "context_source"
        ])
        if any(x in blob for x in ["rank_cache", "v333_rank", "v322_rank", "command_display", "rank_state", "rank_source"]):
            return True
        if any(k in row for k in ["snapshot_rank_score", "rank_watch_action", "rank_watch_chart_state"]):
            if not bool(row.get("factory_v294")):
                return True
    except Exception:
        pass
    return False
def _v337_mark_source(row: dict, source: str, now_ts: float = None) -> dict:
    now_ts = safe_float(now_ts, _v337_now())
    out = dict(row or {})
    ts = _v337_row_ts(out)
    out["v337_context_source"] = source
    out["context_source"] = source
    out["source"] = str(out.get("source", source) or source)
    out["v337_row_ts"] = ts
    out["v337_row_age_sec"] = max(0.0, now_ts - ts) if ts > 0 else 999999.0
    out["v337_central_only"] = True
    if source.startswith("factory"):
        out["v337_factory_row"] = True
    if source == "shared_market_cache":
        out["v337_shared_row"] = True
    return out
def _v337_copy_factory_row(ticker: str, stage_name: str) -> dict:
    try:
        table = globals().get(stage_name, {})
        if not isinstance(table, dict):
            return {}
        t = _v337_ticker(ticker)
        row = table.get(t) or table.get(t.upper()) or table.get("KRW-" + t)
        if isinstance(row, dict):
            return dict(row)
    except Exception:
        pass
    return {}
def _v337_shared_row(ticker: str) -> dict:
    try:
        t = _v337_ticker(ticker)
        cache = globals().get("shared_market_cache", {})
        if not isinstance(cache, dict):
            return {}
        raw = cache.get(t) or cache.get(t.upper()) or cache.get("KRW-" + t)
        now_ts = _v337_now()
        if isinstance(raw, dict):
            row = dict(raw)
        elif safe_float(raw, 0) > 0:
            row = {"ticker": t, "price": safe_float(raw, 0), "current_price": safe_float(raw, 0)}
        else:
            return {}
        row.setdefault("ticker", t)
        row.setdefault("current_price", row.get("price", row.get("last_price", 0)))
        row.setdefault("price", row.get("current_price", row.get("last_price", 0)))
        ts = safe_float(row.get("ts", row.get("updated_ts", 0)), 0)
        if ts <= 0:
            ts = safe_float(globals().get("shared_market_cache_time", 0), 0)
        if ts <= 0:
            ts = now_ts
        row.setdefault("ts", ts)
        row.setdefault("updated_ts", ts)
        row.setdefault("latest_ts", ts)
        row.setdefault("cache_source", "shared_market_cache")
        row.setdefault("source", "shared_market_cache")
        return row
    except Exception:
        return {}
def _v337_row_is_fresh(row: dict, source: str, now_ts: float = None) -> bool:
    now_ts = safe_float(now_ts, _v337_now())
    ts = _v337_row_ts(row)
    if ts <= 0:
        return False
    age = max(0.0, now_ts - ts)
    limit = V337_SHARED_MAX_AGE_SEC if source == "shared_market_cache" else V337_CENTRAL_MAX_AGE_SEC
    return age <= safe_float(limit, 90.0)
