def _v341_extract_watch_metrics(row: dict) -> dict:
    row = row if isinstance(row, dict) else {}
    first = row.get("first_snapshot") if isinstance(row.get("first_snapshot"), dict) else {}
    last = row.get("last_snapshot") if isinstance(row.get("last_snapshot"), dict) else first
    results = row.get("results") if isinstance(row.get("results"), dict) else {}
    r10 = results.get("10m", {}) if isinstance(results.get("10m", {}), dict) else {}
    r30 = results.get("30m", {}) if isinstance(results.get("30m", {}), dict) else {}
    main = r30 or r10 or {}
    return {
        "ticker": _v341_ticker(row) or _v341_ticker(first) or _v341_ticker(last),
        "first": first,
        "last": last,
        "result_type": str(main.get("result_type", row.get("result_type", "")) or ""),
        "max_up": max(safe_float(row.get("max_up_pct", 0), 0), safe_float(r10.get("max_up_pct", 0), 0), safe_float(r30.get("max_up_pct", 0), 0)),
        "end_up": max(safe_float(row.get("last_up_pct", 0), 0), safe_float(r10.get("end_up_pct", -999), -999), safe_float(r30.get("end_up_pct", -999), -999)),
        "min_down": min(safe_float(row.get("min_down_pct", 0), 0), safe_float(r10.get("min_down_pct", 0), 0), safe_float(r30.get("min_down_pct", 0), 0)),
        "text": _v341_text_blob(row, first, last, r10, r30),
    }
def _v341_should_bridge_watch(row: dict, active: bool = False) -> tuple[bool, str]:
    try:
        m = _v341_extract_watch_metrics(row)
        t = m.get("ticker", "")
        if not t:
            return False, "no_ticker"
        text = str(m.get("text", ""))
        lower = text.lower()
        result = str(m.get("result_type", ""))
        max_up = safe_float(m.get("max_up", 0), 0)
        end_up = safe_float(m.get("end_up", 0), 0)
        if any(w in lower for w in ["진짜버림", "위험 회피", "가짜 상승", "매도반전", "식는", "discard"]):
            if not (max_up >= 3.0 and end_up >= 0.7):
                return False, "weak_or_discard_watch"
        if "승격 놓침 가능성" in result or "승격 놓침 가능성" in text:
            return True, "review_missed_promotion"
        if max_up >= 3.0 and end_up >= 0.7:
            return True, "review_big_missed"
        if active:
            if any(k in text for k in ["강세 후 유지 확인", "검증 표본 좋음", "초입 강세", "재출발 확인", "고점 재돌파 유지", "고점 재접근"]):
                if max_up >= 0.55 or safe_float((m.get("first") or {}).get("change_5", 0), 0) >= 1.2:
                    return True, "active_watch_strong_recheck"
        else:
            if any(k in text for k in ["초입 강세", "재출발 확인", "고점 재돌파 유지", "감시 판단 좋음"]):
                if max_up >= 1.2 and end_up >= 0.25:
                    return True, "closed_watch_good_recheck"
    except Exception:
        pass
    return False, "not_watch_bridge"
def _v341_enqueue_watch_to_v340(row: dict, why: str = "watch_bridge") -> bool:
    try:
        m = _v341_extract_watch_metrics(row)
        t = str(m.get("ticker", "") or "").upper().strip()
        if not t:
            return False
        central = {}
        src = ""
        invalid = []
        try:
            central, src, _ts, invalid = _v337_get_central_entry_row(t, allow_refresh=True) if callable(globals().get("_v337_get_central_entry_row")) else ({}, "missing", 0, ["missing"])
        except Exception:
            central, src, invalid = {}, "missing", ["missing"]
        if not isinstance(central, dict) or not central:
            _v341_inc("central_missing", f"내부감시브릿지 중앙row없음 {t}")
            return False
        if invalid:
            if any("stale" in str(x).lower() or "old" in str(x).lower() or "오래" in str(x) for x in invalid):
                _v341_inc("central_stale", f"내부감시브릿지 stale {t}")
                return False
        first = m.get("first") if isinstance(m.get("first"), dict) else {}
        last = m.get("last") if isinstance(m.get("last"), dict) else {}
        merged = dict(central)
        merged.update({
            "ticker": t,
            "route": "v341_review_watch_bridge",
            "lane": "v341_review_watch_bridge",
            "grade": str(central.get("grade", central.get("signal_grade", "BREAKOUT_WAIT")) or "BREAKOUT_WAIT"),
            "signal_grade": str(central.get("signal_grade", central.get("grade", "BREAKOUT_WAIT")) or "BREAKOUT_WAIT"),
            "final_decision": "내부감시 강세/승격놓침 2차확인 대기",
            "decision": "내부감시 강세/승격놓침 2차확인 대기",
            "primary_reason": f"v341 내부감시 브릿지: {why}",
            "v341_review_bridge": True,
            "v341_review_reason": str(why),
            "v341_watch_max_up": safe_float(m.get("max_up", 0), 0),
            "v341_watch_end_up": safe_float(m.get("end_up", 0), 0),
            "context_source": f"{src or 'factory'}_v341_review_bridge",
        })
        ctx = dict(merged)
        ctx.setdefault("route", "v341_review_watch_bridge")
        ctx.setdefault("grade", "BREAKOUT_WAIT")
        _v341_inc("enqueue_try", f"내부감시브릿지시도 {t}")
        ok = bool(_v340_enqueue_recheck(merged, ctx, trigger="v341_review_watch_bridge", reason=str(why))) if callable(globals().get("_v340_enqueue_recheck")) else False
        if ok:
            _v341_inc("enqueue_success", f"내부감시브릿지등록 {t}/{why}")
        else:
            _v341_inc("enqueue_fail", f"내부감시브릿지실패 {t}/{why}")
        return ok
    except Exception as e:
        try: append_runtime_error_log("v341_enqueue_watch_to_v340", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
def _v341_scan_internal_watch_bridge(force: bool = False) -> int:
    try:
        now_ts = _v341_now()
        if not force and now_ts - safe_float(V341_STATE.get("last_scan_ts", 0), 0) < V341_SCAN_INTERVAL_SEC:
            return 0
        V341_STATE["last_scan_ts"] = now_ts
        _v341_inc("scan", "내부감시브릿지 스캔")
        active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
        active_rows = [x for x in (active.values() if isinstance(active, dict) else []) if isinstance(x, dict)]
        try:
            log_rows = dedupe_internal_watch_logs(logs) if callable(globals().get("dedupe_internal_watch_logs")) else logs
        except Exception:
            log_rows = logs
        log_rows = [x for x in (log_rows or []) if isinstance(x, dict)]
        rows = []
        rows += [(False, r) for r in sorted(log_rows, key=lambda x: safe_float(x.get("closed_at", x.get("saved_at", 0)), 0), reverse=True)[:V341_MAX_SCAN_ROWS]]
        rows += [(True, r) for r in sorted(active_rows, key=lambda x: safe_float(x.get("saved_at", 0), 0), reverse=True)[:max(6, V341_MAX_SCAN_ROWS // 2)]]
        linked = 0
        for is_active, row in rows:
            key = _v341_row_key(row, prefix="active" if is_active else "log")
            if _v341_is_processed(key):
                _v341_inc("duplicate_skip")
                continue
            if is_active:
                _v341_inc("active_seen")
            else:
                _v341_inc("log_seen")
            ok, why = _v341_should_bridge_watch(row, active=is_active)
            if not ok:
                continue
            _v341_inc("missed_signal", f"내부감시브릿지대상 {_v341_ticker(row)}/{why}")
            if _v341_enqueue_watch_to_v340(row, why=why):
                linked += 1
                _v341_mark_processed(key, _v341_ticker(row), why)
        if linked:
            _v341_save_state()
            try:
                if callable(globals().get("_v340_process_recheck_queue")):
                    _v340_process_recheck_queue(force=False)
            except Exception:
                pass
        else:
            _v341_save_state()
        return linked
    except Exception as e:
        try: append_runtime_error_log("v341_scan_internal_watch_bridge", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return 0
