def _v342_row_key(row: dict, prefix: str = "") -> str:
    try:
        t = _v342_ticker(row)
        ts = safe_float((row or {}).get("registered_ts", (row or {}).get("created_ts", (row or {}).get("closed_at", (row or {}).get("saved_at", (row or {}).get("ts", 0))))), 0)
        return f"{prefix}:{t}:{int(ts)}:{str((row or {}).get('key',''))[:40]}"
    except Exception:
        return f"{prefix}:unknown:{int(_v342_now())}"
def _v342_mark_processed(key: str):
    try:
        V342_STATE.setdefault("processed", {})[str(key)] = _v342_now()
    except Exception:
        pass
def _v342_is_processed(key: str) -> bool:
    try:
        return str(key) in (V342_STATE.get("processed", {}) if isinstance(V342_STATE, dict) else {})
    except Exception:
        return False
def _v342_scan_good_pullback_sources(force: bool = False) -> int:
    linked = 0
    try:
        now_ts = _v342_now()
        if not force and now_ts - safe_float(V342_STATE.get("last_scan_ts", 0), 0) < 18.0:
            return 0
        V342_STATE["last_scan_ts"] = now_ts
        _v342_inc("scan", "v342 좋은눌림 route 스캔")
        rows = []
        try:
            if callable(globals().get("_v313_active_queue_rows")):
                for r in list(_v313_active_queue_rows(limit=30) or []):
                    if isinstance(r, dict):
                        rows.append(("v313", r))
                        _v342_inc("v313_rows_seen")
        except Exception:
            pass
        try:
            active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
            active_rows = [x for x in (active.values() if isinstance(active, dict) else []) if isinstance(x, dict)]
            for r in active_rows[:20]:
                rows.append(("review_active", r)); _v342_inc("watch_rows_seen")
            try:
                log_rows = dedupe_internal_watch_logs(logs) if callable(globals().get("dedupe_internal_watch_logs")) else logs
            except Exception:
                log_rows = logs
            log_rows = [x for x in (log_rows or []) if isinstance(x, dict)]
            log_rows = sorted(log_rows, key=lambda x: safe_float(x.get("closed_at", x.get("saved_at", 0)), 0), reverse=True)[:30]
            for r in log_rows:
                rows.append(("review_log", r)); _v342_inc("watch_rows_seen")
        except Exception:
            pass
        for src, r in rows[:80]:
            key = _v342_row_key(r, src)
            if _v342_is_processed(key):
                continue
            ok, why = _v342_is_good_pullback_route(r, {}, src)
            if not ok:
                continue
            if _v342_enqueue_good_pullback(r, {}, trigger=src, reason=why):
                linked += 1
                _v342_mark_processed(key)
        if linked:
            _v342_save_state()
            _v342_process_queue(force=False)
        else:
            _v342_save_state()
    except Exception as e:
        try: append_runtime_error_log("v342_scan_good_pullback_sources", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return linked
