def _v343_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v343_inc(key: str, note: str = ""):
    try:
        V343_STATS[key] = int(safe_float(V343_STATS.get(key, 0), 0)) + 1
        if note:
            V343_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v343_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v342_ticker")):
            return _v342_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        else:
            row = row if isinstance(row, dict) else {}
            t = str(row.get("ticker", row.get("symbol", "")) or "")
        t = t.upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        return t
    except Exception:
        return ""
def _v343_load_state():
    global V343_QUEUE, V343_HISTORY, V343_STATE
    try:
        now_ts = _v343_now()
        q = load_json_file(PAPER_V343_QUEUE_FILE, {})
        if isinstance(q, dict) and isinstance(q.get("queue"), dict):
            q = q.get("queue")
        if isinstance(q, dict):
            V343_QUEUE = {}
            for k, r in q.items():
                if not isinstance(r, dict):
                    continue
                first_ts = safe_float(r.get("first_ts", now_ts), now_ts)
                if now_ts - first_ts <= V343_MAX_KEEP_SEC:
                    V343_QUEUE[str(k).upper()] = dict(r)
        h = load_json_file(PAPER_V343_HISTORY_FILE, [])
        if isinstance(h, dict) and isinstance(h.get("rows"), list):
            h = h.get("rows")
        if isinstance(h, list):
            V343_HISTORY = [dict(x) for x in h if isinstance(x, dict)][-V343_MAX_HISTORY:]
        s = load_json_file(PAPER_V343_STATE_FILE, {})
        if isinstance(s, dict):
            V343_STATE.update({k: v for k, v in s.items() if k in {"processed", "alerted", "directed", "last_scan_ts"}})
        for k in ["processed", "alerted", "directed"]:
            if not isinstance(V343_STATE.get(k), dict):
                V343_STATE[k] = {}
    except Exception as e:
        try: append_runtime_error_log("v343_load_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v343_save_state():
    try:
        now_ts = _v343_now()
        q = {}
        for t, r in list((V343_QUEUE or {}).items()):
            if not isinstance(r, dict):
                continue
            if now_ts - safe_float(r.get("first_ts", now_ts), now_ts) <= V343_MAX_KEEP_SEC:
                q[str(t).upper()] = dict(r)
        save_json_file(PAPER_V343_QUEUE_FILE, {"schema": PAPER_V343_SCHEMA, "updated_ts": now_ts, "queue": q})
        save_json_file(PAPER_V343_HISTORY_FILE, [dict(x) for x in list(V343_HISTORY or [])[-V343_MAX_HISTORY:] if isinstance(x, dict)])
        processed = V343_STATE.get("processed", {}) if isinstance(V343_STATE, dict) else {}
        if isinstance(processed, dict) and len(processed) > 1200:
            processed = dict(list(processed.items())[-1200:])
        alerted = V343_STATE.get("alerted", {}) if isinstance(V343_STATE, dict) else {}
        if isinstance(alerted, dict):
            alerted = {k: v for k, v in alerted.items() if now_ts - safe_float(v, 0) <= V343_ALERT_COOLDOWN_SEC * 2}
        directed = V343_STATE.get("directed", {}) if isinstance(V343_STATE, dict) else {}
        if isinstance(directed, dict):
            directed = {k: v for k, v in directed.items() if now_ts - safe_float(v, 0) <= V343_DIRECT_COOLDOWN_SEC * 3}
        save_json_file(PAPER_V343_STATE_FILE, {
            "schema": PAPER_V343_SCHEMA, "updated_ts": now_ts,
            "processed": processed if isinstance(processed, dict) else {},
            "alerted": alerted if isinstance(alerted, dict) else {},
            "directed": directed if isinstance(directed, dict) else {},
            "last_scan_ts": safe_float(V343_STATE.get("last_scan_ts", 0), 0) if isinstance(V343_STATE, dict) else 0,
        })
    except Exception as e:
        try: append_runtime_error_log("v343_save_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v343_blob(*objs) -> str:
    try:
        if callable(globals().get("_v342_blob")):
            return _v342_blob(*objs)
    except Exception:
        pass
    parts = []
    try:
        for obj in objs:
            if isinstance(obj, dict):
                for k in ["ticker", "route", "lane", "trigger", "mode", "decision", "final_decision", "register_reason", "reason", "why", "note", "close_reason", "cancel_reason"]:
                    v = obj.get(k)
                    if v not in (None, "", [], {}):
                        parts.append(str(v))
                try: parts.extend([str(x) for x in list(obj.get("reasons", []) or [])[:8]])
                except Exception: pass
            elif obj is not None:
                parts.append(str(obj))
    except Exception:
        pass
    return " / ".join(parts)[:4000]
def _v343_source_key(row: dict, src: str) -> str:
    try:
        t = _v343_ticker(row) or "UNKNOWN"
        key = str((row or {}).get("key", "") or (row or {}).get("cancel_watch_key", "") or (row or {}).get("paper_pos_id", "") or "")
        ts = int(safe_float((row or {}).get("cancel_ts", (row or {}).get("registered_ts", (row or {}).get("created_ts", (row or {}).get("closed_at", 0)))), 0))
        return f"{src}:{t}:{key}:{ts}"
    except Exception:
        return f"{src}:unknown:{int(_v343_now())}"
def _v343_already_processed(key: str) -> bool:
    try:
        return str(key) in (V343_STATE.get("processed", {}) if isinstance(V343_STATE, dict) else {})
    except Exception:
        return False
def _v343_mark_processed(key: str):
    try:
        V343_STATE.setdefault("processed", {})[str(key)] = _v343_now()
    except Exception:
        pass
def _v343_enqueue(row: dict, src: str, why: str) -> bool:
    global V343_QUEUE
    try:
        row = row if isinstance(row, dict) else {}
        ticker = _v343_ticker(row)
        if not ticker:
            return False
        if callable(globals().get("_v336_has_active_ticker")) and _v336_has_active_ticker(ticker):
            _v343_inc("queue_duplicate", f"이미진행중 {ticker}")
            return False
        ok, route_why = _v343_is_good_pullback_source(row, src)
        if not ok:
            return False
        now_ts = _v343_now()
        rec = V343_QUEUE.get(ticker)
        if isinstance(rec, dict):
            rec["last_seen_ts"] = now_ts
            rec["seen_count"] = int(safe_float(rec.get("seen_count", 1), 1)) + 1
            rec["last_reason"] = str(why or route_why)[:220]
            V343_QUEUE[ticker] = rec
            _v343_inc("queue_duplicate", f"눌림복구대기 중복 {ticker}")
            return True
        if len(V343_QUEUE or {}) >= V343_MAX_QUEUE:
            old = sorted((V343_QUEUE or {}).items(), key=lambda kv: safe_float((kv[1] or {}).get("first_ts", now_ts), now_ts))[:10]
            for old_t, _old in old[:max(1, len(V343_QUEUE) - V343_MAX_QUEUE + 1)]:
                V343_QUEUE.pop(old_t, None)
        price = safe_float(row.get("price", row.get("current_price", row.get("last_price", row.get("cancel_price", 0)))), 0)
        rec = {
            "schema": PAPER_V343_SCHEMA, "ticker": ticker, "first_ts": now_ts, "last_seen_ts": now_ts,
            "next_check_ts": now_ts + V343_FIRST_CHECK_SEC, "deadline_ts": now_ts + V343_SECOND_CHECK_SEC,
            "expire_ts": now_ts + V343_MAX_KEEP_SEC, "status": "WAIT_V313_PULLBACK_RESTORE",
            "source": str(src or "")[:80], "why": str(why or route_why)[:260], "route_why": str(route_why)[:260],
            "start_price": price, "last_price": price, "best_pct": 0.0, "checks": 0,
            "origin_blob": _v343_blob(row, src)[:900],
            "source_row": {k: row.get(k) for k in list(row.keys())[:80]} if isinstance(row, dict) else {},
        }
        V343_QUEUE[ticker] = rec
        _v343_inc("queued", f"v313눌림복구대기 {ticker}/{route_why}")
        return True
    except Exception as e:
        try: append_runtime_error_log("v343_enqueue", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return False
def _v343_collect_sources() -> list:
    rows = []
    try:
        if callable(globals().get("_v313_cancel_rows")):
            for r in list(_v313_cancel_rows(limit=100) or []):
                if isinstance(r, dict):
                    rows.append(("cancel_watch", r)); _v343_inc("source_cancel")
    except Exception:
        pass
    try:
        if callable(globals().get("_v313_active_queue_rows")):
            for r in list(_v313_active_queue_rows(limit=100) or []):
                if isinstance(r, dict):
                    rows.append(("v313_queue", r)); _v343_inc("source_v313")
    except Exception:
        pass
    try:
        if callable(globals().get("_v313_load_state")):
            st = _v313_load_state(force=False) or {}
            for r in list((st or {}).values())[:120]:
                if isinstance(r, dict):
                    rows.append(("v313_state", r)); _v343_inc("source_v313")
    except Exception:
        pass
    try:
        active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
        for r in list((active or {}).values())[:40] if isinstance(active, dict) else []:
            if isinstance(r, dict):
                rows.append(("review_active", r)); _v343_inc("source_review")
        for r in list(logs or [])[-80:]:
            if isinstance(r, dict):
                rows.append(("review_log", r)); _v343_inc("source_review")
    except Exception:
        pass
    return rows
def _v343_scan_sources(force: bool = False) -> int:
    linked = 0
    try:
        now_ts = _v343_now()
        if not force and now_ts - safe_float(V343_STATE.get("last_scan_ts", 0), 0) < V343_SCAN_INTERVAL_SEC:
            return 0
        V343_STATE["last_scan_ts"] = now_ts
        _v343_inc("scan", "v343 눌림 route 스캔")
        for src, row in _v343_collect_sources()[:180]:
            key = _v343_source_key(row, src)
            if _v343_already_processed(key):
                continue
            ok, why = _v343_is_good_pullback_source(row, src)
            if not ok:
                continue
            _v343_inc("candidate", f"복구후보 {_v343_ticker(row)}/{why}")
            if _v343_enqueue(row, src, why):
                linked += 1
                _v343_mark_processed(key)
        _v343_save_state()
    except Exception as e:
        try: append_runtime_error_log("v343_scan_sources", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return linked
