def _v345_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v345_inc(key: str, note: str = ""):
    try:
        V345_STATS[key] = int(safe_float(V345_STATS.get(key, 0), 0)) + 1
        if note:
            V345_STATS["last_note"] = str(note)[:240]
    except Exception:
        pass
def _v345_load_state():
    global V345_STATE
    try:
        data = load_json_file(PAPER_V345_STATE_FILE, {})
        if isinstance(data, dict):
            cache = data.get("route_hint_cache", {}) if isinstance(data.get("route_hint_cache", {}), dict) else {}
            samples = data.get("route_samples", []) if isinstance(data.get("route_samples", []), list) else []
            if len(cache) > V345_MAX_HINT_CACHE:
                cache = dict(list(cache.items())[-V345_MAX_HINT_CACHE:])
            V345_STATE = {"route_hint_cache": cache, "route_samples": samples[-V345_ROUTE_SAMPLE_MAX:]}
    except Exception as e:
        try: append_runtime_error_log("v345_load_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
        V345_STATE = {"route_hint_cache": {}, "route_samples": []}
def _v345_save_state():
    try:
        cache = V345_STATE.get("route_hint_cache", {}) if isinstance(V345_STATE, dict) else {}
        if isinstance(cache, dict) and len(cache) > V345_MAX_HINT_CACHE:
            V345_STATE["route_hint_cache"] = dict(list(cache.items())[-V345_MAX_HINT_CACHE:])
        samples = V345_STATE.get("route_samples", []) if isinstance(V345_STATE, dict) else []
        if isinstance(samples, list):
            V345_STATE["route_samples"] = samples[-V345_ROUTE_SAMPLE_MAX:]
        save_json_file(PAPER_V345_STATE_FILE, {"schema": PAPER_V345_SCHEMA, "updated_ts": _v345_now(), **(V345_STATE if isinstance(V345_STATE, dict) else {})})
    except Exception as e:
        try: append_runtime_error_log("v345_save_state", str(e), exc=e, include_traceback=False)
        except Exception: pass
def _v345_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v344_ticker")):
            return _v344_ticker(row)
        if callable(globals().get("_v337_ticker")):
            return _v337_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        elif isinstance(row, dict):
            t = row.get("ticker", row.get("symbol", row.get("market", "")))
        else:
            t = ""
        t = str(t or "").upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        if t.endswith("_KRW"):
            t = t[:-4]
        return t.strip()
    except Exception:
        return ""
def _v345_text(row: dict, keys: list, default: str = "") -> str:
    try:
        row = row if isinstance(row, dict) else {}
        for k in keys:
            v = row.get(k)
            if v is None:
                continue
            s = str(v).strip()
            if s and s not in {"[]", "{}", "None", "none", "nan"}:
                return s
    except Exception:
        pass
    return str(default or "")
def _v345_missing_text(v) -> bool:
    try:
        s = str(v or "").strip()
        if not s:
            return True
        low = s.lower()
        return low in {
            "unknown", "unknown_explicit", "central_hub_missing", "central_missing", "missing", "row_only", "none", "nan",
            "v336_entry_reject", "v344_no_base_context"
        }
    except Exception:
        return True
def _v345_hint_from_row(row: dict, src: str = "input") -> dict:
    try:
        row = row if isinstance(row, dict) else {}
        ticker = _v345_ticker(row)
        if not ticker:
            return {}
        route = _v345_text(row, [
            "route", "lane", "entry_rule", "strategy", "route_name", "candidate_route", "signal_route",
            "rank_watch_action", "primary_reason", "status_text", "watch_status", "review_status", "result_type",
            "trigger", "mode", "path", "close_reason", "cancel_reason"
        ])
        decision = _v345_text(row, [
            "final_decision", "decision", "signal_decision", "final_judgement", "final_class", "final_candidate_action_v251",
            "rank_watch_action", "reason", "why", "note", "comment", "register_reason", "cancel_reason", "close_reason"
        ])
        grade = _v345_text(row, ["grade", "signal_grade", "original_grade", "candidate_grade", "final_candidate_state_v251", "score_grade"])
        chart = _v345_text(row, ["chart_status", "chart_quality_code", "current_candle_label", "current_candle_code", "rank_watch_chart_state"])
        blob = " / ".join([route, decision, grade, chart])[:1000]
        if _v345_missing_text(route):
            for kw in [
                "cancel_reentry", "v313", "강한놓침 눌림감시", "강한놓침", "눌림감시", "눌림", "재출발", "재진입",
                "고점 재돌파 유지 확인", "순위권 정밀검토", "실시간 폭발 초입", "초입 강세", "강세 후 유지",
                "preview_command_only", "blocked_v267_discard", "매도반전", "식는 체결흐름"
            ]:
                if kw in blob:
                    route = kw
                    break
        if _v345_missing_text(decision):
            decision = route
        if _v345_missing_text(route) and _v345_missing_text(decision) and _v345_missing_text(grade) and _v345_missing_text(chart):
            return {}
        hint = {
            "ticker": ticker,
            "route": str(route or "")[:160],
            "decision": str(decision or "")[:220],
            "grade": str(grade or "")[:100],
            "chart": str(chart or "")[:140],
            "src": str(src or "input")[:80],
            "ts": _v345_now(),
        }
        return hint
    except Exception as e:
        try: append_runtime_error_log("v345_hint_from_row", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return {}
def _v345_cache_hint(hint: dict):
    try:
        if not isinstance(hint, dict) or not hint.get("ticker"):
            return
        t = _v345_ticker(hint.get("ticker"))
        if not t:
            return
        cache = V345_STATE.setdefault("route_hint_cache", {})
        old = cache.get(t, {}) if isinstance(cache, dict) else {}
        merged = dict(old) if isinstance(old, dict) else {}
        for k in ["route", "decision", "grade", "chart", "src"]:
            if _v345_missing_text(merged.get(k)) and not _v345_missing_text(hint.get(k)):
                merged[k] = hint.get(k)
            elif k == "src" and hint.get(k):
                merged[k] = hint.get(k)
        merged["ticker"] = t
        merged["ts"] = _v345_now()
        cache[t] = merged
        if len(cache) > V345_MAX_HINT_CACHE:
            V345_STATE["route_hint_cache"] = dict(list(cache.items())[-V345_MAX_HINT_CACHE:])
    except Exception:
        pass
def _v345_recent_source_rows() -> list:
    rows = []
    try:
        for r in list(globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS", []) or [])[-90:]:
            if isinstance(r, dict):
                rows.append(("rank_hint", r)); _v345_inc("hint_rank")
    except Exception:
        pass
    try:
        active, logs = _get_internal_watch_state_parts() if callable(globals().get("_get_internal_watch_state_parts")) else ({}, [])
        if isinstance(active, dict):
            for r in list(active.values())[-80:]:
                if isinstance(r, dict):
                    rows.append(("review_active", r)); _v345_inc("hint_review")
        for r in list(logs or [])[-120:]:
            if isinstance(r, dict):
                rows.append(("review_log", r)); _v345_inc("hint_review")
    except Exception:
        pass
    try:
        if callable(globals().get("_v339_load_rows")):
            for r in list(_v339_load_rows() or [])[-120:]:
                if isinstance(r, dict):
                    rows.append(("paper_log", r)); _v345_inc("hint_paper")
    except Exception:
        pass
    try:
        if callable(globals().get("_v339_load_attempts")):
            for r in list(_v339_load_attempts() or [])[-120:]:
                if isinstance(r, dict):
                    ec = r.get("entry_context") if isinstance(r.get("entry_context"), dict) else None
                    rows.append(("paper_attempt", ec or r)); _v345_inc("hint_attempt")
    except Exception:
        pass
    return rows[-V345_MAX_HINT_SCAN_ROWS:]
def _v345_find_route_hint(ticker: str, input_row: dict = None, trigger: str = "") -> dict:
    try:
        t = _v345_ticker(ticker or input_row)
        if not t:
            return {}
        _v345_inc("hint_scan", f"route힌트탐색 {t}")
        if isinstance(input_row, dict):
            hint = _v345_hint_from_row(input_row, "input:" + str(trigger or ""))
            if hint and hint.get("ticker") == t:
                _v345_inc("hint_input", f"입력row힌트 {t}")
                _v345_cache_hint(hint)
                _v345_inc("hint_found", f"힌트발견 {t}/{hint.get('src')}")
                return hint
        cache = V345_STATE.get("route_hint_cache", {}) if isinstance(V345_STATE, dict) else {}
        cached = cache.get(t) if isinstance(cache, dict) else None
        if isinstance(cached, dict) and not (_v345_missing_text(cached.get("route")) and _v345_missing_text(cached.get("decision"))):
            _v345_inc("hint_found", f"힌트캐시 {t}/{cached.get('src','')}")
            return dict(cached)
        for src, row in _v345_recent_source_rows():
            if _v345_ticker(row) != t:
                continue
            hint = _v345_hint_from_row(row, src)
            if hint:
                _v345_cache_hint(hint)
                _v345_inc("hint_found", f"힌트발견 {t}/{src}")
                return hint
    except Exception as e:
        try: append_runtime_error_log("v345_find_route_hint", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return {}
def _v345_enrich_row_with_hint(row: dict, hint: dict, source: str = "central") -> tuple:
    try:
        if not isinstance(row, dict) or not isinstance(hint, dict) or not hint:
            return row, False
        out = dict(row)
        changed = False
        route_hint = str(hint.get("route", "") or "").strip()
        decision_hint = str(hint.get("decision", "") or "").strip()
        grade_hint = str(hint.get("grade", "") or "").strip()
        chart_hint = str(hint.get("chart", "") or "").strip()
        if route_hint and _v345_missing_text(out.get("route")):
            out["route"] = route_hint[:160]; changed = True
        if route_hint and _v345_missing_text(out.get("lane")):
            out["lane"] = route_hint[:160]; changed = True
        if decision_hint and _v345_missing_text(out.get("final_decision")):
            out["final_decision"] = decision_hint[:220]; changed = True
        if decision_hint and _v345_missing_text(out.get("decision")):
            out["decision"] = decision_hint[:220]; changed = True
        if decision_hint and _v345_missing_text(out.get("signal_decision")):
            out["signal_decision"] = decision_hint[:220]; changed = True
        if grade_hint and _v345_missing_text(out.get("grade")):
            out["grade"] = grade_hint[:100]; changed = True
        if grade_hint and _v345_missing_text(out.get("signal_grade")):
            out["signal_grade"] = grade_hint[:100]; changed = True
        if chart_hint and _v345_missing_text(out.get("chart_status")):
            out["chart_status"] = chart_hint[:140]; changed = True
        if chart_hint and _v345_missing_text(out.get("chart_quality_code")):
            out["chart_quality_code"] = chart_hint[:140]; changed = True
        if changed:
            out["v345_route_decision_boost"] = True
            out["v345_boost_source"] = str(hint.get("src", source) or source)[:80]
            out["v345_boost_note"] = "가격/차트는 중앙허브 유지, route/decision/grade만 소스 row에서 보강"
            out.setdefault("source", row.get("source", source))
        return out, changed
    except Exception as e:
        try: append_runtime_error_log("v345_enrich_row", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return row, False
def _v345_apply_hint_to_central_tables(ticker: str, hint: dict) -> int:
    patched = 0
    try:
        t = _v345_ticker(ticker)
        if not t or not isinstance(hint, dict) or not hint:
            return 0
        for table_name in ["DATA_FACTORY_V294_STAGE2", "DATA_FACTORY_V294_STAGE1"]:
            table = globals().get(table_name, {})
            if not isinstance(table, dict):
                continue
            key = None
            for k in [t, t.upper(), "KRW-" + t, t + "_KRW"]:
                if isinstance(table.get(k), dict):
                    key = k; break
            if key is None:
                continue
            row2, changed = _v345_enrich_row_with_hint(table.get(key, {}), hint, table_name)
            if changed:
                table[key] = row2
                patched += 1
                _v345_inc("factory_table_patch", f"factory route보강 {t}/{table_name}")
        cache = globals().get("shared_market_cache", {})
        if isinstance(cache, dict):
            key = None
            for k in [t, t.upper(), "KRW-" + t, t + "_KRW"]:
                if isinstance(cache.get(k), dict):
                    key = k; break
            if key is not None:
                row2, changed = _v345_enrich_row_with_hint(cache.get(key, {}), hint, "shared_market_cache")
                if changed:
                    cache[key] = row2
                    patched += 1
                    _v345_inc("shared_table_patch", f"shared route보강 {t}")
    except Exception as e:
        try: append_runtime_error_log("v345_apply_hint_tables", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return patched
def _v345_record_sample(ticker: str, hint: dict, where: str, changed: bool):
    try:
        sample = {
            "ts": _v345_now(), "ticker": _v345_ticker(ticker), "where": str(where or "")[:80], "changed": bool(changed),
            "route": str((hint or {}).get("route", ""))[:120], "decision": str((hint or {}).get("decision", ""))[:160],
            "grade": str((hint or {}).get("grade", ""))[:80], "src": str((hint or {}).get("src", ""))[:80],
        }
        arr = V345_STATE.setdefault("route_samples", [])
        if isinstance(arr, list):
            arr = [x for x in arr if not (isinstance(x, dict) and x.get("ticker") == sample["ticker"] and x.get("where") == sample["where"])]
            arr.append(sample)
            V345_STATE["route_samples"] = arr[-V345_ROUTE_SAMPLE_MAX:]
    except Exception:
        pass
try:
    _BASE_V337_GET_CENTRAL_ENTRY_ROW_V345 = globals().get('_v337_get_central_entry_row')
except Exception:
    _BASE_V337_GET_CENTRAL_ENTRY_ROW_V345 = None
def _v337_get_central_entry_row(ticker: str, allow_refresh: bool = True) -> tuple:
    row, src, ts, invalid = ({}, "central_missing", 0.0, ["central_hub_missing"])
    try:
        if callable(_BASE_V337_GET_CENTRAL_ENTRY_ROW_V345):
            row, src, ts, invalid = _BASE_V337_GET_CENTRAL_ENTRY_ROW_V345(ticker, allow_refresh=allow_refresh)
    except Exception as e:
        try: append_runtime_error_log("v345_get_central_base", str(e), exc=e, include_traceback=False)
        except Exception: pass
        row, src, ts, invalid = {}, "central_missing", 0.0, ["central_hub_error"]
    try:
        if isinstance(row, dict) and row:
            t = _v345_ticker(ticker or row)
            hint = _v345_find_route_hint(t, None, "central_row")
            if hint:
                _v345_inc("central_patch_try", f"중앙route보강시도 {t}")
                row2, changed = _v345_enrich_row_with_hint(row, hint, src)
                if changed:
                    _v345_inc("central_patch_success", f"중앙route보강 {t}/{hint.get('src','')}")
                    _v345_apply_hint_to_central_tables(t, hint)
                    _v345_record_sample(t, hint, "central", True)
                    return row2, src, ts, invalid
                _v345_inc("central_patch_fail", f"중앙route보강불필요 {t}")
    except Exception as e:
        _v345_inc("central_patch_fail", f"중앙route보강오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v345_get_central_patch", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return row, src, ts, invalid
try:
    _BASE_V337_BUILD_ENTRY_CONTEXT_V345 = globals().get('_v337_build_entry_context')
except Exception:
    _BASE_V337_BUILD_ENTRY_CONTEXT_V345 = None
def _v337_build_entry_context(row: dict, trigger: str = "") -> tuple:
    ctx, merged, invalid = ({}, dict(row or {}) if isinstance(row, dict) else {}, ["v345_no_base_context"])
    try:
        if callable(_BASE_V337_BUILD_ENTRY_CONTEXT_V345):
            ctx, merged, invalid = _BASE_V337_BUILD_ENTRY_CONTEXT_V345(row if isinstance(row, dict) else {}, trigger=trigger)
    except Exception as e:
        try: append_runtime_error_log("v345_build_context_base", str(e), exc=e, include_traceback=False)
        except Exception: pass
        ctx, merged, invalid = ({"schema": PAPER_V345_SCHEMA, "error": str(e)[:120]}, dict(row or {}) if isinstance(row, dict) else {}, ["v345_context_base_error"])
    try:
        t = _v345_ticker((ctx or {}).get("ticker") or (merged or {}).get("ticker") or row)
        hint = _v345_find_route_hint(t, row if isinstance(row, dict) else {}, str(trigger or "context"))
        if hint:
            _v345_inc("ctx_patch_try", f"context route보강시도 {t}")
            merged2, ch_m = _v345_enrich_row_with_hint(merged if isinstance(merged, dict) else {}, hint, "merged")
            ctx2, ch_c = _v345_enrich_row_with_hint(ctx if isinstance(ctx, dict) else {}, hint, "ctx")
            if ch_m or ch_c:
                if isinstance(ctx2, dict):
                    if not _v345_missing_text(ctx2.get("route")):
                        ctx2["route"] = str(ctx2.get("route"))[:120]
                    if not _v345_missing_text(ctx2.get("final_decision")):
                        ctx2["final_decision"] = str(ctx2.get("final_decision"))[:180]
                    ctx2["v345_route_decision_boost"] = True
                    ctx2["v345_boost_source"] = str(hint.get("src", "") or "")[:80]
                if isinstance(merged2, dict):
                    merged2["v345_route_decision_boost"] = True
                _v345_apply_hint_to_central_tables(t, hint)
                _v345_record_sample(t, hint, "context", True)
                _v345_inc("ctx_patch_success", f"context route보강 {t}/{hint.get('src','')}")
                return ctx2, merged2, list(dict.fromkeys([str(x) for x in (invalid or []) if x]))
            _v345_inc("ctx_patch_fail", f"context route보강불필요 {t}")
    except Exception as e:
        _v345_inc("ctx_patch_fail", f"context route보강오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v345_context_patch", str(e), exc=e, include_traceback=False)
        except Exception: pass
