def _v344_factory_probe(ticker: str) -> dict:
    probe = _BASE_V344_FACTORY_PROBE_V345(ticker) if callable(_BASE_V344_FACTORY_PROBE_V345) else {"ticker": _v345_ticker(ticker)}
    try:
        t = _v345_ticker(ticker)
        if not isinstance(probe, dict):
            probe = {"ticker": t}
        route_values = [str(probe.get(k, "") or "").strip() for k in ["factory2_route", "factory1_route", "shared_route"]]
        if not any(route_values):
            hint = _v345_find_route_hint(t, None, "factory_probe")
            if hint and not _v345_missing_text(hint.get("route") or hint.get("decision")):
                route_hint = str(hint.get("route") or hint.get("decision") or "")[:100]
                if probe.get("factory2"):
                    probe["factory2_route"] = route_hint
                elif probe.get("factory1"):
                    probe["factory1_route"] = route_hint
                elif probe.get("shared"):
                    probe["shared_route"] = route_hint
                probe["v345_route_hint"] = route_hint
                probe["v345_route_hint_src"] = str(hint.get("src", ""))[:80]
                _v345_apply_hint_to_central_tables(t, hint)
                _v345_inc("row_only_route_fixed", f"route_missing보강 {t}/{hint.get('src','')}")
            else:
                _v345_inc("row_only_route_still_missing", f"route_missing유지 {t}")
    except Exception as e:
        try: append_runtime_error_log("v345_factory_probe", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return probe
def _v345_cycle(force: bool = False):
    try:
        touched = 0
        for src, row in _v345_recent_source_rows():
            if touched >= 60 and not force:
                break
            hint = _v345_hint_from_row(row, src)
            if hint:
                _v345_cache_hint(hint)
                _v345_apply_hint_to_central_tables(hint.get("ticker", ""), hint)
                touched += 1
        _v345_save_state()
    except Exception as e:
        try: append_runtime_error_log("v345_cycle", str(e), exc=e, include_traceback=False)
        except Exception: pass
