        arr = V346_STATE.setdefault("samples", [])
        if isinstance(arr, list):
            arr = [x for x in arr if not (isinstance(x, dict) and x.get("ticker") == sample["ticker"] and x.get("kind") == sample["kind"])]
            arr.append(sample)
