V347_SCAN_INTERVAL_SEC = 5.0
V347_HEAVY_CYCLE_MIN_GAP_SEC = 10.0
V347_MAX_BRIDGE_PER_CYCLE = 8
V347_MAX_SAMPLES = 18
V347_STATE = {"last_scan_ts": 0.0, "last_heavy_ts": 0.0, "bridged": {}, "samples": []}
