def _send_fast_scan_alerts(items, now_ts: float):
    try:
        before_keys = set((recent_signal_alerts or {}).keys()) if isinstance(recent_signal_alerts, dict) else set()
        candidate_n = 0
        for item in list(items or []):
            if not isinstance(item, dict):
                continue
            if str(item.get("alert_bucket", "")) == "user_alert" and str(item.get("alert_grade", "")) in {"S", "A"}:
                candidate_n += 1
                _v348_inc("actual_buy_push_try", f"fast BUY_READY 후보 {_v348_ticker(item)}")
        res = _BASE_SEND_FAST_SCAN_ALERTS_V348(items, now_ts) if callable(_BASE_SEND_FAST_SCAN_ALERTS_V348) else None
        after_keys = set((recent_signal_alerts or {}).keys()) if isinstance(recent_signal_alerts, dict) else set()
        sent_n = max(0, len(after_keys - before_keys))
        for _ in range(sent_n):
            _v348_inc("actual_buy_push_after", "fast 실제푸시 증가")
        if candidate_n and sent_n <= 0:
            _v348_inc("router_drop", "fast 후보는 있었지만 실제푸시 증가 없음")
        return res
    except Exception as e:
        _v348_inc("router_drop", f"fast_alert 오류 {e.__class__.__name__}")
        try: append_runtime_error_log("v348_fast_alert_wrap", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return _BASE_SEND_FAST_SCAN_ALERTS_V348(items, now_ts) if callable(_BASE_SEND_FAST_SCAN_ALERTS_V348) else None
