def _v349_suspect_causes() -> list:
    causes = []
    try:
        v348 = globals().get("V348_STATS", {}) if isinstance(globals().get("V348_STATS", {}), dict) else {}
        v343 = _v349_dict("V343_STATS")
        v344 = _v349_dict("V344_STATS")
        v341 = _v349_dict("V341_STATS")
        v342 = _v349_dict("V342_STATS")
        v336 = _v349_dict("V336_STATS")
        active_n, open_n, pending_n = _v349_paper_counts()
        max_active = int(safe_float(globals().get("PAPER_MAX_ACTIVE", 24), 24))
        _top, by_kind = _v349_recent_reject_summary(100)
        chart = _v349_chart_trust_summary()
        buy_try = int(safe_float(v348.get("actual_buy_push_try", 0), 0))
        if buy_try <= 0:
            causes.append(("BUY_READY 후보 생성 0", "PENDING/내부감시 이후 최종 매수신호로 승격되는 입구가 비어 있거나 호출되지 않음"))
            _v349_inc("buy_path_no_try_seen")
        if int(safe_float(v343.get("direct_success", 0), 0)) > 0 and buy_try <= 0:
            causes.append(("v343 성공 후 승격 없음", "눌림대기/PENDING 복구는 됐지만 재확인→BUY_READY 경로가 이어지지 않음"))
        if pending_n >= max(1, max_active - 1):
            causes.append(("paper PENDING 포화", f"paper 전체 {active_n}/{max_active}, PENDING {pending_n}. 표본 등록은 막지만 실제 알림 제한과 분리해서 봐야 함"))
        if by_kind.get("chart_unverified", 0) >= 3 or chart.get("chart_unverified", 0) >= 3:
            causes.append(("차트미검증 다수", "진짜 약해서 탈락한 것과 정밀차트가 없어서 보류된 것을 분리해야 함"))
        if by_kind.get("grade_c", 0) >= 3:
            causes.append(("C등급 거절 다수", "route/grade 누락 때문에 좋은 후보가 C로 떨어지는지 확인 필요"))
        if by_kind.get("final_not_buy", 0) >= 3:
            causes.append(("최종판정매수아님 다수", "최종 게이트에서 무엇을 보고 거절했는지 세부 원인 분해 필요"))
        if by_kind.get("weak_flow", 0) >= 3:
            causes.append(("약한 흐름 거절 다수", "매도우세/위꼬리/단기음수는 대부분 푸시 금지가 맞지만 실제 차트와 불일치 여부 확인 필요"))
        if int(safe_float(v344.get("row_only_all_missing", 0), 0)) > 0 or int(safe_float(v344.get("row_only_factory2_missing", 0), 0)) > 0:
            causes.append(("허브/source 누락 누적", "factory2/shared/price/source 누락 때문에 좋은 후보도 row_only로 남을 수 있음"))
        if int(safe_float(v341.get("row_bridge_fail", 0), 0)) > int(safe_float(v341.get("row_bridge_success", 0), 0)) and int(safe_float(v341.get("row_bridge_fail", 0), 0)) > 0:
            causes.append(("v341 내부감시 브릿지 실패", "내부감시에서 강한 후보를 v340/v343 쪽으로 태우는 등록브릿지가 실패 중"))
        if int(safe_float(v342.get("reupgrade_success", 0), 0)) <= 0 and int(safe_float(v342.get("reupgrade_try", 0), 0)) > 0:
            causes.append(("v342 재승격 실패", "성과 좋던 눌림 route가 재확인 후 BUY_READY로 못 올라감"))
        market_age = _v349_now() - safe_float(globals().get("shared_market_cache_time", 0), 0) if safe_float(globals().get("shared_market_cache_time", 0), 0) > 0 else 9999
        rank_age = _v349_now() - safe_float(globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS", 0), 0) if safe_float(globals().get("COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS", 0), 0) > 0 else 9999
        if market_age > 90 or rank_age > 90:
            causes.append(("데이터 최신성 낮음", f"시장캐시 {int(market_age)}초 / rank스냅샷 {int(rank_age)}초. 차트 판단을 과신하면 안 됨"))
    except Exception as e:
        causes.append(("진단 생성 오류", str(e)[:160]))
    out = []
    seen = set()
    for a, b in causes:
        if a not in seen:
            out.append((a, b)); seen.add(a)
    return out[:10]
