def _v350_now() -> float:
    try:
        return time.time()
    except Exception:
        return 0.0
def _v350_inc(key: str, note: str = ""):
    try:
        V350_STATS[key] = int(safe_float(V350_STATS.get(key, 0), 0)) + 1
        if note:
            V350_STATS["last_note"] = str(note)[:260]
    except Exception:
        pass
def _v350_ticker(row=None) -> str:
    try:
        if callable(globals().get("_v349_ticker")):
            return _v349_ticker(row)
    except Exception:
        pass
    try:
        if isinstance(row, str):
            t = row
        elif isinstance(row, dict):
            t = row.get("ticker", row.get("symbol", row.get("market", "")))
        else:
            t = ""
        t = str(t or "").upper().strip()
        if t.startswith("KRW-"):
            t = t.split("-", 1)[1]
        if t.endswith("_KRW"):
            t = t[:-4]
        return t
    except Exception:
        return ""
def _v350_blob(*objs) -> str:
    try:
        if callable(globals().get("_v349_blob")):
            return _v349_blob(*objs)
    except Exception:
        pass
    parts = []
    try:
        for obj in objs:
            if isinstance(obj, dict):
                for k in ["ticker", "status", "route", "lane", "trigger", "reason", "last_reason", "why", "note", "decision", "final_decision", "signal_decision", "register_reason", "close_reason", "cancel_reason", "kind", "grade", "signal_grade", "alert_bucket", "alert_grade", "one_liner", "primary_reason"]:
                    v = obj.get(k)
                    if v not in (None, "", [], {}):
                        parts.append(str(v))
                try:
                    parts.extend([str(x) for x in list(obj.get("reasons", []) or [])[:10]])
                except Exception:
                    pass
            elif obj is not None:
                parts.append(str(obj))
    except Exception:
        pass
    return " / ".join(parts)[:9000]
