def _v343_process_queue(force: bool = False) -> int:
    before_try = int(safe_float(_v350_dict("V343_STATS").get("direct_try", 0), 0))
    before_success = int(safe_float(_v350_dict("V343_STATS").get("direct_success", 0), 0))
    before_q = len(globals().get("V343_QUEUE", {}) or {}) if isinstance(globals().get("V343_QUEUE", {}), dict) else 0
    _v350_inc("v343_process_called", f"v343_process q{before_q}")
    try:
        res = _BASE_V343_PROCESS_QUEUE_V350(force=force) if callable(_BASE_V343_PROCESS_QUEUE_V350) else 0
        after_try = int(safe_float(_v350_dict("V343_STATS").get("direct_try", 0), 0))
        after_success = int(safe_float(_v350_dict("V343_STATS").get("direct_success", 0), 0))
        after_q = len(globals().get("V343_QUEUE", {}) or {}) if isinstance(globals().get("V343_QUEUE", {}), dict) else 0
        if after_try > before_try:
            _v350_inc("v343_process_made_direct_try", f"v343 direct_try +{after_try-before_try}")
        if after_success > before_success:
            _v350_inc("v343_process_made_direct_success", f"v343 direct_success +{after_success-before_success}")
        _v350_sample("v343_process", "", f"q {before_q}->{after_q} / direct_try {before_try}->{after_try} / success {before_success}->{after_success}")
        _v350_save_state()
        return res
    except Exception as e:
        _v350_sample("v343_process_error", "", str(e)[:200])
        try: append_runtime_error_log("v350_v343_process", str(e), exc=e, include_traceback=False)
        except Exception: pass
        raise
