V2120_DEPLOY_FILENAME = "수익형_v2.12.0.py"
def _v2120_bool_text(v) -> str:
    return "켜짐" if bool(v) else "꺼짐"
def _v2120_read_text_file(path: str, limit: int = 4000) -> str:
    try:
        if not path or not os.path.exists(path):
            return ""
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            return f.read(max(1, int(limit))).strip()
    except Exception:
        return ""
def _v2120_file_tail(path: str, max_bytes: int = 60000, max_lines: int = 80) -> str:
    try:
        if not path or not os.path.exists(path):
            return ""
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            if size > max_bytes:
                f.seek(max(0, size - max_bytes))
            raw = f.read(max_bytes)
        text = raw.decode("utf-8", errors="ignore")
        return "\n".join(text.splitlines()[-max_lines:]).strip()
    except Exception:
        return ""
def _v2120_read_deploy_target() -> str:
    try:
        path = data_file("DEPLOY_TARGET.txt")
        body = _v2120_read_text_file(path, limit=1000)
        if body:
            return body.splitlines()[0].strip()
    except Exception:
        pass
    return V2120_DEPLOY_FILENAME
def _v2120_uptime_sec() -> int:
    try:
        return max(0, int(time.time() - safe_float(globals().get("BOT_START_TS", time.time()), time.time())))
    except Exception:
        return 0
def _v2120_boot_state_text() -> str:
    sec = _v2120_uptime_sec()
    if sec < 300:
        return f"초기 수집중 ({format_elapsed_text(sec)} 경과)"
    return "정상 감시중"
def _v2120_count_positions_by_status() -> dict:
    out = {"total": 0, "open": 0, "pending": 0, "closed": 0}
    try:
        data = globals().get("paper_positions", None)
        if not isinstance(data, dict):
            data = load_json(data_file("paper_positions.json"), {}) if callable(globals().get("load_json")) else {}
        if isinstance(data, dict):
            rows = list(data.values())
        elif isinstance(data, list):
            rows = data
        else:
            rows = []
        out["total"] = len(rows)
        for r0 in rows:
            r = r0 if isinstance(r0, dict) else {}
            st = str(r.get("status", r.get("state", ""))).upper()
            if st == "OPEN":
                out["open"] += 1
            elif st == "PENDING":
                out["pending"] += 1
            elif st in {"CLOSED", "DONE", "EXIT"}:
                out["closed"] += 1
    except Exception:
        pass
    return out
def _v2120_cpu_sample(delay: float = 0.35) -> dict:
    def read_proc():
        with open('/proc/self/stat', 'r') as f:
            parts = f.read().split()
        utime = int(parts[13]); stime = int(parts[14])
        return time.time(), utime + stime
    try:
        clk = os.sysconf(os.sysconf_names.get('SC_CLK_TCK', 'SC_CLK_TCK'))
    except Exception:
        clk = 100
    try:
        t1, c1 = read_proc(); time.sleep(max(0.05, float(delay))); t2, c2 = read_proc()
        elapsed = max(0.001, t2-t1)
        cpu_single = ((c2-c1)/float(clk))/elapsed*100.0
        cores = max(1, os.cpu_count() or 1)
        return {"single": cpu_single, "total": cpu_single/cores, "cores": cores}
    except Exception:
        return {"single": 0.0, "total": 0.0, "cores": max(1, os.cpu_count() or 1)}
def _v2120_rss_mb() -> float:
    try:
        with open('/proc/self/status', 'r') as f:
            for line in f:
                if line.startswith('VmRSS:'):
                    kb = safe_float(line.split()[1], 0)
                    return kb/1024.0
    except Exception:
        pass
    return 0.0
