def _v2121_fnum(x, default=0.0):
    try:
        if x is None or x == "":
            return default
        return float(x)
    except Exception:
        return default
def _v2121_status(row: dict) -> str:
    try:
        return str((row or {}).get("status", (row or {}).get("state", ""))).upper()
    except Exception:
        return ""
def _v2121_load_json_file(path: str, default=None):
    if default is None:
        default = []
    try:
        if not path or not os.path.exists(path):
            return default
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            text = f.read().strip()
        if not text:
            return default
        return json.loads(text)
    except Exception:
        try:
            out = []
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        out.append(json.loads(line))
                    except Exception:
                        pass
            return out if out else default
        except Exception:
            return default
def _v2121_paper_log_path() -> str:
    return data_file("paper_trade_log_v336.json")
def _v2121_load_paper_rows() -> list:
    try:
        path = _v2121_paper_log_path()
        if not os.path.exists(path):
            return []
        mtime = os.path.getmtime(path)
        now = time.time()
        if (
            V2121_PAPER_CACHE.get("rows") is not None
            and V2121_PAPER_CACHE.get("mtime") == mtime
            and now - _v2121_fnum(V2121_PAPER_CACHE.get("ts"), 0) <= V2121_PAPER_CACHE_TTL_SEC
        ):
            return list(V2121_PAPER_CACHE.get("rows") or [])
        data = _v2121_load_json_file(path, [])
        if isinstance(data, dict):
            for k in ["rows", "items", "logs", "trades", "data"]:
                if isinstance(data.get(k), list):
                    data = data.get(k)
                    break
            else:
                data = list(data.values()) if all(isinstance(v, dict) for v in data.values()) else []
        if not isinstance(data, list):
            data = []
        rows = [r for r in data if isinstance(r, dict)]
        V2121_PAPER_CACHE.update({"mtime": mtime, "ts": now, "rows": rows})
        return list(rows)
    except Exception as e:
        try: append_runtime_error_log("v2121_load_paper_rows", str(e), exc=e, include_traceback=False)
        except Exception: pass
        return []
def _v2121_pnl(row: dict):
    for k in ["pnl_pct", "net_pct", "profit_pct", "result_pct", "return_pct", "realized_pct", "gross_pnl_pct"]:
        try:
            if k in row and row.get(k) not in [None, ""]:
                return _v2121_fnum(row.get(k), 0.0)
        except Exception:
            pass
    return None
def _v2121_row_text(row: dict) -> str:
    try:
        pieces = []
        for k in [
            "register_reason", "trigger", "lane", "entry_rule", "close_reason", "v343_source",
            "v343_origin", "note", "signal_grade", "original_grade", "v336_route", "v336_source",
        ]:
            v = row.get(k)
            if v not in [None, ""]:
                pieces.append(str(v))
        rs = row.get("reasons")
        if isinstance(rs, list):
            pieces.extend([str(x) for x in rs[:8]])
        elif rs:
            pieces.append(str(rs))
        return " / ".join(pieces)
    except Exception:
        return ""
def _v2121_route_bucket(row: dict) -> str:
    try:
        rr = str(row.get("register_reason", "") or "")
        src = str(row.get("v343_source", "") or "")
        lane = str(row.get("lane", "") or "")
        trigger = str(row.get("trigger", "") or "")
        cr = str(row.get("close_reason", "") or "")
        txt = _v2121_row_text(row).lower()
        if rr == "v340_real_wait_recheck" or src == "v346_v347_v340_real_queue":
            return "v340"
        if "현재 350 route" in rr or "v21019_current_350_route" in lane or "current_350" in txt:
            return "main350"
        if "v343_good_pullback_restore" in trigger or "v343:v342:v313_pullback_good_route" in rr or "cancel_reentry_forced_v313_pullback_v343" in lane:
            return "v343"
        if any(x in txt for x in ["entry_reject", "max_active", "rank_cache", "reject"]):
            return "hold"
        return "other"
    except Exception:
        return "other"
def _v2121_is_real_closed(row: dict) -> bool:
    try:
        if _v2121_status(row) != "CLOSED":
            return False
        pnl = _v2121_pnl(row)
        if pnl is None:
            return False
        txt = _v2121_row_text(row).lower()
        if any(x in txt for x in ["entry_reject", "max_active", "rank_cache"]):
            return False
        return True
    except Exception:
        return False
def _v2121_time_value(row: dict) -> float:
    for k in ["close_ts", "updated_ts", "entered_ts", "created_ts", "ts", "cancel_ts"]:
        try:
            v = _v2121_fnum((row or {}).get(k), 0)
            if v > 0:
                return v
        except Exception:
            pass
    return 0.0
def _v2121_recent_filter(rows: list, hours: float):
    try:
        now = time.time()
        cut = now - float(hours) * 3600.0
        return [r for r in rows if _v2121_time_value(r) >= cut]
    except Exception:
        return list(rows or [])
def _v2121_calc_stats(rows: list) -> dict:
    vals = []
    for r in rows or []:
        pnl = _v2121_pnl(r)
        if pnl is not None:
            vals.append(float(pnl))
    n = len(vals)
    wins = sum(1 for v in vals if v > 0)
    losses = sum(1 for v in vals if v < 0)
    total = sum(vals)
    gross_win = sum(v for v in vals if v > 0)
    gross_loss = -sum(v for v in vals if v < 0)
    pf = (gross_win / gross_loss) if gross_loss > 0 else (999.0 if gross_win > 0 else 0.0)
    avg_win = (gross_win / wins) if wins else 0.0
    avg_loss = (gross_loss / losses) if losses else 0.0
    return {"n": n, "wins": wins, "losses": losses, "total": total, "pf": pf, "avg_win": avg_win, "avg_loss": avg_loss}
def _v2121_stats_line(label: str, rows: list) -> str:
    s = _v2121_calc_stats(rows)
    if s["n"] <= 0:
        return f"- {label}: 종료 표본 없음"
    return f"- {label}: {s['n']}전 {s['wins']}승 {s['losses']}패 / 승률 {s['wins']/max(1,s['n'])*100:.1f}% / 누적 {s['total']:+.2f}% / PF {s['pf']:.2f} / 평균익 +{s['avg_win']:.2f}% / 평균손 -{s['avg_loss']:.2f}%"
def _v2121_count_paper_positions() -> dict:
    out = {"total": 0, "open": 0, "pending": 0, "closed": 0}
    try:
        data = globals().get("paper_positions", None)
        if not isinstance(data, (dict, list)):
            data = _v2121_load_json_file(data_file("paper_positions.json"), {})
        rows = list(data.values()) if isinstance(data, dict) else (data if isinstance(data, list) else [])
        out["total"] = len(rows)
        for r0 in rows:
            r = r0 if isinstance(r0, dict) else {}
            st = _v2121_status(r)
            if st == "OPEN": out["open"] += 1
            elif st == "PENDING": out["pending"] += 1
            elif st in {"CLOSED", "DONE", "EXIT"}: out["closed"] += 1
    except Exception:
        pass
    return out
def _v2121_hold_counts(rows: list) -> dict:
    out = {"REJECTED": 0, "CANCELLED": 0, "ZERO": 0, "OTHER": 0}
    try:
        for r in rows or []:
            st = _v2121_status(r)
            pnl = _v2121_pnl(r)
            if st in out:
                out[st] += 1
            elif pnl is not None and abs(float(pnl)) < 0.0001 and st != "CLOSED":
                out["ZERO"] += 1
            elif st and st != "CLOSED":
                out["OTHER"] += 1
    except Exception:
        pass
    return out
def _v2121_format_time(ts: float) -> str:
    try:
        if ts <= 0:
            return "시간없음"
        return datetime.fromtimestamp(ts, ZoneInfo(TIMEZONE)).strftime("%m-%d %H:%M")
    except Exception:
        try:
            return datetime.fromtimestamp(ts).strftime("%m-%d %H:%M")
        except Exception:
            return "시간없음"
