def _v2121_backup_paper_files_once() -> dict:
    result = {"dir": "", "copied": 0, "exists": 0, "missing": 0, "error": 0}
    try:
        import shutil
        backup_dir = data_file("paper_backup_v2121_pre_observe")
        os.makedirs(backup_dir, exist_ok=True)
        result["dir"] = backup_dir
        for name in V2121_PAPER_PRESERVE_FILES:
            src = data_file(name)
            dst = os.path.join(backup_dir, name)
            if not os.path.exists(src):
                result["missing"] += 1
                continue
            if os.path.exists(dst):
                result["exists"] += 1
                continue
            try:
                shutil.copy2(src, dst)
                result["copied"] += 1
            except Exception:
                result["error"] += 1
        globals()["V2121_PAPER_BACKUP_RESULT"] = result
    except Exception as e:
        result["error"] += 1
        try: append_runtime_error_log("v2121_backup_paper", str(e), exc=e, include_traceback=False)
        except Exception: pass
    return result
