def _v2122_row_has_price(row: dict) -> bool:
    for k in ["price", "current_price", "close", "last_price", "trade_price"]:
        try:
            if _v2121_fnum((row or {}).get(k), 0) > 0:
                return True
        except Exception:
            pass
    return False
def _v2122_row_has_source(row: dict) -> bool:
    try:
        for k in ["source", "cache_source", "candidate_source", "precision_chart_source", "data_source", "current_candle_source"]:
            if str((row or {}).get(k, "") or "").strip():
                return True
    except Exception:
        pass
    return False
def _v2122_route_label_missing_count(rows: list) -> dict:
    out = {"route": 0, "decision": 0, "grade": 0, "price": 0, "source": 0}
    try:
        for r in rows or []:
            if not isinstance(r, dict):
                continue
            if not str(r.get("route", r.get("entry_rule", r.get("register_reason", ""))) or "").strip():
                out["route"] += 1
            if not str(r.get("final_decision", r.get("decision", r.get("action_label", ""))) or "").strip():
                out["decision"] += 1
            if not str(r.get("signal_grade", r.get("grade", r.get("original_grade", ""))) or "").strip():
                out["grade"] += 1
            if not _v2122_row_has_price(r):
                out["price"] += 1
            if not _v2122_row_has_source(r):
                out["source"] += 1
    except Exception:
        pass
    return out
def _v2122_worker_snapshot() -> dict:
    out = {"total": 0, "command": 0, "paper": 0, "ohlcv": 0, "updater": 0, "other_named": []}
    try:
        ths = threading.enumerate()
        out["total"] = len(ths)
        for th in ths:
            nm = str(getattr(th, "name", "") or "")
            low = nm.lower()
            if "command" in low or "cache" in low:
                out["command"] += 1
            elif "paper" in low:
                out["paper"] += 1
            elif "ohlcv" in low or "prefetch" in low:
                out["ohlcv"] += 1
            elif "updater" in low or "telegram" in low or "bot:" in low:
                out["updater"] += 1
            elif nm and len(out["other_named"]) < 4:
                out["other_named"].append(nm[:40])
    except Exception:
        pass
    return out
