def _v2123_fnum(x, default=0.0):
    try:
        return float(x)
    except Exception:
        return default
def _v2123_short_age(ts) -> str:
    try:
        ts = _v2123_fnum(ts, 0)
        if ts <= 0:
            return "기록 없음"
        sec = max(0, int(time.time() - ts))
        if sec < 60:
            return f"{sec}초 전"
        if sec < 3600:
            return f"{sec//60}분 {sec%60}초 전"
        return f"{sec//3600}시간 {(sec%3600)//60}분 전"
    except Exception:
        return "확인불가"
def _v2123_safe_json_load(path, default=None):
    if default is None:
        default = {}
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
    except Exception:
        pass
    return default
def _v2123_safe_json_save(path, obj):
    try:
        tmp = path + ".tmp"
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(obj, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
        return True
    except Exception:
        return False
def _v2123_slow_stage_lines(limit=4):
    try:
        d = globals().get("COMMAND_DISPLAY_CACHE_STAGE_LAST_ROUND", {})
        if not isinstance(d, dict):
            return []
        rows = []
        for k, v in sorted(d.items(), key=lambda kv: _v2123_fnum(kv[1], 0), reverse=True)[:limit]:
            rows.append(f"{k} {float(_v2123_fnum(v, 0)):.2f}s")
        return rows
    except Exception:
        return []
def _v2123_cpu_brief() -> str:
    try:
        sample = _v2120_cpu_sample(0.12) if callable(globals().get('_v2120_cpu_sample')) else {"total": 0, "single": 0, "cores": os.cpu_count() or 1}
        total = _v2123_fnum(sample.get('total'), 0)
        if total < 55:
            return f"보통({total:.1f}%)"
        if total < 80:
            return f"주의({total:.1f}%)"
        return f"과열권({total:.1f}%)"
    except Exception:
        return "확인불가"
def _v2123_prepend_conclusion(title: str, conclusion_lines: list, body: str, reason_lines: list = None) -> str:
    reason_lines = list(reason_lines or [])
    parts = [str(body or "").strip()]
    if not parts[0].startswith(title):
        parts.insert(0, title)
    head = [title, "", "[결론]"] + [f"- {x}" for x in conclusion_lines]
    b_lines = str(body or "").splitlines()
    if b_lines and b_lines[0].strip() == title.strip():
        b_lines = b_lines[1:]
    out = head + b_lines
    if reason_lines:
        out += ["", "[이유/주의]"] + [f"- {x}" for x in reason_lines]
    return "\n".join(out).strip()
