def _v2123_format_batch_timing(rows: list, batch_start: float, source_label: str) -> str:
    try:
        lines = [
            "⏱ 명령어별 시간표",
            f"- 출처: {source_label}",
            f"- 전체 경과: {time.time()-batch_start:.2f}s",
        ]
        for r in rows[-12:]:
            lines.append(f"- /{r.get('cmd')}: 배치후 {r.get('after_start',0):.1f}s / 처리 {r.get('elapsed',0):.2f}s / 결과 {r.get('status','OK')}")
        slow = [r for r in rows if _v2123_fnum(r.get('elapsed'),0) >= 2.0]
        wait_slow = [r for r in rows if _v2123_fnum(r.get('after_start'),0) >= 10.0]
        lines += ["", "[느린 이유 후보]"]
        if slow:
            lines.append("- 실제 처리시간 긴 명령: " + ", ".join([f"/{r.get('cmd')} {r.get('elapsed'):.1f}s" for r in slow[:5]]))
        else:
            lines.append("- 실제 처리시간 긴 명령은 뚜렷하지 않음")
        if wait_slow:
            lines.append("- 배치 시작 뒤 늦게 출력된 명령 있음: 캐시 준비/텔레그램 큐/긴 review 조립 대기 가능")
        stage = ", ".join(_v2123_slow_stage_lines(4)) or "기록 없음"
        lines.append(f"- 최근 캐시 느린 작업: {stage}")
        lines.append("- 정확한 원인은 /cpu_status와 /scan_funnel의 직원/CPU 계측을 같이 본다")
        return "\n".join(lines)
    except Exception as e:
        return f"⏱ 명령어별 시간표\n- 생성 오류: {e.__class__.__name__}: {str(e)[:120]}"
