def _v2125_sha(path: str) -> str:
    try:
        import hashlib; h=hashlib.sha256()
        with open(path,'rb') as f:
            for b in iter(lambda:f.read(1024*1024), b''):
                if not b: break
                h.update(b)
        return h.hexdigest()[:16]
    except Exception: return "확인불가"
