def _v2129_fnum(v, default=0.0):
    try:
        if v in [None, ""]:
            return default
        return float(v)
    except Exception:
        return default
def _v2129_len(x) -> int:
    try:
        if isinstance(x, dict):
            return len(x)
        if isinstance(x, (list, tuple, set)): 
            return len(x)
    except Exception:
        pass
    return 0
def _v2129_age_text(ts) -> str:
    try:
        ts = _v2129_fnum(ts, 0)
        if ts <= 0:
            return "기록 없음"
        sec = int(max(0, time.time() - ts))
        if sec < 60:
            return f"{sec}초 전"
        if sec < 3600:
            return f"{sec//60}분 {sec%60}초 전"
        return f"{sec//3600}시간 {(sec%3600)//60}분 전"
    except Exception:
        return "확인불가"
def _v2129_status_text(v):
    return "켜짐" if bool(v) else "꺼짐"
def _v2129_safe_call(fn_name, *a, default=None, **kw):
    try:
        fn = globals().get(fn_name)
        if callable(fn):
            return fn(*a, **kw)
    except Exception:
        pass
    return default
def _v2129_line_count(path=None):
    try:
        p = path or os.path.abspath(__file__)
        with open(p, "rb") as f:
            return sum(1 for _ in f)
    except Exception:
        return 0
def _v2129_format_stats(label: str, stat: dict) -> str:
    try:
        n = int(stat.get("n", 0) or 0)
        if n <= 0:
            return f"- {label}: 종료 표본 없음"
        wins = int(stat.get("wins", 0) or 0)
        losses = int(stat.get("losses", 0) or 0)
        total = float(stat.get("total", 0) or 0)
        pf = float(stat.get("pf", 0) or 0)
        avg_win = float(stat.get("avg_win", 0) or 0)
        avg_loss = float(stat.get("avg_loss", 0) or 0)
        wr = wins / max(1, n) * 100.0
        return f"- {label}: {n}전 {wins}승 {losses}패 / 승률 {wr:.1f}% / 누적 {total:+.2f}% / PF {pf:.2f} / 평균익 +{avg_win:.2f}% / 평균손 -{avg_loss:.2f}%"
    except Exception:
        return f"- {label}: 집계 오류"
