def _v2129_batch_timing_text(timings, batch_start, source_label):
    try:
        elapsed = time.time() - batch_start
        lines = [
            "⏱ 명령어별 시간표",
            f"- 출처: {source_label}",
            f"- 전체 경과: {elapsed:.2f}s",
        ]
        slow = []
        for t in timings or []:
            cmd = str(t.get('cmd', ''))
            after = float(t.get('after_start', 0) or 0)
            el = float(t.get('elapsed', 0) or 0)
            status = str(t.get('status', 'OK'))
            lines.append(f"- /{cmd}: 배치후 {after:.1f}s / 처리 {el:.2f}s / 결과 {status}")
            if el >= 2.0:
                slow.append(f"/{cmd} {el:.1f}s")
        lines += ["", "🐢 느린 이유 후보"]
        if slow:
            lines.append("- 실제 처리시간 긴 명령: " + ", ".join(slow[:5]))
        else:
            lines.append("- 2초 이상 걸린 명령 없음")
        lines.append(f"- 최근 캐시 느린 작업: {_v2129_stage_summary()}")
        lines.append("- 무거운 진단은 full 명령으로 분리해서 확인")
        return "\n".join(lines)
    except Exception:
        return "⏱ 명령어별 시간표\n- 생성 오류"
