def _v2111_quality_data(force=False):
    try:
        rows = _v2111_real_closed_rows()
        sig = f"{len(rows)}:{max([_v2111_row_ts(r) for r in rows] or [0]):.0f}"
        now = time.time()
        cached = V2111_QUALITY_CACHE.get('data')
        if (not force) and cached is not None and V2111_QUALITY_CACHE.get('rows_sig') == sig and now - float(V2111_QUALITY_CACHE.get('ts') or 0) <= V2111_QUALITY_TTL_SEC:
            return dict(cached)
        v340_all = [r for r in rows if _v2111_route_bucket(r) == 'v340']
        v343_all = [r for r in rows if _v2111_route_bucket(r) == 'v343']
        v340_2 = _v2111_recent_rows(v340_all, 2)
        v340_6 = _v2111_recent_rows(v340_all, 6)
        v340_12 = _v2111_recent_rows(v340_all, 12)
        v343_6 = _v2111_recent_rows(v343_all, 6)
        reason_map = {}
        ticker_map = {}
        source_map = {}
        for r in v340_12:
            reason_map.setdefault(_v2111_exit_reason(r), []).append(r)
            tk = str(r.get('ticker') or r.get('symbol') or '?').upper()
            ticker_map.setdefault(tk, []).append(r)
            source_map.setdefault(_v2111_source_hint(r), []).append(r)
        data = {
            'rows_total': len(rows),
            'v340_2': v340_2, 'v340_6': v340_6, 'v340_12': v340_12,
            'v343_6': v343_6,
            'reason_map': reason_map, 'ticker_map': ticker_map, 'source_map': source_map,
        }
        V2111_QUALITY_CACHE.update({'ts': now, 'rows_sig': sig, 'data': dict(data)})
        return data
    except Exception as e:
        try: append_runtime_error_log('v2111_quality_data', str(e), exc=e, include_traceback=False)
        except Exception: pass
        return {'rows_total': 0, 'v340_2': [], 'v340_6': [], 'v340_12': [], 'v343_6': [], 'reason_map': {}, 'ticker_map': {}, 'source_map': {}}
def _v2111_top_group_lines(title, group_map, limit=5):
    lines = [title]
    items = []
    for k, rows in (group_map or {}).items():
        st = _v2111_stats(rows)
        items.append((st['total'], st['n'], str(k), rows, st))
    items.sort(key=lambda x: (x[0], -x[1]))
    shown = 0
    for total, n, key, rows, st in items:
        if n <= 0:
            continue
        if shown >= limit:
            break
        winrate = st['wins'] / st['n'] * 100.0 if st['n'] else 0.0
        lines.append(f"- {key}: {st['n']}전 {st['wins']}승 {st['losses']}패 / {st['total']:+.2f}% / PF {st['pf']:.2f} / 승률 {winrate:.0f}%")
        shown += 1
    if shown <= 0:
        lines.append("- 표본 없음")
    return lines
