def _v2133_label_parts(row):
    route_raw = str(_v2133_row_get(row, ["route", "route_key", "source_route", "strategy_route", "paper_route"], "") or "")
    decision_raw = str(_v2133_row_get(row, ["decision", "decision_label", "rank_watch_action", "action", "final_action"], "") or "")
    grade_raw = str(_v2133_row_get(row, ["grade", "tier", "rank_grade"], "") or "")
    txt = str(row).lower()
    route = route_raw
    if not route:
        if "v340" in txt or "reconfirm" in txt:
            route = "v340 추정"
        elif "v343" in txt:
            route = "v343 추정"
        elif _v2133_row_get(row, ["source", "ctx", "origin"], ""):
            route = "rank_scan"
    decision = decision_raw
    if not decision:
        if callable(globals().get('build_final_candidate_display_context_v251')):
            try:
                ctx = build_final_candidate_display_context_v251(row) or {}
                decision = str(ctx.get('action') or ctx.get('state') or ctx.get('main') or '')
            except Exception:
                decision = ""
    grade = grade_raw
    if not grade:
        score = _v2133_float(_v2133_row_get(row, ["snapshot_rank_score", "lite_score", "score", "edge"], 0), 0)
        if score >= 8.5:
            grade = "A추정"
        elif score >= 5.0:
            grade = "B추정"
        elif score > 0:
            grade = "C추정"
    return {"route_raw": route_raw, "decision_raw": decision_raw, "grade_raw": grade_raw, "route": route, "decision": decision, "grade": grade}
def _v2133_scan_label_missing(rows):
    raw = {"route": 0, "decision": 0, "grade": 0, "price": 0, "source": 0}
    inferred = {"route": 0, "decision": 0, "grade": 0}
    total = 0
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        total += 1
        lab = _v2133_label_parts(r)
        if not lab['route_raw']:
            raw['route'] += 1
        if not lab['decision_raw']:
            raw['decision'] += 1
        if not lab['grade_raw']:
            raw['grade'] += 1
        if not lab['route']:
            inferred['route'] += 1
        if not lab['decision']:
            inferred['decision'] += 1
        if not lab['grade']:
            inferred['grade'] += 1
        if _v2133_float(_v2133_row_get(r, ["price", "current_price"], 0), 0) <= 0:
            raw['price'] += 1
        if not _v2133_row_get(r, ["source", "ctx", "origin"], ""):
            raw['source'] += 1
    return {"total": total, "raw": raw, "inferred": inferred}
def _v2133_tf_context(row):
    ch1 = _v2133_pct(row, 1); ch3 = _v2133_pct(row, 3); ch5 = _v2133_pct(row, 5); ch15 = _v2133_pct(row, 15); ch30 = _v2133_pct(row, 30)
    from_low = _v2133_float(_v2133_row_get(row, ["from_low", "from_30m_low_pct", "low_from_ref_pct_v2"], 0.0), 0.0)
    below_high = _v2133_float(_v2133_row_get(row, ["below_high", "below_30m_high_pct", "high_gap_pct"], 999.0), 999.0)
    pressure = _v2133_float(_v2133_row_get(row, ["current_candle_pressure_score", "pressure_score"], 0.0), 0.0)
    live = _v2133_float(_v2133_row_get(row, ["current_candle_live_score", "live_score"], 0.0), 0.0)
    label_text = str(_v2133_row_get(row, ["current_candle_label", "primary_reason", "decision_label", "status"], "") or "")
    has15 = _v2133_has_any(row, _v2133_pct_keys(15)); has30 = _v2133_has_any(row, _v2133_pct_keys(30))
    vals_1_15 = [round(ch1, 4), round(ch3, 4), round(ch5, 4), round(ch15, 4)]
    same_short = len(set(vals_1_15)) <= 1
    trust = "높음" if has15 and has30 and not same_short else ("보통" if has15 or has30 else "낮음")
    trust_reason = "시간대 캐시" if trust == "높음" else ("부분 캐시/스냅샷 혼합" if trust == "보통" else "스냅샷 추정")
    caution = []
    if same_short:
        caution.append("1/3/5/15 값 유사")
    if not has30 or abs(ch30) < 0.0001:
        caution.append("30분 미확인")
    near_high = 0 <= below_high <= 0.20
    if near_high:
        caution.append("고점 바로 근처")
    weak = min(ch1, ch3, ch5) <= -0.25 or pressure >= 1.25 or any(x in label_text for x in ["밀림", "위꼬리", "약함"])
    if near_high:
        pattern = "고점근처 재돌파 확인"; group = "고점"
    elif weak:
        pattern = "단기 힘 약함"; group = "약함"
    elif ch1 >= 0.35 and ch3 >= 0.25 and ch5 >= 0.20 and from_low <= 2.20 and below_high >= 0.20:
        pattern = "초입 강세 후보"; group = "초입"
    elif ch1 >= 0.15 and ch5 >= 0.10 and 0.20 <= from_low <= 2.80 and below_high >= 0.20:
        pattern = "눌림 후 재출발 후보"; group = "재출발"
    elif from_low >= 3.20 and below_high <= 0.80:
        pattern = "추격주의"; group = "추격"
    else:
        pattern = "대기/횡보 확인"; group = "대기"
    if group in {"초입", "재출발"} and trust in {"높음", "보통"} and not near_high:
        auto = "자동매매 살릴후보"; auto_group = "살릴"
    elif group in {"초입", "재출발", "고점"}:
        auto = "자동매매 보류후보"; auto_group = "보류"
    elif group in {"약함", "추격"}:
        auto = "자동매매 제외후보"; auto_group = "제외"
    else:
        auto = "자동매매 관찰"; auto_group = "관찰"
    if trust == "낮음" and auto_group == "살릴":
        auto = "자동매매 보류후보"; auto_group = "보류"
    return {
        "ticker": _v2133_ticker(row), "ch1": ch1, "ch3": ch3, "ch5": ch5, "ch15": ch15, "ch30": ch30,
        "from_low": from_low, "below_high": below_high, "pattern": pattern, "group": group,
        "trust": trust, "trust_reason": trust_reason, "caution": caution, "auto": auto, "auto_group": auto_group,
    }
def _v2133_tf_line(row, idx=None):
    c = _v2133_tf_context(row)
    head = f"{idx}. " if idx else "- "
