def _v2133_scan_tf_summary(force=False):
    try:
        now = time.time()
        cached = V2133_TF_CACHE.get('summary')
        if (not force) and cached and now - _v2133_float(V2133_TF_CACHE.get('ts', 0), 0) <= V2133_TF_TTL_SEC:
            return dict(cached)
        rows = _v2133_rank_rows(12)
        counts = {"살릴": 0, "보류": 0, "제외": 0, "관찰": 0, "낮은신뢰": 0, "초입": 0, "재출발": 0, "고점": 0, "추격": 0, "밀림": 0, "약함": 0, "대기": 0}
        contexts = []
        for r in rows:
            ctx = _v2133_tf_context(r); contexts.append(ctx)
            counts[ctx['auto_group']] = counts.get(ctx['auto_group'], 0) + 1
            if ctx['trust'] == "낮음": counts['낮은신뢰'] += 1
            counts[ctx['group']] = counts.get(ctx['group'], 0) + 1
        out = {"rows": rows, "contexts": contexts, "counts": counts, "ts": now}
        V2133_TF_CACHE.update({"ts": now, "summary": dict(out)})
        return out
    except Exception as e:
        try: append_runtime_error_log('v2133_scan_tf_summary', str(e), exc=e, include_traceback=False)
        except Exception: pass
        return {"rows": [], "contexts": [], "counts": {}, "ts": time.time()}
def _v2133_scan_verdict(m=None, miss=None):
    try:
        m = m or (_v2129_market_state() if callable(globals().get('_v2129_market_state')) else {})
        rows = m.get('rank_rows') or _v2133_rank_rows(40)
        miss = miss or _v2133_scan_label_missing(rows)
        cache = _v2133_int(m.get('cache', 0), 0); rank = _v2133_int(m.get('rank', len(rows)), len(rows)); hb = _v2133_float(m.get('hb_age', -1), -1)
        raw = miss.get('raw', {}); inferred = miss.get('inferred', {})
        if cache < 20 or rank < 10:
            return "문제 있음", "시장캐시/rank row 부족"
        if hb >= 180:
            return "문제 있음", "메인루프 최신성 부족"
        if raw.get('price', 0) or raw.get('source', 0):
            return "주의", "가격/source 누락 있음"
        if inferred.get('route', 0) or inferred.get('decision', 0) or inferred.get('grade', 0):
            return "주의", "추정 라벨까지 비는 후보 있음"
        if raw.get('route', 0) or raw.get('decision', 0) or raw.get('grade', 0):
            return "주의", "raw 라벨은 비지만 추정 라벨로 보완 중"
        return "정상", "시장수집·rank row·라벨 최신성 정상"
    except Exception:
        return "확인필요", "스캔 판정 생성 오류"
def _v2133_short_stat(stat: dict) -> str:
    try:
        n = int((stat or {}).get('n', 0) or 0)
        if n <= 0:
            return "종료 표본 없음"
        wins = int((stat or {}).get('wins', 0) or 0); losses = int((stat or {}).get('losses', 0) or 0)
        total = float((stat or {}).get('total', 0) or 0); pf = float((stat or {}).get('pf', 0) or 0)
        wr = wins / max(1, n) * 100.0
        return f"{n}전 {wins}승 {losses}패 / 승률 {wr:.1f}% / 수익률 {total:+.2f}% / PF {pf:.2f}"
    except Exception:
        return "집계 오류"
def _v2133_reason_lines(title, group_map, limit=6):
    lines = [title]
    items = []
    try:
        iterator = group_map.items() if isinstance(group_map, dict) else []
        for key, rows in iterator:
            st = _v2111_stats(rows) if callable(globals().get('_v2111_stats')) else {"n": 0, "wins": 0, "losses": 0, "total": 0, "pf": 0}
            items.append((float(st.get('total', 0)), -int(st.get('n', 0)), str(key), st))
        items.sort(key=lambda x: (x[0], x[1]))
        shown = 0
        for _total, _neg_n, key, st in items:
            if int(st.get('n', 0)) <= 0 or shown >= limit:
                continue
            n = int(st.get('n', 0)); wins = int(st.get('wins', 0)); losses = int(st.get('losses', 0)); total = float(st.get('total', 0))
            lines.append(f"- {key}: {n}전 {wins}승 {losses}패 / {total:+.2f}%")
            shown += 1
        if shown <= 0:
            lines.append("- 표본 없음")
    except Exception:
        lines.append("- 집계 오류")
    return lines
