    good_keys = [k for k in reason_map if 'time_exit' in str(k) or 'TP3' in str(k) or 'tp3' in str(k)]
    bad_keys = [k for k in reason_map if any(x in str(k) for x in ['slow_no_progress', 'crash_cut', 'stop_loss'])]
    lines = ["📌 v340 내부 유형"]
    if not reason_map:
        return lines + ["- 표본 없음"]
    for k in good_keys:
        st = _v2111_stats(reason_map.get(k) or [])
        lines.append(f"✅ 수익형: {k}: {_v2133_short_stat(st)}")
    for k in bad_keys:
        st = _v2111_stats(reason_map.get(k) or [])
        lines.append(f"⚠️ 손실형: {k}: {_v2133_short_stat(st)}")
    other = [k for k in reason_map if k not in set(good_keys + bad_keys)]
    for k in other[:4]:
        st = _v2111_stats(reason_map.get(k) or [])
        lines.append(f"▫️ 기타: {k}: {_v2133_short_stat(st)}")
    return lines
