def _v2136_short_stat(st):
    try:
        n = int((st or {}).get('n', 0) or 0)
        if n <= 0: return '표본 없음'
        wins = int((st or {}).get('wins', 0) or 0); losses = int((st or {}).get('losses', max(0, n-wins)) or 0)
        total = float((st or {}).get('total', 0) or 0); pf = float((st or {}).get('pf', 0) or 0)
        return f"{n}전 {wins}승 {losses}패 / 승률 {wins/max(1,n)*100:.1f}% / 수익률 {total:+.2f}% / PF {pf:.2f}"
    except Exception:
        return '집계 오류'
def _v2136_row_ts(row):
    if not isinstance(row, dict): return 0.0
    for k in ['exit_ts','closed_ts','close_ts','sell_ts','ts','timestamp','created_ts','updated_ts','time','exit_time','closed_at','sell_time']:
        v = row.get(k)
        if v in (None, ''): continue
        try:
            f = float(v)
            if f > 1e12: f /= 1000.0
            if f > 1_000_000_000: return f
        except Exception:
            pass
        try:
            s = str(v).replace('KST','').strip().replace('T',' ')
            for fmt in ['%Y-%m-%d %H:%M:%S','%Y-%m-%d %H:%M','%m-%d %H:%M:%S','%m-%d %H:%M']:
                try:
                    import datetime as _dt
                    dt = _dt.datetime.strptime(s[:len(fmt)], fmt)
                    if fmt.startswith('%m'):
                        dt = dt.replace(year=_dt.datetime.now().year)
                    return dt.timestamp()
                except Exception:
                    continue
        except Exception:
            pass
    return 0.0
