        items.sort(key=lambda kv: (0 if any(x in kv[0] for x in good_hint) else (1 if any(x in kv[0] for x in bad_hint) else 2), kv[0]))
        shown = 0
        for reason, st in items:
            n = int((st or {}).get('n', 0) or 0)
