def _v2137_is_unknown_gap(v):
    try:
        return _v2136_float(v, 999) >= 900
    except Exception:
        return True
def _v2137_gap_text(v):
    try:
        f = _v2136_float(v, 999)
        if f >= 900:
            return '미확인'
        if f < -0.0001:
            return '고점 돌파/계산확인'
        return f'{f:.2f}%'
    except Exception:
        return '미확인'
def _v2137_is_true_missed(row: dict) -> bool:
    try:
        if not isinstance(row, dict) or is_watch_excluded_ticker(str(row.get('ticker','') or '')):
            return False
        bucket = str(row.get('missed_tracking_bucket') or get_missed_review_bucket(row) or '')
        best = _v2136_float(row.get('best_up_pct', 0), 0)
        end = _v2136_float(row.get('end_up_pct', 0), 0)
        worst = _v2136_float(row.get('worst_down_pct', 0), 0)
        trust = get_minute1_sample_trust(int(_v2136_float(row.get('window_candles', 0), 0))) if callable(globals().get('get_minute1_sample_trust')) else str(row.get('sample_trust',''))
        high_gap = min(_v2136_float(row.get('high_gap_pct', 999),999), _v2136_float(row.get('below_30m_high_pct',999),999), _v2136_float(row.get('chart_gap_pct',999),999))
        late = (not _v2137_is_unknown_gap(high_gap)) and high_gap <= 0.20
        if late or trust in {'very_low','low'}:
            return False
        if bucket == '진짜놓침' and best >= V2137_TRUE_MISSED_MIN_UP and end >= 0.20 and worst > -2.40:
            return True
        if best >= V2137_TRUE_MISSED_MIN_UP and end >= V2137_TRUE_MISSED_MIN_END and worst > -1.80:
            return True
        return False
    except Exception:
        return False
def _v2137_is_big_ambiguous_missed(row: dict) -> bool:
    try:
        if _v2137_is_true_missed(row):
            return False
        best = _v2136_float(row.get('best_up_pct', 0), 0)
        end = _v2136_float(row.get('end_up_pct', 0), 0)
        worst = _v2136_float(row.get('worst_down_pct', 0), 0)
        high_gap = min(_v2136_float(row.get('high_gap_pct', 999),999), _v2136_float(row.get('below_30m_high_pct',999),999), _v2136_float(row.get('chart_gap_pct',999),999))
        if (not _v2137_is_unknown_gap(high_gap)) and high_gap <= 0.20:
            return False
        return best >= V2137_BIG_AMBIG_MIN_UP and end >= 0.10 and worst > -2.80
    except Exception:
        return False
