def _v21315_safe_now():
    try:
        return time.time()
    except Exception:
        import time as _t
        return _t.time()
def _v21315_btc_row_raw(interval):
    try:
        return (globals().get('BTC_V291_CACHE') or {}).get(str(interval), {}) or {}
    except Exception:
        return {}
def _v21315_btc_interval_due(interval: str, min_gap: int) -> bool:
    try:
        row = _v21315_btc_row_raw(interval)
        now = _v21315_safe_now()
        ok_ts = float(row.get('ok_ts', 0) or 0)
        cool_until = float(row.get('cool_until', 0) or 0)
        if cool_until > now:
            V21315_BTC_WORKER_STATE['cooldown'] = int(float(V21315_BTC_WORKER_STATE.get('cooldown', 0) or 0)) + 1
            return False
        if ok_ts <= 0:
            return True
        return (now - ok_ts) >= float(min_gap)
    except Exception:
        return True
def _v21315_btc_fetch_once(interval: str, min_len: int = 20):
    global BTC_V293_READONLY_MODE
    prev = bool(globals().get('BTC_V293_READONLY_MODE', False))
    try:
        BTC_V293_READONLY_MODE = False
    except Exception:
        pass
    try:
        if callable(globals().get('_v291_get_btc_df_cached')):
            df, st, age = _v291_get_btc_df_cached(str(interval), int(min_len))
        elif callable(globals().get('get_ohlcv')):
            df = get_ohlcv('BTC', str(interval)); st = 'direct_fetch'; age = 0.0
        else:
            return None, 'no_fetch_function', 999999.0
        ok = False
        try:
            ok = bool(callable(globals().get('_v291_ok_df')) and _v291_ok_df(df, int(min_len)))
        except Exception:
            ok = df is not None
        if ok:
            V21315_BTC_WORKER_STATE['fetch_ok'] = int(float(V21315_BTC_WORKER_STATE.get('fetch_ok', 0) or 0)) + 1
        elif str(st).startswith('cooldown'):
            V21315_BTC_WORKER_STATE['cooldown'] = int(float(V21315_BTC_WORKER_STATE.get('cooldown', 0) or 0)) + 1
        else:
            V21315_BTC_WORKER_STATE['fetch_fail'] = int(float(V21315_BTC_WORKER_STATE.get('fetch_fail', 0) or 0)) + 1
        V21315_BTC_WORKER_STATE.update({'last_ts': _v21315_safe_now(), 'last_interval': str(interval), 'last_status': str(st), 'last_error': ''})
        return df, st, age
    except Exception as e:
        V21315_BTC_WORKER_STATE['fetch_fail'] = int(float(V21315_BTC_WORKER_STATE.get('fetch_fail', 0) or 0)) + 1
        V21315_BTC_WORKER_STATE.update({'last_ts': _v21315_safe_now(), 'last_interval': str(interval), 'last_status': 'worker_error', 'last_error': str(e)[:120]})
        try:
            append_runtime_error_log('v21315_btc_worker', str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return None, 'worker_error', 999999.0
    finally:
        try:
            BTC_V293_READONLY_MODE = prev
        except Exception:
            pass
def _v21315_btc_cache_worker_loop():
    try:
        V21315_BTC_WORKER_STATE['started'] = True
        for interval, min_len, _gap in V21315_BTC_INTERVALS:
            _v21315_btc_fetch_once(interval, min_len)
            time.sleep(2)
        while True:
            V21315_BTC_WORKER_STATE['cycle'] = int(float(V21315_BTC_WORKER_STATE.get('cycle', 0) or 0)) + 1
            did = False
            for interval, min_len, gap in V21315_BTC_INTERVALS:
                if _v21315_btc_interval_due(interval, gap):
                    _v21315_btc_fetch_once(interval, min_len)
                    did = True
                    break
            time.sleep(25 if did else 45)
    except Exception as e:
        V21315_BTC_WORKER_STATE['started'] = False
        V21315_BTC_WORKER_STATE['last_error'] = str(e)[:120]
        try:
            append_runtime_error_log('v21315_btc_worker_loop', str(e), exc=e, include_traceback=False)
        except Exception:
            pass
def _v21315_start_btc_worker_once():
    try:
        if bool(V21315_BTC_WORKER_STATE.get('started')):
            return False
        import threading as _threading
        _threading.Thread(target=_v21315_btc_cache_worker_loop, daemon=True, name='btc_cache_worker_v21315').start()
        return True
    except Exception as e:
        V21315_BTC_WORKER_STATE['last_error'] = str(e)[:120]
        try:
            append_runtime_error_log('v21315_start_btc_worker', str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        return False
def _v21315_btc_status():
    out = {'ok': 0, 'missing': 0, 'rows': [], 'impact': '확인', 'impact_reason': 'BTC 상태 확인 중'}
    try:
        specs = [('단기', 'minute10', 6), ('중기', 'minute60', 6), ('일봉', 'day', 3)]
        for label, interval, bars in specs:
            st = _v21314_btc_row(interval) if callable(globals().get('_v21314_btc_row')) else {'has_df': False, 'status': '대기', 'age': -1, 'rem': 0}
            has = bool(st.get('has_df'))
            age = float(st.get('age', -1) or -1)
            rem = float(st.get('rem', 0) or 0)
            chg = None
            try:
                chg = _v21314_btc_change(interval, bars) if has and callable(globals().get('_v21314_btc_change')) else None
            except Exception:
                chg = None
            if has:
                out['ok'] += 1
                val = f"{float(chg):+.2f}%" if chg is not None else "값 계산중"
                suffix = f" / 정상 {_v21314_elapsed(age)} 전" if callable(globals().get('_v21314_elapsed')) and age >= 0 else ""
                out['rows'].append(f"- {label}: {val}{suffix}")
            else:
                out['missing'] += 1
                s = str(st.get('status','대기') or '대기')
                if rem > 0 and callable(globals().get('_v21314_elapsed')):
                    out['rows'].append(f"- {label}: 데이터 부족 / {s} / 쿨다운 {_v21314_elapsed(rem)}")
                else:
                    out['rows'].append(f"- {label}: 데이터 부족 / {s}")
        if out['ok'] >= 2:
            out['impact'] = '정상'; out['impact_reason'] = 'BTC 장세 참고 가능'
        elif out['ok'] == 1:
            out['impact'] = '주의'; out['impact_reason'] = 'BTC 일부 시간대만 있음 / 후보 승격은 보수 확인'
        else:
            out['impact'] = '부족'; out['impact_reason'] = 'BTC 캐시 없음 / 후보를 완전 차단하진 않지만 장세 판단은 보수'
        ws = V21315_BTC_WORKER_STATE
        last_ts = float(ws.get('last_ts', 0) or 0)
        last_age = (_v21315_safe_now() - last_ts) if last_ts > 0 else -1
        if callable(globals().get('_v21314_elapsed')) and last_age >= 0:
            out['worker_line'] = f"- worker: {'작동' if ws.get('started') else '대기'} / 최근 {ws.get('last_interval','-')} {ws.get('last_status','-')} / {_v21314_elapsed(last_age)} 전"
        else:
            out['worker_line'] = f"- worker: {'작동' if ws.get('started') else '대기'} / 최근 기록 없음"
        out['worker_stats'] = f"- worker 누적: 성공 {int(float(ws.get('fetch_ok',0) or 0))} / 실패 {int(float(ws.get('fetch_fail',0) or 0))} / 쿨다운 {int(float(ws.get('cooldown',0) or 0))}"
        if ws.get('last_error'):
            out['worker_error'] = f"- worker 오류: {ws.get('last_error')}"
    except Exception as e:
        out['impact'] = '확인불가'; out['impact_reason'] = f'{e.__class__.__name__}: {str(e)[:80]}'
    return out
def _v21314_btc_status():
    return _v21315_btc_status()
def _v21314_btc_line(short=True):
    st = _v21315_btc_status()
    if short:
        return f"BTC: {st.get('impact')} / {st.get('impact_reason')}"
    lines = ["📊 BTC 장세", f"- 상태: {st.get('impact')} / {st.get('impact_reason')}"]
