def get_market_universe(force=False):
    global market_universe, market_universe_time, market_universe_cursor, last_universe_build_stats
    now_ts = time.time()
    if (not force) and market_universe and (now_ts - market_universe_time < UNIVERSE_REFRESH_SEC):
        return market_universe
    tickers = get_cached_market_tickers(force=force)
    if not tickers:
        last_universe_build_stats = {
            "tried": 0,
            "success": 0,
            "selected": len(market_universe),
            "kept": len(market_universe),
            "duration_sec": 0.0,
            "note": "티커 목록 없음",
        }
        return market_universe
    tickers_set = set(tickers)
    base_map = {row.get("ticker"): dict(row) for row in market_universe if isinstance(row, dict) and row.get("ticker") in tickers_set}
    try:
        if len(base_map) < UNIVERSE_COLD_START_TARGET:
            base_map = seed_universe_with_snapshot_rows(tickers, base_map, limit=max(UNIVERSE_COLD_START_TARGET, LIGHT_SNAPSHOT_UNIVERSE_SEED_TARGET))
    except Exception as e:
        append_runtime_event_log("snapshot_universe_seed_error", "스냅샷 유니버스 보강 실패", extra={"error": str(e)[:120]})
    cold_start = len(base_map) < UNIVERSE_COLD_START_TARGET
    if cold_start:
        batch_size = min(max(UNIVERSE_COLD_START_BATCH, UNIVERSE_FORCE_FULL_BATCH), len(tickers))
    else:
        batch_size = UNIVERSE_FORCE_FULL_BATCH if (force or not base_map) else UNIVERSE_REFRESH_BATCH
    batch, next_cursor = pick_refresh_batch(tickers, market_universe_cursor, batch_size)
    started = time.time()
    build_budget_sec = UNIVERSE_COLD_START_MAX_SEC if cold_start else UNIVERSE_BUILD_MAX_SEC
    refreshed_count = 0
    fail_count = 0
    tried_count = 0
    direct_minute3_used = 0
    for idx3, ticker in enumerate(batch, start=1):
        tried_count += 1
        if idx3 % 8 == 0:
            try:
                mark_main_loop_heartbeat(stage=f"build_universe_{idx3}")
            except Exception:
                pass
        try:
            if SNAPSHOT_FIRST_HARD_MODE_ON:
                metrics = compute_light_snapshot_metrics(ticker, current_price=safe_float(base_map.get(ticker, {}).get("last_price", 0), 0)) if LIGHT_SNAPSHOT_ENGINE_ON else {}
                if isinstance(metrics, dict) and metrics.get("snapshot_ready"):
                    price = safe_float(metrics.get("snapshot_price", 0), 0)
                    turn = safe_float(metrics.get("snapshot_turnover_hint", 0), 0)
                    ch5 = safe_float(metrics.get("change_5", 0), 0)
                    ch15 = safe_float(metrics.get("change_15", 0), 0)
                    ch30 = safe_float(metrics.get("change_30", 0), 0)
                    ch60 = safe_float(metrics.get("change_60", 0), 0)
                    vol = safe_float(metrics.get("vol_ratio_snapshot", 0), 0)
                    surge_score = max(ch5, 0) * 2.7 + max(ch15, 0) * 0.9 + max(ch30, 0) * 0.7 + max(ch60, 0) * 0.35 + max(vol - 1.0, 0) * 1.1
                    base_map[ticker] = {
                        "ticker": ticker,
                        "snapshot_seed": True,
                        "last_price": price,
                        "turnover_recent": turn,
                        "turnover_score": math.log10(max(turn, 1)),
                        "surge_score": surge_score,
                        "short_change": ch5,
                        "change_15": ch15,
                        "change_30": ch30,
                        "change_60": ch60,
                        "vol_ratio": vol,
                        "range_pct": max(safe_float(metrics.get("from_low", 0), 0), 0),
                    }
                    refreshed_count += 1
                    continue
                if direct_minute3_used >= SNAPSHOT_FIRST_DIRECT_MINUTE3_MAX_PER_UNIVERSE_BUILD:
                    continue
                direct_minute3_used += 1
            df3 = get_ohlcv(ticker, "minute3")
            if df3 is None or len(df3) < 30:
                fail_count += 1
                continue
            price = safe_float(df3["close"].iloc[-1], 0)
            if price <= 0:
                fail_count += 1
                continue
            vol_ratio = get_vol_ratio(df3, 3, 15)
            short_change = get_recent_change_pct(df3, 3)
            change_15 = get_recent_change_pct(df3, 5)
            change_30 = get_recent_change_pct(df3, 10)
            change_60 = get_recent_change_pct(df3, 20)
            range_pct = get_range_pct(df3, 8)
            turnover_recent = float(df3["volume"].tail(5).sum()) * price
            turnover_score = math.log10(max(turnover_recent, 1))
            surge_score = (
                min(vol_ratio, 7.0) * 1.8
                + min(max(short_change, 0), 4.5) * 1.4
                + min(max(change_15, 0), 6.5) * 0.85
                + min(max(change_30, 0), 9.0) * 0.62
                + min(max(change_60, 0), 14.0) * 0.36
                + min(range_pct, 5.0) * 0.7
            )
            base_map[ticker] = {
                "ticker": ticker,
                "df_3m": df3,
                "last_price": price,
                "turnover_recent": turnover_recent,
                "turnover_score": turnover_score,
                "surge_score": surge_score,
                "short_change": short_change,
                "change_15": change_15,
                "change_30": change_30,
                "change_60": change_60,
                "vol_ratio": vol_ratio,
                "range_pct": range_pct,
            }
            refreshed_count += 1
        except Exception as e:
            fail_count += 1
            if fail_count <= 3:
                print(f"[유니버스 갱신 오류] {ticker}: {e}", flush=True)
        elapsed = time.time() - started
        if elapsed >= build_budget_sec:
            min_success = max(1 if cold_start else 2, min(UNIVERSE_MIN_PARTIAL_ROWS, batch_size))
            min_tried = max(2 if cold_start else 3, min(batch_size, UNIVERSE_MIN_PARTIAL_ROWS + 1))
            if refreshed_count >= min_success or tried_count >= min_tried:
                append_runtime_event_log("universe_partial_break", f"{elapsed:.1f}초 제한으로 부분 종료", extra={"tried": tried_count, "success": refreshed_count, "batch_size": batch_size, "force": force})
                break
    if not base_map:
        last_universe_build_stats = {
            "tried": tried_count,
            "success": refreshed_count,
            "selected": len(market_universe),
            "kept": len(market_universe),
            "duration_sec": round(time.time() - started, 2),
            "note": "유니버스 후보 비었음",
        }
        return market_universe
    ranked = rank_universe_rows(base_map.values())
    if ranked:
        market_universe = ranked
        market_universe_time = time.time()
        market_universe_cursor = next_cursor
    last_universe_build_stats = {
        "tried": tried_count,
        "success": refreshed_count,
        "selected": len(market_universe),
        "kept": max(len(base_map) - refreshed_count, 0),
        "duration_sec": round(time.time() - started, 2),
        "note": "부분 갱신" if refreshed_count and refreshed_count < tried_count else ("유지" if refreshed_count == 0 else "정상"),
    }
    return market_universe
def build_shared_market_cache(force=False, refresh_universe: bool = False):
    global shared_market_cache, shared_market_cache_time, last_shared_cache_success_ts
    global shared_cache_cursor, shared_cache_row_times, last_cache_build_stats
    now_ts = time.time()
    cache_age = (now_ts - shared_market_cache_time) if shared_market_cache_time else None
    if (not force) and cache_age is not None and cache_age >= SCAN_CACHE_HARD_RESET_SEC:
        force = True
    if (not force) and shared_market_cache and (now_ts - shared_market_cache_time < MARKET_CACHE_TTL_SEC):
        return shared_market_cache
    universe_age = (now_ts - market_universe_time) if market_universe_time else None
    if market_universe and (not refresh_universe) and (universe_age is not None) and universe_age < max(UNIVERSE_REFRESH_SEC * 4, 60):
        universe = market_universe
    else:
        universe = get_market_universe(force=bool(force and refresh_universe))
    if not universe:
        if cache_age is not None and cache_age >= SCAN_CACHE_HARD_RESET_SEC:
            soft_recover_market_refresh_state(f"시장 유니버스 갱신 실패가 {int(cache_age)}초 넘게 이어짐")
        last_cache_build_stats = {
            "tried": 0,
            "success": 0,
            "kept": len(shared_market_cache) if isinstance(shared_market_cache, dict) else 0,
            "duration_sec": 0.0,
            "note": "유니버스 없음",
        }
        return shared_market_cache
    universe_tickers = {row.get("ticker") for row in universe if isinstance(row, dict) and row.get("ticker")}
    if isinstance(shared_market_cache, dict):
        if len(universe_tickers) < CACHE_COLD_START_TARGET:
            base_cache = {ticker: dict(row) for ticker, row in shared_market_cache.items()}
        else:
            base_cache = {ticker: dict(row) for ticker, row in shared_market_cache.items() if ticker in universe_tickers}
    else:
        base_cache = {}
    row_times = {ticker: safe_float(shared_cache_row_times.get(ticker, shared_market_cache_time), shared_market_cache_time) for ticker in base_cache.keys()}
    cold_cache = len(base_cache) < CACHE_COLD_START_TARGET
    if cold_cache:
        batch_size = min(max(CACHE_COLD_START_BATCH, CACHE_FORCE_FULL_BATCH), len(universe))
    else:
        batch_size = CACHE_FORCE_FULL_BATCH if (force or not base_cache) else CACHE_REFRESH_BATCH
    max_tries = max(CACHE_REFRESH_MAX_TRIES, batch_size + (4 if cold_cache else 0)) if (force or not base_cache or cold_cache) else CACHE_REFRESH_MAX_TRIES
    cache_build_budget_sec = CACHE_COLD_START_MAX_SEC if cold_cache else CACHE_BUILD_MAX_SEC
    batch_rows, next_cursor = pick_cache_refresh_rows(
        universe,
        row_times,
        shared_cache_cursor,
        batch_size,
        max_tries=max_tries,
        stale_sec=CACHE_ROW_REFRESH_TARGET_SEC,
    )
    started = time.time()
    refreshed_count = 0
    fail_count = 0
    tried_count = 0
    direct_minute1_used = 0
    snapshot_filled_count = 0
    for idx4, row in enumerate(batch_rows, start=1):
        tried_count += 1
        try:
            mark_main_loop_heartbeat(stage=f"build_cache_{idx4}")
        except Exception:
            pass
        ticker = row.get("ticker", "")
        if not ticker:
            continue
        try:
            snap_cache_item = build_snapshot_cache_item_from_row(ticker, row) if LIGHT_SNAPSHOT_ENGINE_ON else None
            if snap_cache_item:
                base_cache[ticker] = snap_cache_item
                row_times[ticker] = time.time()
                refreshed_count += 1
                snapshot_filled_count += 1
                try:
                    shared_market_cache = dict(base_cache)
                    shared_cache_row_times = dict(row_times)
                    shared_market_cache_time = time.time()
                    last_shared_cache_success_ts = shared_market_cache_time
                except Exception:
                    pass
                if SNAPSHOT_FIRST_HARD_MODE_ON:
                    continue
                if cold_cache or bool(row.get("snapshot_seed")):
                    continue
            if SNAPSHOT_FIRST_HARD_MODE_ON:
                price_hint = safe_float(row.get("last_price", row.get("price", 0)), 0)
                if price_hint > 0:
                    try:
                        record_light_price_snapshot(ticker, price_hint, turnover_hint=row.get("turnover_recent", 0), source="cache_price_hint")
                    except Exception:
                        pass
                if (not _is_priority_market_row(row)) or direct_minute1_used >= SNAPSHOT_FIRST_DIRECT_MINUTE1_MAX_PER_CACHE_BUILD:
                    continue
                direct_minute1_used += 1
            df1 = get_ohlcv(ticker, "minute1")
            if df1 is None or len(df1) < 35:
                fail_count += 1
                register_data_failure_missed_probe(ticker, row, reason="minute1 조회 실패 또는 봉 부족")
                if _is_priority_market_row(row):
                    shorten_ohlcv_cooldown_for_priority(ticker, "minute1", max_cooldown_sec=7)
                df3_lite = row.get("df_3m")
                lite_price = safe_float(row.get("last_price", row.get("price", 0)), 0)
                if lite_price <= 0 and df3_lite is not None:
                    try:
                        lite_price = safe_float(df3_lite["close"].iloc[-1], 0)
                    except Exception:
                        lite_price = 0
                if df3_lite is not None and len(df3_lite) >= 12 and lite_price > 0:
                    base_cache[ticker] = {
                        "price": lite_price,
                        "current_price": lite_price,
                        "df_3m": df3_lite,
                        "df_1m": None,
                        "turnover": row.get("turnover_recent", 0),
                        "surge_score": row.get("surge_score", 0),
                        "leader_score": row.get("leader_score", 0),
                        "turnover_rank": row.get("turnover_rank", 999),
                        "surge_rank": row.get("surge_rank", 999),
                        "vol_ratio": safe_float(row.get("vol_ratio", 0), 0),
                        "change_3": safe_float(row.get("short_change", 0), 0),
                        "change_5": safe_float(row.get("short_change", 0), 0),
                        "change_15": safe_float(row.get("change_15", 0), 0),
                        "change_30": safe_float(row.get("change_30", 0), 0),
                        "change_60": safe_float(row.get("change_60", 0), 0),
                        "rsi": 0,
                        "cache_updated_at": time.time(),
                        "cache_source": "df3_lite_after_minute1_fail",
                    }
                    try:
                        record_light_price_snapshot(ticker, lite_price, turnover_hint=row.get("turnover_recent", 0), source="df3_lite_after_minute1_fail")
                        base_cache[ticker] = apply_light_snapshot_metrics_to_item(base_cache[ticker])
                    except Exception:
                        pass
                    row_times[ticker] = time.time()
                    try:
                        shared_market_cache = dict(base_cache)
                        shared_cache_row_times = dict(row_times)
                        shared_market_cache_time = time.time()
                        last_shared_cache_success_ts = shared_market_cache_time
                    except Exception:
                        pass
                continue
            price = safe_float(df1["close"].iloc[-1], 0)
            if price <= 0:
                price = safe_float(row.get("last_price", 0), 0)
            if price <= 0:
                fail_count += 1
                continue
            change_1 = get_recent_change_pct(df1, 2)
            change_3 = get_recent_change_pct(df1, 3)
            change_5 = get_recent_change_pct(df1, 5)
            change_15 = get_recent_change_pct(df1, 15)
            change_30 = get_recent_change_pct(df1, 30)
            change_60 = get_recent_change_pct(df1, 60)
            vol_ratio_1m = get_vol_ratio(df1, 3, 15)
            range_pct_1m = get_range_pct(df1, 10)
            rsi_1m = get_rsi(df1, 14)
            base_cache[ticker] = {
                "price": price,
                "df_1m": df1,
                "df_3m": row.get("df_3m"),
                "turnover": row["turnover_recent"],
                "surge_score": row["surge_score"],
                "leader_score": row.get("leader_score", 0),
                "turnover_rank": row.get("turnover_rank", 999),
                "surge_rank": row.get("surge_rank", 999),
                "change_1": change_1,
                "change_3": change_3,
                "change_5": change_5,
                "change_15": change_15,
                "change_30": change_30,
                "change_60": change_60,
                "turnover_1m": float(df1["volume"].tail(1).sum()) * price,
                "turnover_3m": float(df1["volume"].tail(3).sum()) * price,
                "turnover_5m": float(df1["volume"].tail(5).sum()) * price,
                "turnover_15m": float(df1["volume"].tail(15).sum()) * price,
                "vol_ratio_1m": vol_ratio_1m,
                "range_pct_1m": range_pct_1m,
                "rsi_1m": rsi_1m,
                "vol_ratio": vol_ratio_1m,
                "range_pct": range_pct_1m,
                "rsi": rsi_1m,
                "cache_updated_at": time.time(),
            }
            try:
                record_light_price_snapshot(ticker, price, turnover_hint=base_cache[ticker].get("turnover_5m", base_cache[ticker].get("turnover", 0)), source="minute1_cache")
                base_cache[ticker] = apply_light_snapshot_metrics_to_item(base_cache[ticker])
            except Exception:
                pass
            row_times[ticker] = time.time()
            refreshed_count += 1
            try:
                shared_market_cache = dict(base_cache)
                shared_cache_row_times = dict(row_times)
                shared_market_cache_time = time.time()
                last_shared_cache_success_ts = shared_market_cache_time
            except Exception:
                pass
        except Exception as e:
            fail_count += 1
            if fail_count <= 3:
                print(f"[시장 캐시 갱신 오류] {ticker}: {e}", flush=True)
        elapsed = time.time() - started
        if refreshed_count >= CACHE_REFRESH_TARGET_SUCCESS and tried_count >= batch_size:
            break
        if elapsed >= cache_build_budget_sec:
            append_runtime_event_log("cache_partial_break", f"{elapsed:.1f}초 제한으로 부분 종료", extra={"tried": tried_count, "success": refreshed_count, "batch_size": batch_size, "max_tries": max_tries, "force": force, "cold_cache": cold_cache})
            break
    if base_cache:
        keep = {}
        keep_times = {}
        for ticker, row in base_cache.items():
            updated_at = safe_float(row_times.get(ticker, shared_market_cache_time), shared_market_cache_time)
            if refreshed_count > 0 and updated_at > 0 and (now_ts - updated_at) > CACHE_ROW_FRESH_KEEP_SEC:
                continue
            keep[ticker] = row
            keep_times[ticker] = updated_at
        if keep:
            base_cache = keep
            row_times = keep_times
    if refreshed_count > 0 and base_cache:
        shared_market_cache = base_cache
        shared_cache_row_times = row_times
        shared_market_cache_time = time.time()
        last_shared_cache_success_ts = shared_market_cache_time
        shared_cache_cursor = next_cursor
        update_recent_leader_board(shared_market_cache)
        update_market_pulse_state(shared_market_cache)
        try:
            update_scan_debug_snapshot(shared_market_cache, note=f"시장 캐시 부분 갱신 {refreshed_count}/{tried_count}")
        except Exception:
            pass
    elif not shared_market_cache and base_cache:
        shared_market_cache = base_cache
        shared_cache_row_times = row_times
    elif base_cache:
        shared_market_cache = base_cache
        shared_cache_row_times = row_times
        if tried_count >= max(2, min(batch_size, CACHE_MIN_PARTIAL_ROWS + 1)):
            shared_cache_cursor = next_cursor
            append_runtime_event_log("cache_batch_skip", "응답 없는 캐시 배치는 건너뛰고 다음 차수로 넘김", extra={"tried": tried_count, "success": refreshed_count, "batch_size": batch_size, "next_cursor": next_cursor, "force": force})
    elif cache_age is not None and cache_age >= SCAN_CACHE_HARD_RESET_SEC:
        soft_recover_market_refresh_state(f"1분봉 시장 캐시가 {int(cache_age)}초 넘게 새로 안 만들어짐")
    last_cache_build_stats = {
        "tried": tried_count,
        "success": refreshed_count,
        "kept": len(shared_market_cache) if isinstance(shared_market_cache, dict) else 0,
        "duration_sec": round(time.time() - started, 2),
        "note": "부분 갱신" if refreshed_count and refreshed_count < tried_count else ("유지" if refreshed_count == 0 else "정상"),
    }
    return shared_market_cache
