def _v21317_now():
    try:
        return time.time()
    except Exception:
        import time as _t
        return _t.time()
def _v21317_clean_ticker_list(rows):
    out, seen = [], set()
    for raw in list(rows or []):
        t = str(raw or '').upper().strip()
        if not t or t == 'BTC' or t in seen:
            continue
        seen.add(t); out.append(t)
    return out
def _v21317_default_ticker_set():
    return set(_v21317_clean_ticker_list(globals().get('DEFAULT_MARKET_TICKERS', []) or []))
def _v21317_is_fallback_tickers(rows):
    clean = _v21317_clean_ticker_list(rows)
    if not clean:
        return True
    default = _v21317_default_ticker_set()
    if len(clean) <= max(90, len(default) + 20):
        if not default or len(set(clean) - default) <= 8:
            return True
    return False
def _v21317_load_last_good_tickers():
    try:
        if not os.path.exists(V21317_TICKER_LAST_GOOD_FILE):
            return []
        with open(V21317_TICKER_LAST_GOOD_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
        rows = _v21317_clean_ticker_list(data.get('tickers') if isinstance(data, dict) else data)
        ts = safe_float(data.get('ts', 0), 0) if isinstance(data, dict) else 0
        if rows and not _v21317_is_fallback_tickers(rows):
            V21317_TICKER_STATE.update({'last_good_count': len(rows), 'last_good_ts': ts, 'last_source': 'last_good_file'})
            return rows
    except Exception as e:
        V21317_TICKER_STATE['last_error'] = f'load:{e.__class__.__name__}'
    return []
def _v21317_save_last_good_tickers(rows, source='fetch'):
    rows = _v21317_clean_ticker_list(rows)
    if not rows or _v21317_is_fallback_tickers(rows) or len(rows) < V21317_FULL_TICKER_MIN_COUNT:
        return False
    try:
        data = {'ts': _v21317_now(), 'source': source, 'count': len(rows), 'tickers': rows}
        with open(V21317_TICKER_LAST_GOOD_FILE, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False)
        V21317_TICKER_STATE.update({'last_good_count': len(rows), 'last_good_ts': data['ts'], 'last_source': source, 'last_error': ''})
        return True
    except Exception as e:
        V21317_TICKER_STATE['last_error'] = f'save:{e.__class__.__name__}'
        return False
def _v21317_ticker_fetch_allowed():
    try:
        import inspect
        allowed = {
            'get_market_universe', 'build_shared_market_cache', '_market_refresh_worker', 'market_refresh_worker',
            'market_refresh_loop', 'request_market_refresh', 'scan_watchlist', 'main', 'main_loop',
            'fast_scan_background_refresh_loop', '_v21317_ticker_refresh_worker_loop'
        }
        for fr in inspect.stack()[1:10]:
            if fr.function in allowed:
                return True
    except Exception:
        pass
    return False
def _v21317_direct_fetch_tickers():
    now = _v21317_now()
    if now - safe_float(V21317_TICKER_STATE.get('last_fetch_attempt_ts', 0), 0) < V21317_TICKER_FETCH_COOLDOWN_SEC:
        return []
    V21317_TICKER_STATE['last_fetch_attempt_ts'] = now
    try:
        rows = _call_with_timeout(pybithumb.get_tickers, timeout_sec=float(globals().get('TICKER_LIST_CALL_TIMEOUT_SEC', 1.2)), default=None)
        clean = _v21317_clean_ticker_list(rows)
        if clean and len(clean) >= V21317_FULL_TICKER_MIN_COUNT and not _v21317_is_fallback_tickers(clean):
            V21317_TICKER_STATE['fetch_ok'] = int(safe_float(V21317_TICKER_STATE.get('fetch_ok', 0), 0)) + 1
            V21317_TICKER_STATE['last_source'] = 'direct_full_fetch'
            _v21317_save_last_good_tickers(clean, source='direct_full_fetch')
            return clean
        V21317_TICKER_STATE['fetch_fail'] = int(safe_float(V21317_TICKER_STATE.get('fetch_fail', 0), 0)) + 1
        V21317_TICKER_STATE['last_error'] = f'fetch_short:{len(clean)}'
    except Exception as e:
        V21317_TICKER_STATE['fetch_fail'] = int(safe_float(V21317_TICKER_STATE.get('fetch_fail', 0), 0)) + 1
        V21317_TICKER_STATE['last_error'] = f'fetch:{e.__class__.__name__}:{str(e)[:60]}'
    return []
def get_cached_market_tickers(force=False):
    global market_all_tickers, market_all_tickers_time, last_ticker_fetch_attempt_ts
    now = _v21317_now()
    try:
        cached = _v21317_clean_ticker_list(globals().get('market_all_tickers', []) or [])
        cached_is_fallback = _v21317_is_fallback_tickers(cached)
        if cached and not cached_is_fallback:
            age = now - safe_float(globals().get('market_all_tickers_time', 0), 0)
            if age <= max(float(globals().get('TICKER_LIST_REFRESH_SEC', 3600)), 3600):
                V21317_TICKER_STATE.update({'last_good_count': len(cached), 'last_good_ts': globals().get('market_all_tickers_time', now), 'last_source': 'memory_full'})
                return list(cached)
            if age <= V21317_TICKER_LAST_GOOD_MAX_AGE_SEC:
                V21317_TICKER_STATE.update({'last_good_count': len(cached), 'last_good_ts': globals().get('market_all_tickers_time', now), 'last_source': 'memory_stale_full'})
                return list(cached)
        last_good = _v21317_load_last_good_tickers()
        if last_good:
            market_all_tickers = list(last_good)
            if not safe_float(globals().get('market_all_tickers_time', 0), 0):
                market_all_tickers_time = safe_float(V21317_TICKER_STATE.get('last_good_ts', now), now)
            return list(last_good)
        if force or _v21317_ticker_fetch_allowed():
            fetched = _v21317_direct_fetch_tickers()
            if fetched:
                market_all_tickers = list(fetched)
                market_all_tickers_time = now
                return list(fetched)
        base = _BASE_GET_CACHED_MARKET_TICKERS_V21317(force=False) if callable(_BASE_GET_CACHED_MARKET_TICKERS_V21317) else cached
        base = _v21317_clean_ticker_list(base)
        if base and not _v21317_is_fallback_tickers(base):
            _v21317_save_last_good_tickers(base, source='base_full')
            return list(base)
        V21317_TICKER_STATE['fallback_used'] = int(safe_float(V21317_TICKER_STATE.get('fallback_used', 0), 0)) + 1
        V21317_TICKER_STATE['last_source'] = 'emergency_60_fallback'
        fallback = _v21317_clean_ticker_list(base or globals().get('DEFAULT_MARKET_TICKERS', []) or [])
        return fallback
    except Exception as e:
        V21317_TICKER_STATE['last_error'] = f'wrapper:{e.__class__.__name__}'
        return _v21317_clean_ticker_list(globals().get('market_all_tickers', []) or globals().get('DEFAULT_MARKET_TICKERS', []) or [])
def _v21317_expand_universe_light(universe, tickers):
    rows = [dict(x) for x in list(universe or []) if isinstance(x, dict) and _v2136_ticker(x)]
    seen = {_v2136_ticker(x) for x in rows}
    target = min(len(_v21317_clean_ticker_list(tickers)), int(globals().get('V2138_UNIVERSE_SOFT_CAP', 220)))
    if target <= 0:
        return rows
    for t in _v21317_clean_ticker_list(tickers):
        if len(rows) >= target:
            break
        if t not in seen:
            if callable(globals().get('_v2138_seed_row')):
                rows.append(_v2138_seed_row(t))
            else:
                rows.append({'ticker': t, 'symbol': t, 'source': 'v21317_seed'})
            seen.add(t)
    return rows
def get_market_universe(force=False):
    global market_universe, market_universe_time
