def _v291_get_btc_df_cached(interval, min_len=20):
    now = time.time(); interval = str(interval or 'minute10')
    refresh, cool, max_reuse = (globals().get('BTC_V291_CFG') or {}).get(interval, (180,180,900))
    row = _v291_btc_row(interval) if callable(globals().get('_v291_btc_row')) else {}
    df = row.get('df') if isinstance(row, dict) else None
    ok_fn = globals().get('_v291_ok_df')
    ok = (ok_fn(df, int(min_len)) if callable(ok_fn) else (df is not None and len(df) >= int(min_len)))
    age = now - safe_float(row.get('ok_ts',0),0) if isinstance(row, dict) and safe_float(row.get('ok_ts',0),0)>0 else 999999
    if ok and age <= refresh:
        row['status'] = 'cache_hit'
        row['err'] = ''
        try: _v291_inc('hit', f'{interval} cache {int(age)}s')
        except Exception: pass
        return df, 'cache_hit', age
    if isinstance(row, dict) and safe_float(row.get('cool_until',0),0) > now:
        remain = safe_float(row.get('cool_until',0),0) - now
        row['status'] = 'cooldown'
        try: _v291_inc('cooldown', f'{interval} cooldown {int(remain)}s')
        except Exception: pass
        if ok and age <= max_reuse:
            try: _v291_inc('reuse', f'{interval} reuse {int(age)}s')
            except Exception: pass
            return df, 'cooldown_reuse', age
        return None, 'cooldown_no_data', age
    nd, st, detail = _v21318_btc_fetch_raw(interval, int(min_len))
    ok2 = (ok_fn(nd, int(min_len)) if callable(ok_fn) else (nd is not None and len(nd) >= int(min_len)))
    if isinstance(row, dict) and ok2:
        row.update({'df': nd, 'ok_ts': time.time(), 'cool_until': 0.0, 'fail': 0, 'status': 'fetch_ok', 'err': '', 'diag': detail})
        try: _v291_inc('fetch', f'{interval} fetch_ok')
        except Exception: pass
        return nd, 'fetch_ok', 0.0
    if isinstance(row, dict):
        row['fail'] = int(safe_float(row.get('fail',0),0)) + 1
        row['cool_until'] = time.time() + min(cool * max(1, row['fail']), cool * 3)
        row['status'] = 'fetch_fail'
        row['err'] = str(detail)[:160]
        row['diag'] = str(detail)[:240]
        try: _v291_inc('fail', f'{interval} fail:{str(detail)[:80]} -> cooldown {int(row["cool_until"]-time.time())}s')
        except Exception: pass
    if ok and age <= max_reuse:
        try: _v291_inc('reuse', f'{interval} fail_reuse {int(age)}s')
        except Exception: pass
        return df, 'fail_reuse', age
    return None, 'fetch_fail_no_cache', age
