        total = float(st.get('total', 0) or 0); pf = float(st.get('pf', 0) or 0)
        avg = total / max(1, n)
        best = float(st.get('best', 0) or 0); worst = float(st.get('worst', 0) or 0)
        return f"{n}전 {wins}승 {losses}패 / 승률 {wins/max(1,n)*100:.1f}% / 수익률 {total:+.2f}% / 평균 {avg:+.2f}% / 최고 {best:+.2f}% / 최악 {worst:+.2f}% / PF {pf:.2f}"
