    total = sum(vals); gw = sum(v for v in vals if v > 0); gl = -sum(v for v in vals if v < 0)
    return {'n': n, 'wins': wins, 'losses': losses, 'total': total, 'pf': (gw/gl if gl > 0 else (999.0 if gw > 0 else 0.0)), 'best': (max(vals) if vals else 0.0), 'worst': (min(vals) if vals else 0.0)}
