        ticker = str((row or {}).get('ticker', c.get('ticker','')) or '').upper().strip()
        known_ultra = ticker in {'BTT'}
        if same_big and no30 and (money <= V21320_TICK_NOISE_MONEY_MAX or tiny_price or known_ultra):
            return True
        if known_ultra and max_abs >= 8.0 and no30:
            return True
