    high_gap = safe_float(ctx.get('high_gap', ctx.get('below_high', ctx.get('high_gap_pct', row.get('high_gap', 999)))), 999)
    if high_gap >= 900: high_gap_unknown = True
    low_up = safe_float(ctx.get('low_up', ctx.get('from_low', ctx.get('from_low_pct', row.get('low_up', 0)))), 0)
    confidence = str(ctx.get('confidence', ctx.get('conf','')) or '')
    low_conf = ('낮' in confidence) or bool(ctx.get('low_conf'))
    decision = str(ctx.get('decision', ctx.get('status','')) or '')
