        reasons = [x for x in list(sc.get('reasons') or []) if x not in ('시간대미검증','고점거리미확인','낮은신뢰','살릴후보아님','확장스캔저장')][:3]
        if not reasons: reasons = list(sc.get('reasons') or [])[:3]
