def _v21340_clean_timefit_words(good, bad):
    try:
        raw_bad = [str(x or '').strip() for x in (bad or []) if str(x or '').strip()]
        has_slow = any(('slow' in x.lower()) or ('진행느림' in x) for x in raw_bad)
        good_map = {
            '5/15분 안 죽음': '단기흐름 유지',
            '거래대금 충분': '거래대금 충분',
            '고점거리 확인': '고점거리 확인',
            '신뢰도 양호': '신뢰도 양호',
            '완만한 움직임': '완만한 움직임',
            '기존 time_exit성향': 'time_exit 성향',
            '흐름값복구': '흐름값 복구',
        }
        bad_map = {
            '진행느림 큼': '진행느림 큼',
            '진행느림 주의': '진행느림 주의',
            '진행느림 위험': '진행느림 위험',
            '낮은신뢰': '신뢰 낮음',
            '고점거리 미확인': '고점거리 미확인',
            '움직임 약함': '움직임 약함',
        }
        out_good = []
        for x in good or []:
            x = str(x or '').strip()
            if not x:
                continue
            if has_slow and x == '5/15분 안 죽음':
                continue
            y = good_map.get(x, x.replace('slow', '진행느림'))
            if y and y not in out_good:
                out_good.append(y)
        out_bad = []
        for x in raw_bad:
            y = bad_map.get(x, x.replace('진행느림 큼', '진행느림 큼').replace('진행느림 주의', '진행느림 주의').replace('진행느림 위험', '진행느림 위험').replace('slow', '진행느림'))
            if y and y not in out_bad:
                out_bad.append(y)
        return out_good, out_bad
    except Exception:
        return list(good or []), list(bad or [])
