_FLOW_KEYS = ('change_1','change_1m','ch1','pct_1m','one_min_change','change_3','change_3m','ch3','pct_3m','change_5','change_5m','ch5','pct_5m','change_15','change_15m','ch15','pct_15m','change_30','change_30m','ch30','pct_30m')
_HIGH_KEYS = ('below_high','high_gap','high_gap_pct','below_30m_high_pct','distance_from_high','high_distance_pct')
