def _v21348_flow_grade(sc):
    sc = sc if isinstance(sc, dict) else {}
    ch = _v21348_ch(sc)
    ch1,ch3,ch5,ch15,ch30 = ch
    max_pos = max(ch[:4] + [0.0])
    max_abs = max([abs(x) for x in ch[:4]] + [0.0])
    money = _v21348_num(sc.get('money'), 0.0)
    flow_missing = bool(sc.get('flow_missing') or ('흐름확인전' in (sc.get('tags') or [])) or ('흐름확인전' in (sc.get('reasons') or [])))
    if flow_missing:
        return 'flow_unknown', ch, max_pos, max_abs
