def _v21349_diff_lines(good, bad):
    gp=_v21349_profile(good); bp=_v21349_profile(bad)
    lines=['🔍 차이 크게 볼 항목']
    if gp.get('n',0)<=0 or bp.get('n',0)<=0:
        return lines+['- 승리군/손실군 중 하나의 표본이 부족해서 차이 계산 보류']
    items=[('1분 변화율', gp['ch1'], bp['ch1'], 0.12, '%'), ('5분 변화율', gp['ch5'], bp['ch5'], 0.12, '%'), ('15분 변화율', gp['ch15'], bp['ch15'], 0.18, '%'), ('거래대금', gp['money'], bp['money'], 50000000, 'money'), ('고점확인비율', gp['high_known']/max(1,gp['n']), bp['high_known']/max(1,bp['n']), 0.25, 'ratio')]
    shown=0
    for name,a,b,th,unit in items:
        diff=a-b
        if abs(diff) < th: continue
        if unit=='money': av=_v21349_money_label(a); bv=_v21349_money_label(b); dv=_v21349_money_label(abs(diff))
        elif unit=='ratio': av=f"{a*100:.0f}%"; bv=f"{b*100:.0f}%"; dv=f"{abs(diff)*100:.0f}%p"
        else: av=f"{a:+.2f}%"; bv=f"{b:+.2f}%"; dv=f"{abs(diff):.2f}%p"
        mark='✅' if diff>0 else '⚠️'
        lines.append(f"- {mark} {name}: 승리군 {av} / 손실군 {bv} / 차이 {dv}")
        shown+=1
    if shown<=0:
        lines.append('- 아직 뚜렷한 수치 차이는 작음. 표본을 더 쌓아야 함')
    return lines
def build_mine_text_v21349(full=False):
    now=time.time()
    if (not full) and V21349_MINE_CACHE.get('text') and now - _v21349_num(V21349_MINE_CACHE.get('ts'),0) <= V21349_MINE_CACHE_TTL_SEC:
        return V21349_MINE_CACHE.get('text')
    start=time.time()
    rows=_v21349_closed_rows_all()
    v340=[r for r in rows if _v21349_is_v340(r)]
    v340.sort(key=_v21349_ts, reverse=True)
    feats=[_v21349_feat(r) for r in v340]
    good_primary=[f for f in feats if _v21349_num(f.get('pnl'),0)>0 and any(x in str(f.get('reason','')).lower() for x in ['time_exit','tp3','protect_stop_after_tp'])]
    good_extra=[f for f in feats if _v21349_num(f.get('pnl'),0)>0 and f not in good_primary]
    bad_primary=[f for f in feats if _v21349_num(f.get('pnl'),0)<0 and any(x in str(f.get('reason','')).lower() for x in ['slow','stop','crash','no_progress'])]
    bad_extra=[f for f in feats if _v21349_num(f.get('pnl'),0)<0 and f not in bad_primary]
    good=(good_primary+good_extra)[:10]
    bad=(bad_primary+bad_extra)[:10]
    all_st=_v21349_stat(feats)
    elapsed=time.time()-start
    lines=['🧪 v340 승패 공통점 분석 /mine', '', '✅ 결론']
    lines.append('- 저장된 CLOSED 결과를 읽어서 v340 승리군/손실군 공통점을 비교함')
    lines.append('- 자동매수 조건 변경 아님 / BUY_READY 강제 없음 / paper 기록 조회 전용')
    lines.append(f"- 읽은 범위: 전체 CLOSED {len(rows)}건 / v340 {len(v340)}건 / 분석 {len(good)}승리군 + {len(bad)}손실군")
    lines.append(f"- 처리시간: {elapsed:.2f}s / 정확도 우선 명령이라 조금 느려도 정상")
    lines += ['', '1) v340 전체 요약', '- ' + _v21349_stat_line(all_st)]
    lines += ['', *(_v21349_profile_lines('2) ✅ 승리군 공통점', good))]
    lines += ['', *(_v21349_profile_lines('3) ❌ 손실군 공통점', bad))]
    lines += ['', *(_v21349_diff_lines(good, bad))]
    lines += ['', '🎯 현재 후보 분류에 쓸 임시 판단']
    lines.append('- ✅ 집중관찰 후보: 승리군 특징 3개 이상 + 손실군 특징 1개 이하')
    lines.append('- ⚠️ 복기저장 후보: 승리군/손실군 특징이 섞임. 나중에 오른 애만 다시 보기')
    lines.append('- ❌ 제외 후보: slow/no_progress/stop/crash 손실군 특징 2개 이상')
    lines.append('- 코인명 영구차단은 하지 않음. 패턴 기준으로만 나눔')
    if full:
        lines += ['', *(_v21349_sample_lines('📌 승리군 최근 표본 최대 10건', good, 10))]
        lines += ['', *(_v21349_sample_lines('📌 손실군 최근 표본 최대 10건', bad, 10))]
    else:
        lines += ['', '📌 자세한 10건 목록: /mine full']
    text='\n'.join(lines)
    if not full:
        V21349_MINE_CACHE.update({'ts':now,'text':text,'full':False})
    return text
