def _v21349_profile_lines(title, fs):
    st=_v21349_stat(fs); p=_v21350_profile(fs)
    lines=[title, f"- 표본: {_v21349_stat_line(st)}"]
    if p.get('n',0)<=0:
        return lines + ['- 비교할 표본 없음']
