def _v21352_num(v, default=0.0):
    try:
        return safe_float(v, default) if callable(globals().get('safe_float')) else float(v)
    except Exception:
        return default
def _v21352_deep_pick(obj, keys, default=None, max_depth=4):
    """후보 row/ctx/score에 흩어진 값을 한 번에 찾는다. 없으면 default."""
    try:
        wanted = {str(k) for k in keys}
        seen = set()
        def walk(x, depth):
            if depth < 0:
                return None
            oid = id(x)
            if oid in seen:
                return None
            seen.add(oid)
            if isinstance(x, dict):
                for k in wanted:
                    if k in x and x.get(k) not in [None, '']:
                        return x.get(k)
                for v in x.values():
                    r = walk(v, depth-1)
                    if r not in [None, '']:
                        return r
            elif isinstance(x, (list, tuple)):
                for v in x[:20]:
                    r = walk(v, depth-1)
                    if r not in [None, '']:
                        return r
            return None
        r = walk(obj, max_depth)
        return default if r in [None, ''] else r
    except Exception:
        return default
