        good = list(base.get('good') or [])
        bad = list(base.get('bad') or [])
        for x in q.get('win_reasons') or []:
            if x not in good: good.append(x)
        for x in q.get('loss_reasons') or []:
            if x not in bad: bad.append(x)
        base['good'] = good[:6]
        base['bad'] = bad[:6]
