def _v21354_cause_tags(f, side='loss'):
    tags=[]
    try:
        reason=str(f.get('reason','')).lower()
        ch=list(f.get('ch') or [0,0,0,0])
        found=list(f.get('ch_found') or [False,False,False,False])
        def known(i):
            try: return bool(found[i])
            except Exception: return False
        def val(i):
            try: return float(ch[i])
            except Exception: return 0.0
        max_ch=f.get('max_ch')
        money=float(f.get('money') or 0.0)
        low=float(f.get('low_up') or 0.0)
        max_up=f.get('max_up')
        max_down=f.get('max_down')
        hold=f.get('hold_min')
        if side == 'loss':
            if any(x in reason for x in ['slow','no_progress']): tags.append('slow/no_progress 종료')
            if any(x in reason for x in ['stop','crash']): tags.append('stop/crash 손실')
            if max_ch is not None and max_ch < 0.12: tags.append('초반반응 없음')
            if known(2) and val(2) <= -0.45: tags.append('5분 흐름 약함')
            if known(3) and val(3) <= -0.35: tags.append('15분 흐름 약함')
            if low >= 0.45: tags.append(f'저점부담 큼 {low:.2f}%')
            if money >= 600_000_000 and (max_ch is None or max_ch < 0.15): tags.append('거래대금 큰데 진행 없음')
            if max_up is not None and float(max_up) < 0.25: tags.append(f'최고수익 낮음 {float(max_up):+.2f}%')
            if max_down is not None and float(max_down) <= -0.70: tags.append(f'중간낙폭 큼 {float(max_down):+.2f}%')
            if hold is not None and float(hold) >= 8 and (max_up is None or float(max_up) < 0.35): tags.append(f'오래 끌림 {float(hold):.0f}분')
        else:
            if 'time_exit' in reason: tags.append('time_exit 승리')
            if low <= 0.30: tags.append(f'저점부담 낮음 {low:.2f}%')
            if 120_000_000 <= money <= 900_000_000: tags.append('적정 거래대금')
            if max_ch is not None and max_ch >= 0.12: tags.append('초반 반응 있음')
            if known(2) and val(2) >= -0.35: tags.append('5분 흐름 방어')
            if max_up is not None and float(max_up) >= 0.45: tags.append(f'최고수익 확보 {float(max_up):+.2f}%')
            if max_down is not None and float(max_down) > -0.70: tags.append('중간낙폭 제한')
        if not tags:
            tags.append('원인 추가확인')
    except Exception:
        tags=['원인분석 오류']
    return tags[:8]
def _v21354_count_tags(fs, side):
    c={}
    for f in fs or []:
        for tag in _v21354_cause_tags(f, side=side):
            c[tag]=c.get(tag,0)+1
    return sorted(c.items(), key=lambda x:(-x[1], x[0]))
