    good_extra=[f for f in feats if _v21349_num(f.get('pnl'),0)>0 and f not in good_primary]
    bad_primary=[f for f in feats if _v21349_num(f.get('pnl'),0)<0 and any(x in str(f.get('reason','')).lower() for x in ['slow','stop','crash','no_progress'])]
    bad_extra=[f for f in feats if _v21349_num(f.get('pnl'),0)<0 and f not in bad_primary]
    good=(good_primary+good_extra)[:20]
    bad=(bad_primary+bad_extra)[:20]
