        good=list(base.get('good') or []); bad=list(base.get('bad') or [])
        for x in q.get('good') or []:
            if x not in good: good.append(x)
        for x in (q.get('hard') or []) + (q.get('bad') or []):
            if x not in bad: bad.append(x)
        base['good']=good[:7]; base['bad']=bad[:7]
