def _v21359_rank_score_for_sort(row):
    try:
        price_found = _v21359_num(row.get('price', row.get('current_price', 0)), 0) > 0
        flow = max(
            _v21359_num(row.get('change_1', row.get('change_1m', row.get('ch1', 0))), 0),
            _v21359_num(row.get('change_3', row.get('change_3m', row.get('ch3', 0))), 0),
            _v21359_num(row.get('change_5', row.get('change_5m', row.get('ch5', 0))), 0),
            _v21359_num(row.get('change_15', row.get('change_15m', row.get('ch15', 0))), 0),
            0.0,
        )
        abs_flow = max(
            abs(_v21359_num(row.get('change_1', row.get('change_1m', row.get('ch1', 0))), 0)),
            abs(_v21359_num(row.get('change_3', row.get('change_3m', row.get('ch3', 0))), 0)),
            abs(_v21359_num(row.get('change_5', row.get('change_5m', row.get('ch5', 0))), 0)),
            abs(_v21359_num(row.get('change_15', row.get('change_15m', row.get('ch15', 0))), 0)),
            0.0,
        )
        money = _v21359_num(row.get('turnover_5m', row.get('turnover', row.get('money', 0))), 0)
        live = 1 if bool(row.get('current_cache_ok')) or 'live_market' in str(row.get('v21359_sources','')) or 'ws_current' in str(row.get('v21359_sources','')) else 0
        rich = 1 if bool(row.get('v21347_flow_present')) or abs_flow > 0 or money > 0 else 0
        return (rich, live, flow, abs_flow * 0.25, min(money / 300_000_000.0, 5.0), 1 if price_found else 0)
    except Exception:
        return (0,0,0,0,0,0)
def _v21347_build_rank_rows(limit=70):
    safe_limit = max(20, min(int(_v21359_num(limit, 70)), int(globals().get('V21359_RANK_INPUT_LIMIT', 180))))
    try:
        pool, counts = _v21359_input_pool()
        live = _v21347_live_cache_map() if callable(globals().get('_v21347_live_cache_map')) else {}
        rows = []; seen = set()
        raw_rows = sorted(list(pool.values()), key=_v21359_rank_score_for_sort, reverse=True)
        for raw in raw_rows:
            t = _v21359_ticker(raw)
            if not t or t == 'BTC' or t in seen:
                continue
            try:
                rr = _v21347_rank_row(raw, len(rows)+1, set((live or {}).keys())) if callable(globals().get('_v21347_rank_row')) else dict(raw)
            except Exception:
                rr = dict(raw)
            if not isinstance(rr, dict):
                continue
            rr.setdefault('ticker', t)
            rr.setdefault('symbol', t)
            rr['v21359_input_wide'] = True
            rr['v21359_sources'] = raw.get('v21359_sources', rr.get('v21359_sources',''))
            rows.append(rr); seen.add(t)
            if len(rows) >= safe_limit:
                break
        rows.sort(key=_v21359_rank_score_for_sort, reverse=True)
        for i, r in enumerate(rows, 1):
            r['snapshot_rank'] = i
        now = time.time()
        try:
            globals()['COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS'] = list(rows)
            globals()['COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_TS'] = now
            globals()['COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_COUNT'] = len(rows)
            globals()['COMMAND_DISPLAY_CACHE_LAST_RANK_SNAPSHOT_NOTE'] = 'v21359 live+보조입력 rank/current 보강'
            globals()['V333_RANK_SOURCE_CACHE'] = {'ts': now, 'rows': list(rows), 'sec': 0.0, 'note': 'v21359 live+보조입력 rank/current 보강'}
            counts['rank_rows'] = len(rows)
            counts['current_rows'] = sum(1 for r in rows if isinstance(r, dict) and (_v21359_num(r.get('current_price', r.get('price', 0)), 0) > 0 or bool(r.get('current_cache_ok'))))
            V21359_INPUT_STATE.update({'ts': now, 'rows': len(rows), 'usable': counts.get('usable_pool', 0), 'counts': dict(counts), 'last_error': '', 'input_note': 'live+보조입력'})
            if isinstance(globals().get('V21347_SCAN_STATE'), dict):
                V21347_SCAN_STATE.update({'ts': now, 'rank': len(rows), 'current_cache': counts.get('current_rows', 0), 'source': 'v21359_wide_input', 'last_error': ''})
        except Exception:
            pass
        return list(rows)
    except Exception as e:
        try:
            V21359_INPUT_STATE.update({'last_error': 'rank:' + e.__class__.__name__})
            append_runtime_error_log('v21359_build_rank_rows', str(e), exc=e, include_traceback=False)
        except Exception:
            pass
        if callable(_BASE_V21359_BUILD_RANK_ROWS):
            try:
                return _BASE_V21359_BUILD_RANK_ROWS(limit=limit)
            except Exception:
                pass
        return []
