def _v21326_source_items(summary=None):
    s = summary if isinstance(summary, dict) else _v21326_cached_tf_summary()
    out=[]; seen=set()
    c = dict((V21359_INPUT_STATE or {}).get('counts') or {})
    counts={
        'scan_tf':0, 'missed_wait':0, 'rank_watch':0, 'rank_expand':0, 'rank_store':0,
        'live_market': int(c.get('live_market_unique', c.get('live_market', 0)) or 0),
        'prior_rank': int(c.get('prior_rank', 0) or 0),
        'market_universe': int(c.get('market_universe', 0) or 0),
        'ws_current': int(c.get('ws_current', 0) or 0),
        'light_price': int(c.get('light_price', 0) or 0),
        'api_price': int(c.get('api_price', 0) or 0),
        'input_pool': int(c.get('usable_pool', 0) or 0),
        'total_tickers': int(c.get('total_tickers', 0) or 0),
    }
    try:
        rows = list(s.get('rows') or [])
        ctxs = list(s.get('contexts') or [])
        for i, row in enumerate(rows[:V21359_SOURCE_SCAN_LIMIT]):
            ctx = ctxs[i] if i < len(ctxs) and isinstance(ctxs[i], dict) else (row if isinstance(row, dict) else {})
            item = _v21326_item_from(row if isinstance(row,dict) else {}, ctx, 'scan_tf')
            item = _v21328_reclassify_item(item, 'scan_tf')
            key = str(item.get('ticker') or '').upper()
            if key and key != '?' and key not in seen:
                out.append(item); seen.add(key); counts['scan_tf'] += 1
    except Exception:
        pass
