def _v21357_quality_causes(item):
    """v59: v57의 실패 원인 반영은 유지하되, 양수 흐름 후보 오판을 줄인다."""
    sc=(item or {}).get('score') or {}
    m=_v21357_item_metrics(item)
    ch=list(m.get('ch') or [0,0,0,0,0])
    ch=(ch+[0,0,0,0,0])[:5]
    ch=[_v21359_num(x,0.0) for x in ch]
    money=_v21359_num(m.get('money'),0.0)
    low=_v21359_num(m.get('low_burden'),999.0)
    high_gap=_v21359_num(m.get('high_gap'),999.0)
    max_pos=max(ch[:4]+[0.0])
    reasons=[str(x) for x in (sc.get('reasons') or [])]
    tags=[str(x) for x in (sc.get('tags') or [])]
    blob=' '.join(reasons+tags)
    basefit=_v21357_fit_base(item)
    fit_score=int(_v21359_num((basefit or {}).get('score'),0))
    bad=[]; good=[]; hard=[]
    early_positive = max(ch[0], ch[1], ch[2]) >= 0.12
    tiny_positive = max(ch[0], ch[1], ch[2]) > 0.05
    early_no_react = (not early_positive) and ch[0] <= 0.05 and ch[1] <= 0.08 and ch[2] <= 0.05
    big_money_no_progress = money >= 600_000_000 and early_no_react and ch[2] <= 0.05
    low_burden_big = low < 900 and low >= 0.45
    weak_5m = len(ch) >= 3 and ch[2] <= -0.35
    weak_15m = len(ch) >= 4 and ch[3] <= -0.35
    hard_slow = ('진행느림 큼' in blob) or ('slow강함' in blob) or str(sc.get('flow_grade')) == 'slow_hard'
    slow_watch = ('진행느림 주의' in blob) or str(sc.get('flow_grade')) == 'slow_watch'
    low_conf = bool(sc.get('low_conf'))
    tick_noise = bool(sc.get('tick_noise')) or ('틱노이즈' in blob)
    if early_no_react:
        bad.append('초반반응없음')
    else:
        good.append('초반반응있음')
    if big_money_no_progress:
        bad.append('거래대금큰데진행없음')
    elif money >= 600_000_000 and early_positive:
        good.append('대금있고초반반응있음')
    if low_burden_big:
        bad.append(f'저점부담큼{low:.2f}%')
    if weak_5m:
        bad.append('5분흐름약함')
    if weak_15m:
        bad.append('15분흐름약함')
    if hard_slow:
        bad.append('진행느림큼')
    elif slow_watch and early_no_react:
        bad.append('진행느림주의')
    elif slow_watch:
        good.append('진행느림주의지만반응있음')
    if low_conf:
        bad.append('낮은신뢰')
    if tick_noise:
        bad.append('틱노이즈')
    if big_money_no_progress and (low_burden_big or weak_5m or hard_slow):
        hard.append('거래대금큰데진행없음조합')
    if low_burden_big and (weak_5m or hard_slow or (early_no_react and not early_positive)):
        hard.append('저점부담+진행부족조합')
    if tick_noise or low_conf:
        hard.append('신뢰/틱노이즈차단')
    if fit_score >= 5:
        good.append(f'time_exit성향{fit_score}')
    if low < 900 and low <= 0.30:
        good.append(f'저점부담낮음{low:.2f}%')
    if len(ch)>=3 and ch[2] >= -0.35:
        good.append('5분흐름방어')
    if 120_000_000 <= money <= 900_000_000:
        good.append('적정거래대금')
    elif money > 0 and not big_money_no_progress:
        good.append('거래대금충분')
    if high_gap < 900:
        good.append('고점거리확인')
    if tiny_positive and '초반반응있음' not in good:
        good.append('약한양수반응')
    bad_unique=[]; good_unique=[]; hard_unique=[]
    for arr, out in [(bad,bad_unique),(good,good_unique),(hard,hard_unique)]:
        for x in arr:
            if x and x not in out:
                out.append(x)
    bad_count = len([x for x in bad_unique if x not in {'진행느림주의'}])
    if early_positive:
        bad_unique = [x for x in bad_unique if x not in {'초반반응없음','거래대금큰데진행없음'}]
        hard_unique = [x for x in hard_unique if x != '거래대금큰데진행없음조합']
        bad_count = len([x for x in bad_unique if x not in {'진행느림주의'}])
    return {
        'bad': bad_unique,
        'good': good_unique,
        'hard': hard_unique,
        'bad_count': int(max(bad_count, 0)),
        'good_count': len(good_unique),
        'fit_score': fit_score,
        'metrics': m,
    }
