def _v21360_position_pnl_text(pos):
    try:
        pos = pos if isinstance(pos, dict) else {}
        cur = _v21360_num(pos.get('current_price', pos.get('price', pos.get('last_price', 0))), 0)
        ent = _v21360_num(pos.get('entry_price', pos.get('buy_price', pos.get('avg_price', 0))), 0)
        pct = _v21360_num(pos.get('pnl_pct', pos.get('profit_pct', 0)), 0)
        if abs(pct) <= 0.0001 and ent > 0 and cur > 0:
            pct = ((cur-ent)/ent)*100.0
        if abs(pct) > 0.0001:
            return f'현재수익 {pct:+.2f}%'
    except Exception:
        pass
    return '현재수익 확인중'
