        if isinstance(ctx, dict): merged.update(ctx)
        st = str(merged.get('flow_data_status','') or '')
        reason = str(merged.get('flow_data_reason','') or '')
        if st in {'missing','calculated_unverified'}:
            remove = {'초반반응없음','거래대금큰데진행없음','진행느림주의'}
            q['bad'] = [x for x in list(q.get('bad') or []) if x not in remove]
            q['hard'] = [x for x in list(q.get('hard') or []) if x not in {'거래대금큰데진행없음조합','저점부담+진행부족조합'}]
