def run_batch_command_lines(lines, source_label='batch'):
    global V21339_BATCH_SNAPSHOT
    parsed = []
    try:
        for raw in lines or []:
            norm = _normalize_batch_line(raw)
            if not norm:
                continue
            cmd, args, orig = norm
            if cmd in {'batch', 'run'}:
                continue
            parsed.append((cmd, args, orig))
            if len(parsed) >= BATCH_COMMAND_MAX_LINES:
                break
        parsed = _v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed = [('core', [], '/core'), ('trade', [], '/trade'), ('score', [], '/score'), ('deploy', [], '/deploy')]
        batch_start = time.time()
        V21339_BATCH_SNAPSHOT = None
        send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.69: /mine_today 오늘복기 + paper 스냅샷 보강', '- 고정 스냅샷: 경량 모드 / 스캔은 넓게, 마지막 문턱은 복기로 확인']))
        timings = []
        total = len(parsed)
        try:
            for idx, (cmd, args, orig) in enumerate(parsed, 1):
                st = time.time(); status = 'OK'
                try:
                    _execute_single_batch_command(cmd, args, idx, total)
                except Exception as e:
                    status = f'ERR {e.__class__.__name__}'
                    send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}')
                timings.append({'cmd': cmd, 'after_start': st - batch_start, 'elapsed': time.time() - st, 'status': status})
        finally:
            try:
                send_text_chunks(_v2129_batch_timing_text(timings, batch_start, source_label), limit=2600)
            except Exception:
                pass
            V21339_BATCH_SNAPSHOT = None
    except Exception as e:
        try:
            V21369_STATE['last_error'] = 'batch:' + e.__class__.__name__
        except Exception:
            pass
        if callable(_BASE_V21369_BATCH_RUNNER):
            return _BASE_V21369_BATCH_RUNNER(lines, source_label=source_label)
        raise
