def _v21371_read_json_path(path, default=None):
    try:
        if default is None:
            default = {}
        if not path:
            return default
        p = str(path)
        if callable(globals().get('load_json_file')):
            try:
                return load_json_file(p, default)
            except Exception:
                pass
        import json
        with open(p, 'r', encoding='utf-8', errors='ignore') as f:
            return json.load(f)
    except Exception:
        return default if default is not None else {}
def _v21371_watch_store():
    """후보기록 파일만 가볍게 읽는다. 후보 재계산/gate_buckets 호출 금지."""
    candidates = []
    try:
        paths = []
        for fn in ('_v21326_watch_path', '_v21325_watch_path'):
            try:
                f = globals().get(fn)
                if callable(f):
                    paths.append(f())
            except Exception:
                pass
        try:
            if callable(globals().get('data_file')):
                paths += [data_file('candidate_watch_v21326.json'), data_file('candidate_watch_v21325.json')]
        except Exception:
            pass
        paths += ['candidate_watch_v21326.json', 'candidate_watch_v21325.json']
        seen_paths = []
        for p in paths:
            if not p or str(p) in seen_paths:
                continue
            seen_paths.append(str(p))
            data = _v21371_read_json_path(p, {})
            if not data:
                continue
            items = data.get('items') if isinstance(data, dict) else data
            if isinstance(items, dict):
                candidates = list(items.values())
            elif isinstance(items, list):
                candidates = items
            else:
                candidates = []
            if candidates:
                return {'path': str(p), 'data': data, 'items': [x for x in candidates if isinstance(x, dict)]}
    except Exception as e:
        try:
            V21371_STATE['last_error'] = 'watch_store:' + e.__class__.__name__
        except Exception:
            pass
    return {'path': '', 'data': {}, 'items': []}
def _v21371_item_ticker(x):
    try:
        for src in (x, x.get('row') if isinstance(x.get('row'), dict) else {}, x.get('ctx') if isinstance(x.get('ctx'), dict) else {}, x.get('score') if isinstance(x.get('score'), dict) else {}):
            if not isinstance(src, dict):
                continue
            for k in ('ticker','symbol','market','coin','code'):
                v = src.get(k)
                if v:
                    return str(v).upper().replace('KRW-', '').replace('KRW_', '').strip()
    except Exception:
        pass
    return '?'
def _v21371_item_group(x):
    try:
        for src in (x, x.get('score') if isinstance(x.get('score'), dict) else {}, x.get('row') if isinstance(x.get('row'), dict) else {}):
            if not isinstance(src, dict):
                continue
            for k in ('group','state','status','bucket','watch_group'):
                v = src.get(k)
                if v:
                    s = str(v)
                    if s in {'watch','관찰대기','집중관찰'}:
                        return 'watch'
                    if s in {'exclude','제외'}:
                        return 'exclude'
                    if s in {'pass','예비통과','buy_ready','BUY_READY'}:
                        return 'pass'
                    if s in {'store','복기저장','review'}:
                        return 'store'
                    if '관찰' in s:
                        return 'watch'
                    if '제외' in s:
                        return 'exclude'
                    if '복기' in s:
                        return 'store'
                    return s
    except Exception:
        pass
    return 'store'
def _v21371_store_counts(items):
    c = {'pass':0, 'watch':0, 'exclude':0, 'store':0, 'other':0}
    for x in items or []:
        g = _v21371_item_group(x)
        if g in c:
            c[g] += 1
        else:
            c['other'] += 1
    return c
def _v21371_item_score(x):
    try:
        sc = x.get('score') if isinstance(x.get('score'), dict) else x
        for k in ('fit_score','score','time_exit_score','quality_score'):
            if isinstance(sc, dict) and k in sc:
                return _v21371_num(sc.get(k), 0)
    except Exception:
        pass
    return 0.0
def _v21371_item_reason(x):
    try:
        sc = x.get('score') if isinstance(x.get('score'), dict) else {}
        parts = []
        for k in ('reasons','win_reasons','loss_reasons','tags'):
            vals = sc.get(k) if isinstance(sc, dict) else None
            if isinstance(vals, list):
                parts += [str(v) for v in vals[:3]]
        if not parts:
            for k in ('reason','decision','signal_decision','final_decision','grade'):
                v = x.get(k) if isinstance(x, dict) else None
                if v:
                    parts.append(str(v))
        return _v21371_short('·'.join(parts), 80) if parts else '-'
    except Exception:
        return '-'
def _v21371_recent_candidates(items, group='watch', limit=6):
    arr = []
    try:
        for x in items or []:
            if _v21371_item_group(x) == group:
                arr.append(x)
        arr.sort(key=lambda z: _v21371_item_score(z), reverse=True)
    except Exception:
        pass
    return arr[:limit]
