def _v21373_parse_date_args(args=None):
    """mine_today 인자에서 조회 날짜를 찾는다. full/detail 같은 인자는 무시."""
    today = _v21373_today_date()
    tokens = []
    try:
        tokens = [str(a).strip() for a in list(args or []) if str(a).strip()]
    except Exception:
        tokens = []
    token = ''
    for t in tokens:
        if t.lower() in {'full','all','detail','상세'}:
            continue
        token = t
        break
    if not token:
        return today, '오늘', ''
    t = token.lower()
    try:
        if t in {'today','오늘','금일'}:
            return today, '오늘', ''
        if t in {'yesterday','yday','prev','previous','어제','전날'}:
            return today - timedelta(days=1), '어제', ''
        for sep in ('-', '/', '.'):
            parts = token.split(sep)
            if len(parts) == 3 and all(p.isdigit() for p in parts):
                y, m, d = [int(p) for p in parts]
                return date(y, m, d), token, ''
            if len(parts) == 2 and all(p.isdigit() for p in parts):
                m, d = [int(p) for p in parts]
                return date(today.year, m, d), token, ''
    except Exception as e:
        return today, '오늘', f'날짜 인식 실패: {token} ({e.__class__.__name__})'
    return today, '오늘', f'날짜 인식 실패: {token} / 예: /mine_today yesterday 또는 /mine_today 2026-05-10'
