def _v21376_ticker_from_row(row):
    try:
        if not isinstance(row, dict):
            return ''
        for src in (row, row.get('score') if isinstance(row.get('score'), dict) else {}, row.get('row') if isinstance(row.get('row'), dict) else {}, row.get('ctx') if isinstance(row.get('ctx'), dict) else {}, row.get('entry_context') if isinstance(row.get('entry_context'), dict) else {}, row.get('v336_entry_context') if isinstance(row.get('v336_entry_context'), dict) else {}, row.get('v21369_entry_snapshot') if isinstance(row.get('v21369_entry_snapshot'), dict) else {}):
            if not isinstance(src, dict):
                continue
            for k in ('ticker','symbol','market','coin','code'):
                v = src.get(k)
                if v:
                    return _v21376_norm_ticker(v)
    except Exception:
        pass
    return ''
def _v21376_row_score(row):
    score = 0
    try:
        if not isinstance(row, dict):
            return 0
        for k in ('change_1m','change_3m','change_5m','change_15m','from_low','below_high','money_krw','trade_count','buy_ratio','price','current_price'):
            if k in row and row.get(k) not in (None, ''):
                score += 2
        for nested in ('score','row','ctx','entry_context','v336_entry_context','v21369_entry_snapshot'):
            v = row.get(nested)
            if isinstance(v, dict):
                score += _v21376_row_score(v) // 2
    except Exception:
        pass
    return score
def _v21376_add_source_rows(rows, out, label):
    n=0
    try:
        for r in list(rows or []):
            if not isinstance(r, dict):
                continue
            t = _v21376_ticker_from_row(r)
            if not t:
                continue
            rr = dict(r)
            rr['_v21376_source_label'] = str(label)
            old = out.get(t)
            if old is None or _v21376_row_score(rr) >= _v21376_row_score(old):
                out[t] = rr
            n += 1
    except Exception:
        pass
    return n
