def _execute_single_batch_command(cmd, args, idx, total):
    cmd_l=str(cmd or '').lower().strip().lstrip('/')
    label=f'▶️ 묶음 {idx}/{total} /{cmd_l}\n\n'
    try:
        if cmd_l in {'core','summary','quick','main','home'}:
            send_text_chunks(label + build_core_text_v21373(), limit=6200); return
        if cmd_l in {'trade','gate','candidate_gate','auto_summary','quality'}:
            send_text_chunks(label + build_trade_text_v21377(False), limit=8200); return
        if cmd_l in {'trade_full','quality_full'}:
            send_text_chunks(label + build_trade_text_v21377(True), limit=15000); return
        if cmd_l in {'score','today','performance','result','results'}:
            send_text_chunks(label + build_score_text_v21339(full=('full' in [str(a).lower() for a in (args or [])])), limit=9800); return
        if cmd_l in {'deploy','deploy_check','upgrade_check','upgradestatus'}:
            send_text_chunks(label + build_upgradestatus_text_v21339(), limit=7000); return
        if cmd_l in {'mine_today','today_mine','daily_mine','today_review','mine_today_full','today_mine_full'}:
            a=list(args or [])
            if cmd_l in {'mine_today_full','today_mine_full'} and 'full' not in [str(x).lower() for x in a]: a.append('full')
            send_text_chunks(label + build_mine_today_text_v21373(args=a, full=_v21373_args_full(a)), limit=3600); return
        if callable(_BASE_V21377_EXECUTE_SINGLE):
            return _BASE_V21377_EXECUTE_SINGLE(cmd,args,idx,total)
        send_text_chunks(label + '- 처리 함수 확인 필요', limit=3200)
    except Exception as e:
        send_text_chunks(label + f'⚠️ 처리 오류: {e.__class__.__name__}: {str(e)[:160]}', limit=3200)
def run_batch_command_lines(lines, source_label='batch'):
    global V21339_BATCH_SNAPSHOT
    parsed=[]
    try:
        for raw in lines or []:
            norm=_normalize_batch_line(raw)
            if not norm: continue
            cmd,args,orig=norm
            if cmd in {'batch','run'}: continue
            parsed.append((cmd,args,orig))
            if len(parsed) >= BATCH_COMMAND_MAX_LINES: break
        parsed=_v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed=[('core',[],'/core'),('trade',[],'/trade'),('score',[],'/score'),('deploy',[],'/deploy'),('mine',[],'/mine')]
        batch_start=time.time(); V21339_BATCH_SNAPSHOT=None
        send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.77: 최신 후보 기준 마지막 문턱 라벨링', '- 고정 스냅샷: 초경량 모드 / 스캔은 넓게, 문턱은 조합으로 분리']))
        timings=[]; total=len(parsed)
        try:
            for idx,(cmd,args,orig) in enumerate(parsed,1):
                st=time.time(); status='OK'
                try: _execute_single_batch_command(cmd,args,idx,total)
                except Exception as e:
                    status=f'ERR {e.__class__.__name__}'; send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}')
                timings.append({'cmd':cmd,'after_start':st-batch_start,'elapsed':time.time()-st,'status':status})
        finally:
            try: send_text_chunks(_v2129_batch_timing_text(timings,batch_start,source_label), limit=2600)
            except Exception: pass
            V21339_BATCH_SNAPSHOT=None
    except Exception as e:
        if callable(_BASE_V21377_BATCH_RUNNER):
            return _BASE_V21377_BATCH_RUNNER(lines, source_label=source_label)
        raise
