def _v21379_first_num_in_src(src, keys):
    try:
        if not isinstance(src, dict): return None, ''
        for k in keys:
            if k in src and src.get(k) not in (None, ''):
                return _v21378_num(src.get(k), 0.0) if callable(globals().get('_v21378_num')) else float(src.get(k) or 0), k
    except Exception:
        pass
    return None, ''
def _v21379_money_trace(row):
    """money_krw가 0으로 보이는 이유를 추적한다. 양수/소액/진짜0/저장누락을 분리."""
    trace = {
        'money_raw': 0.0,
        'money_status': '대금저장누락',
        'money_source': '',
        'money_key': '',
        'money_source_checked': [],
        'money_missing_reason': 'no_money_key_found',
        'money_zero_kind': '',
        'money_display': '대금 없음',
        'money_ok_for_top': False,
    }
    try:
        sources = _v21379_collect_source_dicts(row)
        positives=[]; zeros=[]; missing_sources=[]
        for sname, src in sources:
            val, key = _v21379_first_num_in_src(src, _V21379_MONEY_KEYS)
            if key:
                trace['money_source_checked'].append(f'{sname}:{key}')
                verified = bool(src.get('turnover_verified', src.get('actual_turnover_verified', False)))
                verify_status = str(src.get('turnover_verify_status','') or '').lower().strip()
                if val is not None and val > 0:
                    positives.append((float(val), sname, key, verified, verify_status))
                else:
                    zeros.append((0.0, sname, key, verified, verify_status))
            else:
                missing_sources.append(sname)
        if positives:
            val, sname, key, verified, verify_status = sorted(positives, key=lambda x: x[0], reverse=True)[0]
            trace['money_raw'] = float(val)
            trace['money_source'] = sname
            trace['money_key'] = key
            trace['money_missing_reason'] = ''
            if val < 1_000_000:
                trace['money_status'] = '소액확인'
                trace['money_zero_kind'] = 'small_positive'
                trace['money_display'] = f'{val:,.0f}원'
                trace['money_ok_for_top'] = False
                V21379_STATE['money_small'] = int(V21379_STATE.get('money_small',0)) + 1
            else:
                trace['money_status'] = '대금확인됨'
                trace['money_zero_kind'] = 'positive'
                trace['money_display'] = (f'{val/100000000:.2f}억' if val >= 100000000 else f'{val/10000:.0f}만')
                trace['money_ok_for_top'] = True
                V21379_STATE['money_positive'] = int(V21379_STATE.get('money_positive',0)) + 1
        elif zeros:
            verified_zero = [z for z in zeros if bool(z[3]) or str(z[4]) == 'ok']
            val, sname, key, verified, verify_status = (verified_zero[0] if verified_zero else zeros[0])
            trace['money_source'] = sname
            trace['money_key'] = key
            if verified_zero:
                trace['money_status'] = '진짜0확인'
                trace['money_zero_kind'] = 'verified_zero'
                trace['money_missing_reason'] = 'verified_zero_turnover'
                trace['money_display'] = '0원 확인'
                V21379_STATE['money_true_zero'] = int(V21379_STATE.get('money_true_zero',0)) + 1
            else:
                trace['money_status'] = '대금저장누락'
                trace['money_zero_kind'] = 'zero_unverified'
                trace['money_missing_reason'] = f'{sname}:{key}:zero_unverified'
                trace['money_display'] = '대금 0/누락'
                V21379_STATE['money_missing'] = int(V21379_STATE.get('money_missing',0)) + 1
        else:
            trace['money_status'] = '대금저장누락'
            trace['money_zero_kind'] = 'no_key'
            checked = ','.join(list(dict.fromkeys(missing_sources))[:8]) or 'no_sources'
            trace['money_missing_reason'] = f'money_key_missing_after_sources:{checked}'
            trace['money_display'] = '대금 저장누락'
            V21379_STATE['money_missing'] = int(V21379_STATE.get('money_missing',0)) + 1
        trace['money_source_checked'] = list(dict.fromkeys(trace.get('money_source_checked') or []))[:12]
        V21379_STATE['money_trace_done'] = int(V21379_STATE.get('money_trace_done',0)) + 1
        _v21379_inc_dict('money_source_counts', trace.get('money_source') or 'none')
        _v21379_inc_dict('money_status_counts', trace.get('money_status') or 'unknown')
        return trace
    except Exception as e:
        try: V21379_STATE['last_error'] = 'money_trace:' + e.__class__.__name__
        except Exception: pass
        trace['money_status'] = '대금추적오류'
        trace['money_missing_reason'] = str(e)[:120]
        return trace
def _v21379_quality_snapshot(row, stage='scan_candidate'):
    """v78 스냅샷에 money_trace를 덧씌우고, 0/누락/소액 기준으로 문턱 라벨을 재계산한다."""
    try:
        base = _BASE_V21379_QUALITY_SNAPSHOT(row, stage=stage) if callable(_BASE_V21379_QUALITY_SNAPSHOT) else {}
        if not isinstance(base, dict): base = {}
        tr = _v21379_money_trace(row)
        money = _v21378_num(tr.get('money_raw'), 0.0) if callable(globals().get('_v21378_num')) else float(tr.get('money_raw') or 0)
        base['schema'] = 'v21379_quality_snapshot'
        base['v21379_money_trace'] = tr
        base['money_krw'] = money
        base['money_raw'] = money
        base['money_status'] = tr.get('money_status')
        base['money_source'] = tr.get('money_source')
        base['money_key'] = tr.get('money_key')
        base['money_source_checked'] = tr.get('money_source_checked')
        base['money_missing_reason'] = tr.get('money_missing_reason')
        base['money_display'] = tr.get('money_display')
        base['money_eok'] = money / 100000000.0
        missing = list(base.get('missing') or [])
        md = list(base.get('missing_detail') or [])
        risk = list(base.get('risk_flags') or [])
        good = list(base.get('good_flags') or [])
        if not tr.get('money_ok_for_top'):
            if '거래대금' not in missing: missing.append('거래대금')
            reason = tr.get('money_missing_reason') or tr.get('money_status') or '대금미확인'
            if reason not in md: md.append(str(reason))
            good = [g for g in good if g not in {'time_exit/눌림닮음'}]
        risk = [r for r in risk if r not in {'거래대금큼','체결/매수약함','slow닮음'}]
        if money >= 500000000:
            risk.append('거래대금큼')
            cnt = _v21378_num(base.get('trade_count'),0) if callable(globals().get('_v21378_num')) else float(base.get('trade_count') or 0)
            buy = _v21378_num(base.get('buy_ratio'),0) if callable(globals().get('_v21378_num')) else float(base.get('buy_ratio') or 0)
            if cnt <= 0 and buy <= 0: risk.append('체결/매수약함')
            ch1 = _v21378_num(base.get('change_1m'),0); ch3 = _v21378_num(base.get('change_3m'),0); ch5 = _v21378_num(base.get('change_5m'),0)
            if max(ch1,ch3,ch5) < 0.18: risk.append('slow닮음')
        money_ok = bool(tr.get('money_ok_for_top'))
        risk_u = list(dict.fromkeys(risk)); good_u = list(dict.fromkeys(good)); miss_u = list(dict.fromkeys(missing)); md_u = list(dict.fromkeys(md))
        gate='관찰대기'; gate_reason='근거누적대기'
        if miss_u:
            flow_present = bool(base.get('flow_present')) or any(base.get(k) is not None for k in ('change_1m','change_3m','change_5m'))
            gate = '확인부족_흐름있음' if flow_present and (base.get('change_5m') is not None or base.get('change_1m') is not None) else '확인부족'
            gate_reason='·'.join(md_u[:4] or miss_u[:4])
        elif (len(risk_u) >= 4) or (len(risk_u) >= 3 and money >= 500000000):
            gate='복기우선'; gate_reason='·'.join(risk_u[:4])
        elif len(good_u) >= 3 and len(risk_u) <= 2 and money_ok:
            gate='상단관찰'; gate_reason='·'.join(good_u[:4])
        elif len(risk_u) >= 2:
            gate='복기대기'; gate_reason='·'.join(risk_u[:4])
        base['missing'] = miss_u
        base['missing_detail'] = md_u
        base['risk_flags'] = risk_u
        base['good_flags'] = good_u
        base['risk_n'] = len(risk_u)
        base['good_n'] = len(good_u)
        base['v21379_gate'] = gate
        base['v21379_gate_reason'] = gate_reason
        base['v21378_gate'] = gate
        base['v21378_gate_reason'] = gate_reason
        base['v21379_note'] = '대금0 원인추적 포함 / 매수조건 아님'
        return base
    except Exception as e:
        try: V21379_STATE['last_error'] = 'quality_snapshot:' + e.__class__.__name__
        except Exception: pass
        return {'schema':'v21379_quality_snapshot','stage':str(stage),'ticker':'','v21379_gate':'확인부족','v21378_gate':'확인부족','v21379_gate_reason':'스냅샷오류','missing_detail':['스냅샷오류'], 'error':str(e)[:120]}
def _v21378_quality_snapshot(row, stage='scan_candidate'):
    return _v21379_quality_snapshot(row, stage=stage)
def _v21379_attach_snapshot(row, stage='scan_candidate'):
    try:
        out = _v21378_attach_snapshot(row, stage=stage) if callable(globals().get('_v21378_attach_snapshot')) else (dict(row or {}) if isinstance(row, dict) else row)
        if isinstance(out, dict):
            snap = out.get('v21378_quality_snapshot') or _v21379_quality_snapshot(out, stage=stage)
            out['v21379_quality_snapshot'] = snap
            out['v21378_quality_snapshot'] = snap
            out['v21379_gate'] = snap.get('v21379_gate') or snap.get('v21378_gate')
            out['v21378_gate'] = out.get('v21379_gate')
            out['v21379_gate_reason'] = snap.get('v21379_gate_reason') or snap.get('v21378_gate_reason')
            out['v21378_gate_reason'] = out.get('v21379_gate_reason')
            if _v21378_num(snap.get('money_krw'),0) > 0:
                out['money_krw'] = snap.get('money_krw')
                out['money'] = snap.get('money_krw')
                out['turnover'] = snap.get('money_krw')
        return out
    except Exception:
        return row
def _v21379_attach_many(rows, stage='scan_candidate'):
    out=[]
