def _v21379_gate_groups(items):
    risk=[]; good=[]; missing=[]; wait=[]; missing_flow=[]
    try:
        for x in items or []:
            snap = x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}
            g = str(x.get('v21379_gate') or snap.get('v21379_gate') or snap.get('v21378_gate') or '관찰대기')
            if g == '상단관찰': good.append(x)
            elif g in {'복기우선','복기대기'}: risk.append(x)
            elif g == '확인부족_흐름있음': missing_flow.append(x)
            elif g == '확인부족': missing.append(x)
            else: wait.append(x)
        risk.sort(key=lambda x: (len((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('risk_flags') or []), _v21378_num((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('money_krw'),0)), reverse=True)
        good.sort(key=lambda x: (len((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('good_flags') or []), _v21378_num((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('money_krw'),0)), reverse=True)
        missing_flow.sort(key=lambda x: max(_v21378_num((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('change_1m'),0), _v21378_num((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('change_5m'),0)), reverse=True)
        missing.sort(key=lambda x: len((x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}).get('missing_detail') or []), reverse=True)
    except Exception:
        pass
    return risk, good, missing, missing_flow, wait
def _v21379_counts(items):
    c={'상단관찰':0,'복기우선':0,'복기대기':0,'확인부족':0,'확인부족_흐름있음':0,'관찰대기':0}
    try:
        for x in items or []:
            snap=x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}
            g=str(x.get('v21379_gate') or snap.get('v21379_gate') or snap.get('v21378_gate') or '관찰대기')
            c[g]=c.get(g,0)+1
    except Exception: pass
    return c
def _v21379_missing_reason_summary(items):
    c={}
    try:
        for x in items or []:
            snap=x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}
            for r in list(snap.get('missing_detail') or snap.get('missing') or []):
                c[str(r)] = c.get(str(r),0)+1
    except Exception: pass
    return c
def _v21379_line(x, mode='risk'):
    try:
        snap = x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or x.get('v21378_scan_snapshot') or {}
        flags = snap.get('risk_flags') if mode == 'risk' else snap.get('good_flags')
        if mode in {'missing','missing_flow'}: flags = snap.get('missing_detail') or snap.get('missing')
        gate = str(x.get('v21379_gate') or snap.get('v21379_gate') or snap.get('v21378_gate') or '-')
        src = str(snap.get('stage') or x.get('v21377_base_source') or x.get('_v21376_source_label') or '-')
        money_txt = str(snap.get('money_display') or '')
        if not money_txt:
            raw=_v21378_num(snap.get('money_krw'),0); money_txt = f'{raw/100000000:.2f}억' if raw>=100000000 else (f'{raw/10000:.0f}만' if raw>0 else '대금없음')
        trace = snap.get('v21379_money_trace') or {}
        cause = trace.get('money_missing_reason') or snap.get('money_missing_reason') or snap.get('money_status') or ''
        return (f"{_v21378_ticker(x) or '?'} / {gate} / 1m {_v21376_pct(snap.get('change_1m')) if callable(globals().get('_v21376_pct')) else snap.get('change_1m')} · "
                f"5m {_v21376_pct(snap.get('change_5m')) if callable(globals().get('_v21376_pct')) else snap.get('change_5m')} / "
                f"저점 {_v21376_pct(snap.get('from_low')) if callable(globals().get('_v21376_pct')) else snap.get('from_low')} · "
                f"고점 {_v21376_pct(snap.get('below_high')) if callable(globals().get('_v21376_pct')) else snap.get('below_high')} / "
                f"대금 {money_txt}({snap.get('money_status','')}) / 원인 {str(cause)[:34]} / {'·'.join(list(flags or [])[:4]) or '근거대기'} / 스냅샷 {src}")
    except Exception as e:
        return f'표시 오류: {e.__class__.__name__}: {str(e)[:80]}'
def _v21379_money_summary_line():
    try:
        sc = V21379_STATE.get('money_source_counts') or {}
        st = V21379_STATE.get('money_status_counts') or {}
        top_src = ' / '.join(f'{k} {v}' for k,v in sorted(sc.items(), key=lambda kv: kv[1], reverse=True)[:5]) or '대기'
        top_st = ' / '.join(f'{k} {v}' for k,v in sorted(st.items(), key=lambda kv: kv[1], reverse=True)[:5]) or '대기'
        return f"- v79 대금추적: 수행 {V21379_STATE.get('money_trace_done',0)} / 양수 {V21379_STATE.get('money_positive',0)} / 소액 {V21379_STATE.get('money_small',0)} / 진짜0 {V21379_STATE.get('money_true_zero',0)} / 누락 {V21379_STATE.get('money_missing',0)}\n- 대금상태: {top_st}\n- 대금출처: {top_src}"
    except Exception:
        return '- v79 대금추적: 표시 오류'
def build_trade_text_v21379(full=False):
    try:
        store = _v21379_enriched_candidates(full=full)
        items = store.get('items') or []
        risk, good, missing, missing_flow, wait = _v21379_gate_groups(items)
        c = _v21379_counts(items)
        miss_sum = _v21379_missing_reason_summary(missing + missing_flow)
        ref = store.get('ref_meta') or {}
        lines = [
            '🔎 v340 후보품질 /trade', '', '✅ 결론',
            '- v79: 대금 0을 라벨로 덮지 않고 출처·상태·누락 원인을 추적',
            '- 스캔 후보 품질 스냅샷은 유지하고, 상단관찰은 대금 확인 후보만 허용',
            '- 자동매수 OFF / BUY_READY 강제 없음', '',
            '1) 스캔→후보→paper 연결 상태',
            f"- 기준 후보: 최신 rank/cache 중심 {len(items)}개 / current map {int(store.get('current_count',0) or 0)}개",
            f"- candidate_watch: {ref.get('count',0)}개 / {ref.get('age','확인불가')} / 참고용{'(오래됨)' if ref.get('stale') else ''}",
            f"- v79 스냅샷: paper row {V21379_STATE.get('paper_row_enriched',0)} / paper context {V21379_STATE.get('paper_context_enriched',0)}",
            f"- 문턱 라벨: 상단관찰 {c.get('상단관찰',0)} / 복기우선 {c.get('복기우선',0)} / 복기대기 {c.get('복기대기',0)} / 확인부족 {c.get('확인부족',0)} / 확인부족_흐름있음 {c.get('확인부족_흐름있음',0)} / 관찰대기 {c.get('관찰대기',0)}",
            f"- 보강소스: {_v21376_source_counts_line(store.get('source_counts') or {}) if callable(globals().get('_v21376_source_counts_line')) else '확인중'}",
            _v21379_money_summary_line(),
        ]
        if miss_sum:
            bits=[f'{k} {v}' for k,v in sorted(miss_sum.items(), key=lambda kv: kv[1], reverse=True)[:6]]
            lines.append('- 확인부족 원인: ' + ' / '.join(bits))
        lines += ['', '2) 복기우선 후보(마지막 문턱에서 위로 올리지 않음 / 매수아님)']
        if risk:
            for i,x in enumerate(risk[:6 if not full else 14],1): lines.append(f'{i}. {_v21379_line(x,"risk")}')
        else: lines.append('- 현재 기준 강한 복기우선 후보가 뚜렷하지 않음')
        lines += ['', '3) 상단관찰 후보(표시만 / 매수아님)']
        if good:
            for i,x in enumerate(good[:6 if not full else 14],1): lines.append(f'{i}. {_v21379_line(x,"good")}')
        else: lines.append('- 현재 기준 상단관찰 후보가 뚜렷하지 않음')
        lines += ['', '4) 확인부족_흐름있음 후보(죽이지 않고 대금/기준값 원인 추적)']
        if missing_flow:
            for i,x in enumerate(missing_flow[:6 if not full else 14],1): lines.append(f'{i}. {_v21379_line(x,"missing_flow")}')
        else: lines.append('- 흐름은 있으나 대금/저점만 부족한 후보가 뚜렷하지 않음')
        lines += ['', '5) 확인부족 후보']
        if missing:
            for i,x in enumerate(missing[:6 if not full else 14],1): lines.append(f'{i}. {_v21379_line(x,"missing")}')
        else: lines.append('- 핵심값 부족 후보가 뚜렷하지 않음')
        lines += ['', '6) 문턱 원칙',
                  '- 0값·단기양수·단기음수·저점부담은 단독 문턱 금지',
                  '- 대금 0은 진짜0/소액/저장누락/보강실패로 분리해 원인을 본다',
                  '- 대금저장누락·진짜0·소액확인은 상단관찰 금지 또는 보수 표시',
                  '- 상단관찰/복기우선/확인부족은 자동매수/BUY_READY와 연결 없음']
        if full:
            lines += ['', '7) 최소 호출지도',
                      '- 허브/캐시: shared_market_cache / RANK_STATE / WS 체결 / verified_turnover를 money trace 후보로 수집',
                      '- 스캔 직원: get_light_snapshot_rank_rows / build_fast_scan_candidates_from_cache에서 v21379_quality_snapshot 부착',
                      '- 공장 저장: _save_fast_scan_state에 같은 스냅샷 유지',
                      '- paper 등록: paper_register_candidate_v258 row와 _v337/_v336 entry_context에 v21379_quality_snapshot 저장',
                      '- /trade: 저장된 스냅샷을 읽고 대금0 원인을 표시']
        return '\n'.join(lines)
    except Exception as e:
        try: V21379_STATE['last_error'] = 'trade:' + e.__class__.__name__
        except Exception: pass
        return f'🔎 v340 후보품질 /trade\n\n⚠️ v79 표시 오류: {e.__class__.__name__}: {str(e)[:160]}'
