def _v21380_inc_dict(dname, key, n=1):
    try:
        d = V21380_STATE.setdefault(dname, {})
        if not isinstance(d, dict):
            d = {}; V21380_STATE[dname] = d
        k = str(key or 'unknown')[:60]
        d[k] = int(float(d.get(k, 0) or 0)) + int(n)
    except Exception:
        pass
def _v21380_sources(row):
    out=[]; seen=set()
    def add(name, src):
        try:
            if not isinstance(src, dict) or not src:
                return
            ident=(name, id(src))
            if ident in seen:
                return
            seen.add(ident)
            rr=dict(src); rr.setdefault('_v21380_source_name', name)
            out.append((name, rr))
        except Exception:
            pass
    try:
        if callable(globals().get('_v21379_collect_source_dicts')):
            for name, src in _v21379_collect_source_dicts(row):
                add(name, src)
        elif callable(globals().get('_v21378_sources')):
            for src in _v21378_sources(row):
                add('row', src)
        else:
            add('row', row)
    except Exception:
        add('row', row)
    return out
def _v21380_first_num(src, keys):
    try:
        for k in keys:
            if isinstance(src, dict) and k in src and src.get(k) not in (None, ''):
                return _v21380_num(src.get(k), 0.0), k
    except Exception:
        pass
    return None, ''
def _v21380_pick_price(row):
    try:
        for name, src in _v21380_sources(row):
            v, k = _v21380_first_num(src, _V21380_PRICE_KEYS)
            if v is not None and v > 0:
                return float(v), f'{name}:{k}'
    except Exception:
        pass
    return 0.0, ''
def _v21380_price_history_for_ticker(ticker, row=None):
    """v64 가격이력에서 30분 저점/고점을 계산한다. REST/OHLCV 새 조회 없음."""
    try:
        if callable(globals().get('_v21364_load_history_once')):
            _v21364_load_history_once()
        if row is not None and callable(globals().get('_v21364_record_price')):
            try: _v21364_record_price(row)
            except Exception: pass
        hist = globals().get('V21364_PRICE_HISTORY')
        if not isinstance(hist, dict):
            return None
        t = _v21380_norm_ticker(ticker)
        arr = list(hist.get(t) or hist.get('KRW-'+t) or hist.get('KRW_'+t) or [])
        now = time.time() if 'time' in globals() else 0.0
        vals=[]
        for x in arr:
            try:
                ts = _v21380_num(x[0], 0.0); px = _v21380_num(x[1], 0.0)
                if px > 0 and (not now or now - ts <= 30*60):
                    vals.append((ts, px))
            except Exception:
                pass
        if not vals:
            return {'status':'없음','span':0.0,'count':0}
        vals.sort(key=lambda z: z[0])
        prices=[p for _,p in vals if p>0]
        span = (vals[-1][0] - vals[0][0]) if len(vals) >= 2 else 0.0
        return {'status':'있음','span':max(0.0, span),'count':len(vals),'low':min(prices),'high':max(prices),'last':prices[-1]}
    except Exception:
        return None
def _v21380_valid_pct(v, max_abs=200.0):
    try:
        x=float(v)
        return -max_abs <= x <= max_abs and x == x
    except Exception:
        return False
def _v21380_position_trace(row):
    """저점/고점 기준을 한 곳에서만 계산한다. 0/None/999 같은 비정상값은 계산값으로 쓰지 않는다."""
    trace = {
        'from_low': None,
        'below_high': None,
        'low_status': '저점기준없음',
        'high_status': '고점기준없음',
        'low_source': '', 'high_source': '',
        'low_missing_reason': 'low_key_missing',
        'high_missing_reason': 'high_key_missing',
        'history_span_sec': 0.0,
        'history_count': 0,
        'position_ok': False,
    }
    try:
        t = _v21380_ticker(row)
        price, price_src = _v21380_pick_price(row)
        for name, src in _v21380_sources(row):
            v, k = _v21380_first_num(src, _V21380_LOW_PCT_KEYS)
            if k and _v21380_valid_pct(v, 80.0):
                trace['from_low'] = round(max(0.0, float(v)), 4)
                trace['low_status'] = '저점기준확인'
                trace['low_source'] = f'{name}:{k}'
                trace['low_missing_reason'] = ''
                break
        for name, src in _v21380_sources(row):
            v, k = _v21380_first_num(src, _V21380_HIGH_GAP_KEYS)
            if k and _v21380_valid_pct(v, 80.0) and float(v) < 80.0:
                trace['below_high'] = round(max(0.0, float(v)), 4)
                trace['high_status'] = '고점기준확인'
                trace['high_source'] = f'{name}:{k}'
                trace['high_missing_reason'] = ''
                break
            elif k and (not _v21380_valid_pct(v, 80.0) or float(v) >= 80.0):
                trace['high_status'] = '고점기준오류'
                trace['high_source'] = f'{name}:{k}'
                trace['high_missing_reason'] = 'high_gap_invalid'
        if price > 0 and trace['from_low'] is None:
            for name, src in _v21380_sources(row):
                low_p, low_k = _v21380_first_num(src, _V21380_LOW_PRICE_KEYS)
                if low_k and low_p and low_p > 0:
                    pct = ((price - low_p) / low_p) * 100.0
                    if _v21380_valid_pct(pct, 80.0):
                        trace['from_low'] = round(max(0.0, pct), 4)
                        trace['low_status'] = '저점기준확인'
                        trace['low_source'] = f'{name}:{low_k}+{price_src}'
                        trace['low_missing_reason'] = ''
                        break
        if price > 0 and trace['below_high'] is None:
            for name, src in _v21380_sources(row):
                high_p, high_k = _v21380_first_num(src, _V21380_HIGH_PRICE_KEYS)
                if high_k and high_p and high_p > 0:
                    pct = ((high_p - price) / high_p) * 100.0
                    if _v21380_valid_pct(pct, 80.0) and pct < 80.0:
                        trace['below_high'] = round(max(0.0, pct), 4)
                        trace['high_status'] = '고점기준확인'
                        trace['high_source'] = f'{name}:{high_k}+{price_src}'
                        trace['high_missing_reason'] = ''
                        break
                    else:
                        trace['high_status'] = '고점기준오류'
                        trace['high_source'] = f'{name}:{high_k}+{price_src}'
                        trace['high_missing_reason'] = 'high_price_invalid_gap'
        hist = _v21380_price_history_for_ticker(t, row)
        if isinstance(hist, dict):
            span = _v21380_num(hist.get('span'), 0.0); cnt = int(_v21380_num(hist.get('count'), 0))
            trace['history_span_sec'] = round(span, 1); trace['history_count'] = cnt
            hp = price or _v21380_num(hist.get('last'), 0.0)
            if hist.get('status') == '있음' and hp > 0:
                if trace['from_low'] is None and _v21380_num(hist.get('low'), 0.0) > 0:
                    pct = ((hp - _v21380_num(hist.get('low'), hp)) / _v21380_num(hist.get('low'), hp)) * 100.0
                    if _v21380_valid_pct(pct, 80.0):
                        trace['from_low'] = round(max(0.0, pct), 4)
                        trace['low_status'] = '저점기준확인'
                        trace['low_source'] = f'price_history_30m:{cnt}/{int(span)}s'
                        trace['low_missing_reason'] = ''
                        V21380_STATE['low_history'] = int(V21380_STATE.get('low_history',0)) + 1
                if trace['below_high'] is None and _v21380_num(hist.get('high'), 0.0) > 0:
                    high = _v21380_num(hist.get('high'), hp)
                    pct = ((high - hp) / high) * 100.0 if high > 0 else 999.0
                    if _v21380_valid_pct(pct, 80.0) and pct < 80.0:
                        trace['below_high'] = round(max(0.0, pct), 4)
                        trace['high_status'] = '고점기준확인'
                        trace['high_source'] = f'price_history_30m:{cnt}/{int(span)}s'
                        trace['high_missing_reason'] = ''
                        V21380_STATE['high_history'] = int(V21380_STATE.get('high_history',0)) + 1
            if trace['from_low'] is None:
                if span < 180:
                    trace['low_status'] = '저점기준수집중'; trace['low_missing_reason'] = f'price_history_warmup_{int(span)}s'
                    V21380_STATE['low_warming'] = int(V21380_STATE.get('low_warming',0)) + 1
                else:
                    trace['low_status'] = '저점기준없음'; trace['low_missing_reason'] = 'price_history_low_missing'
            if trace['below_high'] is None and trace['high_status'] != '고점기준오류':
                if span < 180:
                    trace['high_status'] = '고점기준수집중'; trace['high_missing_reason'] = f'price_history_warmup_{int(span)}s'
                else:
                    trace['high_status'] = '고점기준없음'; trace['high_missing_reason'] = 'price_history_high_missing'
        if trace['from_low'] is not None:
            V21380_STATE['low_valid'] = int(V21380_STATE.get('low_valid',0)) + 1
        else:
            V21380_STATE['low_missing'] = int(V21380_STATE.get('low_missing',0)) + 1
        if trace['below_high'] is not None:
            V21380_STATE['high_valid'] = int(V21380_STATE.get('high_valid',0)) + 1
        elif trace['high_status'] == '고점기준오류':
            V21380_STATE['high_invalid'] = int(V21380_STATE.get('high_invalid',0)) + 1
        trace['position_ok'] = trace['from_low'] is not None and trace['below_high'] is not None
        V21380_STATE['low_trace_done'] = int(V21380_STATE.get('low_trace_done',0)) + 1
        _v21380_inc_dict('source_counts', trace.get('low_source') or trace.get('low_status'))
        return trace
    except Exception as e:
        try: V21380_STATE['last_error'] = 'position_trace:' + e.__class__.__name__
        except Exception: pass
        trace['low_status'] = '저점추적오류'; trace['high_status'] = '고점추적오류'; trace['low_missing_reason'] = str(e)[:80]
        return trace
def _v21380_recalc_gate(base):
    try:
        money = _v21380_num(base.get('money_raw', base.get('money_krw')), 0.0)
        money_status = str(base.get('money_status') or '')
        money_ok = bool(base.get('money_ok_for_top')) or money_status == '대금확인됨'
        low_status = str(base.get('low_status') or '')
        high_status = str(base.get('high_status') or '')
        from_low = base.get('from_low')
        below_high = base.get('below_high')
        ch1 = _v21380_num(base.get('change_1m'), 0.0)
        ch3 = _v21380_num(base.get('change_3m'), 0.0)
        ch5 = _v21380_num(base.get('change_5m'), 0.0)
        ch15 = _v21380_num(base.get('change_15m'), 0.0)
        risk = [r for r in list(base.get('risk_flags') or []) if r]
        good = [g for g in list(base.get('good_flags') or []) if g]
        missing = [m for m in list(base.get('missing') or []) if m]
        md = [m for m in list(base.get('missing_detail') or []) if m]
        risk = [r for r in risk if r not in {'저점부담높음','저점부담높음0.46%','저점기준없음','고점기준오류','거래대금큼','체결/매수약함','slow닮음'}]
        good = [g for g in good if g not in {'저점부담낮음','저점부담낮음0.00%','고점거리확인','고점여유적당','초반반응있음'}]
        if from_low is None:
            if '저점부담' not in missing: missing.append('저점부담')
            if low_status and low_status not in md: md.append(low_status)
        elif _v21380_num(from_low, 99) <= 0.25:
            good.append(f'저점부담낮음{_v21380_num(from_low,0):.2f}%')
        elif _v21380_num(from_low, 0) >= 0.55:
            risk.append(f'저점부담높음{_v21380_num(from_low,0):.2f}%')
        if below_high is None:
            if '고점거리' not in missing: missing.append('고점거리')
            if high_status and high_status not in md: md.append(high_status)
        elif 0 <= _v21380_num(below_high, 999) < 80:
            good.append('고점거리확인')
            if 0.15 <= _v21380_num(below_high,0) <= 1.20:
                good.append('고점여유적당')
        if not money_ok:
            if '거래대금' not in missing: missing.append('거래대금')
            ms = str(base.get('money_status') or base.get('money_missing_reason') or '대금미확인')
            if ms and ms not in md: md.append(ms)
        elif money >= 500000000:
            risk.append('거래대금큼')
            if _v21380_num(base.get('trade_count'),0) <= 0 and _v21380_num(base.get('buy_ratio'),0) <= 0:
                risk.append('체결/매수약함')
            if max(ch1, ch3, ch5) < 0.18:
                risk.append('slow닮음')
        if max(ch1, ch3, ch5) >= 0.12:
            good.append('초반반응있음')
        if ch5 < -0.25:
            risk.append('5분흐름약함')
        if ch15 < -0.20:
            risk.append('15분약함')
        risk = list(dict.fromkeys(risk)); good = list(dict.fromkeys(good)); missing = list(dict.fromkeys(missing)); md = list(dict.fromkeys(md))
        gate='관찰대기'; reason='근거누적대기'
        flow_present = any(v is not None for v in (base.get('change_1m'), base.get('change_3m'), base.get('change_5m'))) or max(abs(ch1), abs(ch3), abs(ch5)) > 0
        hard_missing = [m for m in md if m in {'저점기준없음','고점기준없음','저점기준수집중','고점기준수집중','저점추적오류','고점추적오류','대금저장누락','진짜0확인','소액확인'} or '기준' in str(m) or '대금' in str(m)]
        if missing:
            gate = '확인부족_흐름있음' if flow_present else '확인부족'
            reason = '·'.join((hard_missing or md or missing)[:4])
        elif len(risk) >= 4 or (len(risk) >= 3 and money >= 500000000):
            gate='복기우선'; reason='·'.join(risk[:4])
        elif len(good) >= 3 and len(risk) <= 2 and money_ok:
            gate='상단관찰'; reason='·'.join(good[:4])
        elif len(risk) >= 2:
            gate='복기대기'; reason='·'.join(risk[:4])
        base['missing'] = missing; base['missing_detail'] = md
        base['risk_flags'] = risk; base['good_flags'] = good
        base['risk_n'] = len(risk); base['good_n'] = len(good)
        base['v21380_gate'] = gate; base['v21380_gate_reason'] = reason
        base['v21379_gate'] = gate; base['v21379_gate_reason'] = reason
        base['v21378_gate'] = gate; base['v21378_gate_reason'] = reason
        return base
    except Exception as e:
        try: V21380_STATE['last_error'] = 'recalc_gate:' + e.__class__.__name__
        except Exception: pass
        base['v21380_gate']='확인부족'; base['v21380_gate_reason']='문턱계산오류'
        return base
def build_v340_quality_snapshot_v21380(row, stage='scan_candidate'):
    """스캔→공장→paper가 공통으로 쓰는 단일 후보품질 스냅샷. v76~v79 후처리층을 여기로 흡수한다."""
    try:
        base = _BASE_V21380_QUALITY_SNAPSHOT(row, stage=stage) if callable(_BASE_V21380_QUALITY_SNAPSHOT) else {}
        if not isinstance(base, dict): base = {}
        try:
            tr = _v21379_money_trace(row) if callable(globals().get('_v21379_money_trace')) else {}
        except Exception:
            tr = {}
        if isinstance(tr, dict) and tr:
            base['v21380_money_trace'] = tr
            base['v21379_money_trace'] = tr
            for k in ('money_raw','money_status','money_source','money_key','money_source_checked','money_missing_reason','money_display','money_ok_for_top'):
                base[k] = tr.get(k)
            base['money_krw'] = _v21380_num(tr.get('money_raw'), 0.0)
            base['money_eok'] = base['money_krw'] / 100000000.0
        pos = _v21380_position_trace(row)
        base['v21380_position_trace'] = pos
        base['from_low'] = pos.get('from_low')
        base['below_high'] = pos.get('below_high')
        base['low_status'] = pos.get('low_status')
        base['high_status'] = pos.get('high_status')
        base['low_source'] = pos.get('low_source')
        base['high_source'] = pos.get('high_source')
        base['low_missing_reason'] = pos.get('low_missing_reason')
        base['high_missing_reason'] = pos.get('high_missing_reason')
        base['history_span_sec'] = pos.get('history_span_sec')
        base['history_count'] = pos.get('history_count')
        base['schema'] = 'v21380_quality_snapshot'
        base['stage'] = str(stage)
        base['ticker'] = _v21380_ticker(row) or base.get('ticker')
        base['snapshot_ts'] = time.time() if 'time' in globals() else 0.0
        base = _v21380_recalc_gate(base)
        base['v21380_note'] = '스캔 후보품질 단일 스냅샷 / 매수조건 아님'
        V21380_STATE['snapshot_built'] = int(V21380_STATE.get('snapshot_built',0)) + 1
        for r in list(base.get('missing_detail') or []):
            _v21380_inc_dict('missing_counts', r)
        return base
    except Exception as e:
        try: V21380_STATE['last_error'] = 'snapshot:' + e.__class__.__name__
        except Exception: pass
        return {'schema':'v21380_quality_snapshot','stage':str(stage),'ticker':'','v21380_gate':'확인부족','v21380_gate_reason':'스냅샷오류','missing_detail':['스냅샷오류'], 'error':str(e)[:120]}
def _v21380_quality_snapshot(row, stage='scan_candidate'):
    return build_v340_quality_snapshot_v21380(row, stage=stage)
def _v21379_quality_snapshot(row, stage='scan_candidate'):
    return build_v340_quality_snapshot_v21380(row, stage=stage)
def _v21378_quality_snapshot(row, stage='scan_candidate'):
    return build_v340_quality_snapshot_v21380(row, stage=stage)
def _v21380_attach_snapshot(row, stage='scan_candidate'):
    try:
        out = dict(row or {}) if isinstance(row, dict) else {}
        snap = build_v340_quality_snapshot_v21380(out, stage=stage)
        out['v21380_quality_snapshot'] = snap
        out['v21379_quality_snapshot'] = snap
        out['v21378_quality_snapshot'] = snap
        out['v21380_gate'] = snap.get('v21380_gate')
        out['v21380_gate_reason'] = snap.get('v21380_gate_reason')
        out['v21379_gate'] = snap.get('v21380_gate')
        out['v21379_gate_reason'] = snap.get('v21380_gate_reason')
        out['v21378_gate'] = snap.get('v21380_gate')
        out['v21378_gate_reason'] = snap.get('v21380_gate_reason')
        sc = out.get('score')
        if isinstance(sc, dict):
            sc['v21380_quality_snapshot'] = snap
            sc['v21379_quality_snapshot'] = snap
            sc['v21378_quality_snapshot'] = snap
            sc['v21380_gate'] = snap.get('v21380_gate')
            sc['v21380_gate_reason'] = snap.get('v21380_gate_reason')
        return out
    except Exception:
        return row if isinstance(row, dict) else {}
def _v21379_attach_snapshot(row, stage='scan_candidate'):
    return _v21380_attach_snapshot(row, stage=stage)
def _v21378_attach_snapshot(row, stage='scan_candidate'):
    return _v21380_attach_snapshot(row, stage=stage)
