        ctx['v21379_gate'] = ctx['v21380_gate']; ctx['v21379_gate_reason'] = ctx['v21380_gate_reason']
        ctx['v21378_gate'] = ctx['v21380_gate']; ctx['v21378_gate_reason'] = ctx['v21380_gate_reason']
