def _v21380_gate_of(x):
    snap = x.get('v21380_quality_snapshot') or x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}
    return str(x.get('v21380_gate') or snap.get('v21380_gate') or snap.get('v21379_gate') or snap.get('v21378_gate') or '관찰대기')
def _v21380_snap(x):
    return x.get('v21380_quality_snapshot') or x.get('v21379_quality_snapshot') or x.get('v21378_quality_snapshot') or {}
def _v21380_gate_groups(items):
    risk=[]; good=[]; missing=[]; missing_flow=[]; wait=[]
    try:
        for x in items or []:
            g = _v21380_gate_of(x)
            if g == '상단관찰': good.append(x)
            elif g in {'복기우선','복기대기'}: risk.append(x)
            elif g == '확인부족_흐름있음': missing_flow.append(x)
            elif g == '확인부족': missing.append(x)
            else: wait.append(x)
        risk.sort(key=lambda x: (len(_v21380_snap(x).get('risk_flags') or []), _v21380_num(_v21380_snap(x).get('money_krw'),0)), reverse=True)
        good.sort(key=lambda x: (len(_v21380_snap(x).get('good_flags') or []), _v21380_num(_v21380_snap(x).get('money_krw'),0)), reverse=True)
        missing_flow.sort(key=lambda x: max(_v21380_num(_v21380_snap(x).get('change_1m'),0), _v21380_num(_v21380_snap(x).get('change_5m'),0)), reverse=True)
        missing.sort(key=lambda x: len(_v21380_snap(x).get('missing_detail') or []), reverse=True)
    except Exception:
        pass
    return risk, good, missing, missing_flow, wait
def _v21380_counts(items):
    c={'상단관찰':0,'복기우선':0,'복기대기':0,'확인부족':0,'확인부족_흐름있음':0,'관찰대기':0}
    try:
        for x in items or []:
            g=_v21380_gate_of(x); c[g]=c.get(g,0)+1
    except Exception:
        pass
    return c
