def _v21382_pipeline_selfcheck():
    """사용자가 매번 수동 분석하지 않도록 연결 상태를 자동 판정한다."""
    V21382_STATE['selfcheck_called']=int(V21382_STATE.get('selfcheck_called',0))+1
    checks=[]
    try:
        rank=int(V21380_STATE.get('rank_rows_enriched',0) or 0)
        scan=int(V21380_STATE.get('scan_items_enriched',0) or 0)
        saved=int(V21380_STATE.get('save_state_enriched',0) or 0)
        built=int(V21380_STATE.get('snapshot_built',0) or 0)
        attempts=int(V21380_STATE.get('paper_register_attempts',0) or 0)
        prow=int(V21380_STATE.get('paper_row_enriched',0) or 0)
        pctx=int(V21380_STATE.get('paper_context_enriched',0) or 0)
        stale_money=int(V21382_STATE.get('stale_money_reason_removed',0) or 0)
        if rank > 0 and built > 0:
            checks.append(('✅','rank 스냅샷','정상',f'rank {rank} / 생성 {built}'))
        elif built > 0:
            checks.append(('⚠️','rank 스냅샷','부분',f'생성 {built} / rank {rank}'))
        else:
            checks.append(('❔','rank 스냅샷','대기','아직 생성 기록 없음'))
        if scan > 0 and saved > 0:
            checks.append(('✅','스캔→공장저장','정상',f'scan {scan} / 저장 {saved}'))
        elif scan > 0 and saved == 0:
            checks.append(('⚠️','스캔→공장저장','저장 미확인',f'scan {scan} / 저장 {saved}'))
        elif rank > 0:
            checks.append(('❔','스캔→공장저장','스캔루프 대기 또는 cache 없음',f'rank는 있음 / scan {scan} / 저장 {saved}'))
        else:
            checks.append(('❔','스캔→공장저장','대기','rank/scan 모두 대기'))
        if attempts > 0 and pctx > 0:
            checks.append(('✅','paper 전달','정상',f'hook {attempts} / row {prow} / context {pctx}'))
        elif attempts > 0 and prow > 0 and pctx == 0:
            checks.append(('⚠️','paper 전달','context 미검증',f'hook {attempts} / row {prow} / context {pctx}'))
        elif attempts > 0:
            checks.append(('❌','paper 전달','hook 미작동 의심',f'hook {attempts} / row {prow} / context {pctx}'))
        else:
            checks.append(('❔','paper 전달','신규등록 없음/문턱 미도달',f'hook {attempts} / row {prow} / context {pctx}'))
        if stale_money > 0:
            checks.append(('✅','문턱 원인 정리','낡은 대금원인 제거됨',f'제거 {stale_money}'))
        else:
            checks.append(('❔','문턱 원인 정리','추가 검증 대기','낡은 원인 제거 기록 없음'))
        bad=[c for c in checks if c[0] in {'❌','⚠️'}]
        if any(c[0]=='❌' for c in checks): status='❌ 수술구간 연결 오류 의심'
        elif any(c[0]=='⚠️' for c in checks): status='⚠️ 수술구간 일부 미검증'
        elif any(c[0]=='❔' for c in checks): status='❔ 신규 이벤트 대기'
        else: status='✅ 수술구간 연결 정상'
        V21382_STATE['last_status']=status
        return status, checks
    except Exception as e:
        try: V21382_STATE['last_error']='selfcheck:'+e.__class__.__name__
        except Exception: pass
        return '⚠️ 자체검사 오류', [('⚠️','자체검사','오류',str(e)[:120])]
