def _v21385_scan_status_lines(source=''):
    try:
        latest=list(globals().get('latest_fast_scan_items') or [])
        age=None
        try:
            ts=float(globals().get('latest_fast_scan_result_ts') or 0)
            age=(_v21385_now()-ts) if ts else None
        except Exception:
            age=None
        rank=list(globals().get('COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS') or [])
        ws=len(globals().get('RANK_STATE_BY_TICKER') or {})
        cache_len=0
        try: cache_len=len(globals().get('shared_market_cache') or {})
        except Exception: pass
        if latest:
            state=f'✅ 스캔 저장 후보 있음 / latest {len(latest)}개 / {int(age)}초 전' if age is not None else f'✅ 스캔 저장 후보 있음 / latest {len(latest)}개'
        elif rank:
            state=f'❔ 스캔 저장 후보 없음 / rank 표시 {len(rank)}개로 조회중'
        else:
            state='⚠️ 스캔 저장 후보·rank 모두 부족'
        return [state, f'- 조회소스: {source or "확인중"} / latest {len(latest)} / rank {len(rank)} / WS상태 {ws} / 시장캐시 {cache_len}']
    except Exception:
        return ['⚠️ 스캔 상태 표시 오류']
