        new_attempts = [dict(x) for x in _v21386_read_json_list(globals().get('PAPER_V336_ATTEMPTS_FILE')) if isinstance(x, dict)]
        new_rejects = [dict(x) for x in _v21386_read_json_list(globals().get('PAPER_V336_REJECT_LOG_FILE')) if isinstance(x, dict)]
        with PAPER_STATE_LOCK:
            paper_positions = {str(k): dict(v) for k, v in new_positions.items() if isinstance(v, dict)}
            paper_trade_log = new_log[-int(globals().get('PAPER_V336_MAX_LOG', 3000)):]
            paper_entry_attempts_v336 = new_attempts[-int(globals().get('PAPER_V336_MAX_ATTEMPTS', 2500)):]
