        lines.append(f"- 메모리 로드: positions {m.get('positions_total',0)}개(PENDING {m.get('pending',0)} / OPEN {m.get('open',0)}) / trade_log {m.get('trade_log',0)}건")
        lines.append(f"- 기존 PENDING 재문턱: {V21386_STATE.get('paper_pending_regated',0)}건 / 유지 {V21386_STATE.get('paper_pending_keep',0)} / 복기우선 {V21386_STATE.get('paper_pending_review',0)} / 확인부족 {V21386_STATE.get('paper_pending_missing',0)} / 보류 {V21386_STATE.get('paper_pending_hold',0)}")
        lines.append(f"- OPEN 보존 {V21386_STATE.get('paper_open_preserved',0)} / CLOSED 보존 {V21386_STATE.get('paper_closed_preserved',0)}")
