def _v21387_safe_send_text(text, limit=3300):
    """Telegram hard chunk sender. Does not treat a fallback as normal body success."""
    s = str(text or '')
    if not s.strip():
        return {'sent': False, 'chunks': 0, 'error': 'empty_text'}
    lim = int(limit or 3300)
    if lim < 1000:
        lim = 1000
    chunks=[]
    cur=''
    try:
        for line in s.splitlines(True):
            if len(cur) + len(line) > lim and cur:
                chunks.append(cur.rstrip())
                cur=''
            while len(line) > lim:
                chunks.append(line[:lim].rstrip())
                line=line[lim:]
            cur += line
        if cur.strip():
            chunks.append(cur.rstrip())
        ok=0
        for ch in chunks:
            try:
                send(ch)
                ok += 1
            except Exception as e:
                V21387_STATE['safe_send_errors'] = int(V21387_STATE.get('safe_send_errors',0)) + 1
                V21387_STATE['last_error'] = 'safe_send:' + e.__class__.__name__
                return {'sent': False, 'chunks': ok, 'error': e.__class__.__name__}
        V21387_STATE['safe_chunks_sent'] = int(V21387_STATE.get('safe_chunks_sent',0)) + ok
        return {'sent': ok > 0, 'chunks': ok, 'error': ''}
    except Exception as e:
        V21387_STATE['safe_send_errors'] = int(V21387_STATE.get('safe_send_errors',0)) + 1
        V21387_STATE['last_error'] = 'chunk:' + e.__class__.__name__
        return {'sent': False, 'chunks': 0, 'error': e.__class__.__name__}
