def _execute_single_batch_command(cmd, args, idx, total):
    cmd_l=str(cmd or '').lower().strip().lstrip('/')
    label=f'▶️ 묶음 {idx}/{total} /{cmd_l}\n\n'
    try:
        if cmd_l in {'core','summary','quick','main','home'}:
            return _v21390_send(label + build_core_text_v21390(), limit=4200)
        if cmd_l in {'trade','gate','candidate_gate','auto_summary','quality'}:
            return _v21390_send(label + build_trade_text_v21390(False), limit=5600)
        if cmd_l in {'trade_full','quality_full'}:
            return _v21390_send(label + build_trade_text_v21390(True), limit=8200)
        if cmd_l in {'flow_check','flow','surgery_check','self_check','pipeline_check'}:
            return _v21390_send(label + build_flow_check_text_v21390(full=('full' in [str(a).lower() for a in (args or [])])), limit=7600)
        if cmd_l in {'deploy','deploy_check','upgrade_check','upgradestatus'}:
            return _v21390_send(label + build_upgradestatus_text_v21390(), limit=6200)
        if cmd_l in {'score','today','performance','result','results'} and callable(_BASE_V21390_SCORE_TEXT):
            return _v21390_send(label + _BASE_V21390_SCORE_TEXT(full=('full' in [str(a).lower() for a in (args or [])])), limit=7800)
        if cmd_l in {'mine','mine_full'} and callable(_BASE_V21390_MINE_TEXT):
            try: return _v21390_send(label + _BASE_V21390_MINE_TEXT(full=(cmd_l=='mine_full' or 'full' in [str(a).lower() for a in (args or [])])), limit=7800)
            except TypeError: return _v21390_send(label + _BASE_V21390_MINE_TEXT(), limit=7800)
        if cmd_l in {'mine_today','today_mine','daily_mine','today_review','mine_today_full','today_mine_full'} and callable(_BASE_V21390_MINE_TODAY):
            a=list(args or [])
            if cmd_l in {'mine_today_full','today_mine_full'} and 'full' not in [str(x).lower() for x in a]: a.append('full')
            full=('full' in [str(x).lower() for x in a])
            return _v21390_send(label + _BASE_V21390_MINE_TODAY(args=a, full=full), limit=5200)
        if callable(globals().get('_BASE_V21387_EXECUTE_SINGLE')):
            return _BASE_V21387_EXECUTE_SINGLE(cmd,args,idx,total)
        return _v21390_send(label + '- 처리 함수 확인 필요', limit=3200)
    except Exception as e:
        return _v21390_send(label + f'⚠️ 처리 오류: {e.__class__.__name__}: {str(e)[:160]}', limit=3200)
def run_batch_command_lines(lines, source_label='/batch'):
    try:
        parsed=[]
        for raw in lines or []:
            norm=_normalize_batch_line(raw) if callable(globals().get('_normalize_batch_line')) else None
            if not norm:
                continue
            cmd,args,orig=norm
            if cmd in {'batch','run'}:
                continue
            parsed.append((cmd,args,orig))
            if len(parsed) >= globals().get('BATCH_COMMAND_MAX_LINES', 12):
                break
        parsed=_v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed=[('core',[],'/core'),('trade',[],'/trade'),('score',[],'/score'),('deploy',[],'/deploy'),('mine',[],'/mine'),('flow_check',[],'/flow_check')]
        batch_start=_v21390_now()
        _v21390_send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.90: paper 연결부 대수술 + 명령어 캐시화', '- 고정 스냅샷: /trade 조회전용 / 살림검증→paper / 자동매수 OFF']), limit=3200)
        timings=[]; records=[]; total=len(parsed)
        for idx,(cmd,args,orig) in enumerate(parsed,1):
            st=_v21390_now(); status='OK'; rec={'cmd':str(cmd).lower().strip('/'),'sent':False,'body_ok':False,'fallback':False,'chunks':0,'error':''}
            try:
                out=_execute_single_batch_command(cmd,args,idx,total)
                if isinstance(out, dict):
                    rec.update(out)
                    rec['body_ok']=bool(out.get('sent')) if 'body_ok' not in out else bool(out.get('body_ok'))
                else:
                    rec['sent']=bool(out) if out is not None else True
                    rec['body_ok']=bool(out) if isinstance(out, bool) else True
                if not rec.get('body_ok'): status='BODY_MISSING'
                elif not rec.get('sent'): status='SEND_FAIL'
            except Exception as e:
                status=f'ERR {e.__class__.__name__}'
                rec.update({'sent':False,'body_ok':False,'fallback':False,'error':e.__class__.__name__})
                try: _v21390_send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}', limit=2500)
                except Exception: pass
            timings.append({'cmd':cmd,'after_start':st-batch_start,'elapsed':_v21390_now()-st,'status':status})
            records.append(rec)
        try:
            if callable(globals().get('_v21387_batch_integrity_text')):
                _v21390_send(_v21387_batch_integrity_text(records, parsed, timings, batch_start).replace('v87 batch','v90 batch'), limit=3300)
        except Exception: pass
        try:
            if callable(globals().get('_v2129_batch_timing_text')):
                _v21390_send(_v2129_batch_timing_text(timings,batch_start,source_label), limit=3000)
        except Exception: pass
    except Exception as e:
        V21390_STATE['last_error']='batch:'+e.__class__.__name__
        if callable(_BASE_V21390_RUN_BATCH):
            return _BASE_V21390_RUN_BATCH(lines, source_label=source_label)
        raise
