        lines=['🧪 모의청산 CLOSED', '', f'코인: {t}', f'결과: {_v21391_fmt_pct(pnl)}', f'진입가: {_v21391_fmt_price(entry)}', f'청산가: {_v21391_fmt_price(exitp)}', f"사유: {row.get('close_reason') or row.get('reason') or '-'}", f'보유시간: {held//60}분 {held%60}초' if held else '보유시간: 확인중', f"최고/최저: {_v21391_fmt_pct(row.get('max_up_pct',0))} / {_v21391_fmt_pct(row.get('min_down_pct',0))}", '', '실제매매 아님 / 자동매수 OFF']
        _v21391_send('\n'.join(lines), limit=3000)
