def _v21391_check_paper_events():
    try:
        sent=0
        for pid,pos in _v21391_current_positions().items():
            if str(pos.get('status','')).upper()=='OPEN':
                if _v21391_emit_paper_open_alert(pid,pos): sent+=1
        rows=_v21391_trade_log_rows()
        rows.sort(key=lambda r: _v21391_num(r.get('close_ts', r.get('updated_ts')),0), reverse=True)
        for r in rows[:30]:
            if str(r.get('status','')).upper()=='CLOSED':
                if _v21391_emit_paper_close_alert(r): sent+=1
        return sent
    except Exception as e:
        V21391_STATE['last_error']='check_events:'+e.__class__.__name__
        return 0
