    closes=[e for e in events if e.get('kind')=='paper_closed']
    rows=[r for r in _v21391_trade_log_rows() if str(r.get('status','')).upper()=='CLOSED' and _v21391_is_today(r.get('close_ts', r.get('updated_ts')))]
