    pnl=sum(_v21391_num(r.get('pnl_pct', r.get('realized_pct')),0) for r in rows)
    pending, openp=_v21391_pending_counts()
    return {'candidate':len(cand), 'pending_registered':len(pend), 'open_alert':len(opens), 'closed_alert':len(closes), 'closed':len(rows), 'wins':wins, 'losses':losses, 'pnl':pnl, 'pending_now':len(pending), 'open_now':len(openp), 'events':events, 'open_positions':openp[:5], 'candidate_recent':cand[-6:]}
