def _execute_single_batch_command(cmd, args, idx, total):
    cmd_l=str(cmd or '').lower().strip().lstrip('/')
    label=f'▶️ 묶음 {idx}/{total} /{cmd_l}\n\n'
    try:
        if cmd_l in {'core','summary','quick','main','home'}:
            return _v21391_send(label + build_core_text_v21392(), limit=6200)
        if cmd_l in {'trade','gate','candidate_gate','auto_summary','quality'}:
            return _v21391_send(label + build_trade_text_v21392(False), limit=7200)
        if cmd_l in {'trade_full','quality_full'}:
            return _v21391_send(label + build_trade_text_v21392(True), limit=9800)
        if cmd_l in {'flow_check','flow','surgery_check','self_check','pipeline_check'}:
            return _v21391_send(label + build_flow_check_text_v21392(full=('full' in [str(a).lower() for a in (args or [])])), limit=9000)
        if cmd_l in {'paper_today','today_paper','paper_alerts','alerts_today'}:
            return _v21391_send(label + build_paper_today_text_v21392(full=('full' in [str(a).lower() for a in (args or [])])), limit=7000)
        if cmd_l in {'btc','bitcoin'}:
            return _v21391_send(label + build_btc_text_v21319(), limit=5000)
        if cmd_l in {'deploy','deploy_check','upgrade_check','upgradestatus'}:
            return _v21391_send(label + build_upgradestatus_text_v21392(), limit=7600)
        if cmd_l in {'mine','mine_full'} and callable(globals().get('build_mine_text_v21349')):
            full = (cmd_l == 'mine_full') or ('full' in [str(a).lower() for a in (args or [])])
            return _v21391_send(label + build_mine_text_v21349(full=full), limit=9800 if not full else 14000)
        if cmd_l in {'mine_today','today_mine'} and callable(globals().get('build_mine_today_text_v21373')):
            a=[str(x) for x in (args or [])]
            full=('full' in [x.lower() for x in a])
            return _v21391_send(label + build_mine_today_text_v21373(args=a, full=full), limit=9800 if not full else 14000)
        if cmd_l in {'score','today'} and callable(globals().get('build_score_text_v21339')):
            full=('full' in [str(a).lower() for a in (args or [])])
            return _v21391_send(label + build_score_text_v21339(full=full), limit=9800 if not full else 7600)
        if callable(_BASE_V21392_EXECUTE_SINGLE):
            return _BASE_V21392_EXECUTE_SINGLE(cmd,args,idx,total)
        return _v21391_send(label + '- 처리 함수 확인 필요', limit=3200)
    except Exception as e:
        return _v21391_send(label + f'⚠️ 처리 오류: {e.__class__.__name__}: {str(e)[:160]}', limit=3200)
