        if cmd_l in {'core','summary','quick','main','home'}:
            return _v21393_send_labeled(cmd_l, idx, total, build_core_text_v21393(), limit=6200)
        if cmd_l in {'trade','gate','candidate_gate','auto_summary','quality'}:
            return _v21393_send_labeled(cmd_l, idx, total, build_trade_text_v21393(False), limit=9000)
        if cmd_l in {'trade_full','quality_full'}:
            return _v21393_send_labeled(cmd_l, idx, total, build_trade_text_v21393(True), limit=12000)
        if cmd_l in {'flow_check','flow','surgery_check','self_check','pipeline_check'}:
            full=any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21393_send_labeled(cmd_l, idx, total, build_flow_check_text_v21393(full), limit=9800 if not full else 13000)
        if cmd_l in {'paper_today','today_paper','paper_alerts','alerts_today'}:
            full=any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21393_send_labeled(cmd_l, idx, total, build_paper_today_text_v21393(full), limit=9000)
        if cmd_l in {'deploy','deploy_check','upgrade_check','upgradestatus'}:
            return _v21393_send_labeled(cmd_l, idx, total, build_upgradestatus_text_v21393(), limit=7600)
        if callable(_BASE_V21393_EXECUTE_SINGLE):
            return _BASE_V21393_EXECUTE_SINGLE(cmd,args,idx,total)
