def run_batch_command_lines(lines, source_label='/batch'):
    try:
        parsed=[]
        for raw in lines or []:
            norm=_normalize_batch_line(raw) if callable(globals().get('_normalize_batch_line')) else None
            if not norm: continue
            cmd,args,orig=norm
            if cmd in {'batch','run'}: continue
            parsed.append((cmd,args,orig))
            if len(parsed) >= globals().get('BATCH_COMMAND_MAX_LINES', 12): break
        parsed=_v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed=[('core',[],'/core'),('trade',[],'/trade'),('paper_today',[],'/paper_today'),('flow_check',[],'/flow_check'),('candidate_reason',[],'/candidate_reason'),('missed',[],'/missed')]
        batch_start=_v21395_now()
        _v21395_send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.95: PENDING→OPEN 알림폭주 차단 + 기존 이관 무음처리', '- 고정 스냅샷: 후보는 /trade, 실제 paper는 /paper_today, 연결은 /flow_check']), limit=3600)
        timings=[]; records=[]; total=len(parsed)
        for idx,(cmd,args,orig) in enumerate(parsed,1):
            st=_v21395_now(); status='OK'; rec={'cmd':str(cmd).lower().strip('/'),'sent':False,'body_ok':False,'fallback':False,'chunks':0,'error':''}
            try:
                out=_execute_single_batch_command(cmd,args,idx,total)
                if isinstance(out, dict):
                    rec.update(out); rec['body_ok']=bool(out.get('body_ok', out.get('sent', True)))
                else:
                    rec['sent']=bool(out) if isinstance(out,bool) else True; rec['body_ok']=True
                if not rec.get('body_ok'): status='BODY_MISSING'
                elif not rec.get('sent'): status='SEND_FAIL'
            except Exception as e:
                status=f'ERR {e.__class__.__name__}'; rec.update({'sent':False,'body_ok':False,'error':e.__class__.__name__})
                try: _v21395_send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}', limit=2500)
                except Exception: pass
            timings.append({'cmd':cmd,'after_start':st-batch_start,'elapsed':_v21395_now()-st,'status':status}); records.append(rec)
        try:
            if callable(globals().get('_v21387_batch_integrity_text')):
                txt=_v21387_batch_integrity_text(records, parsed, timings, batch_start)
                _v21395_send(str(txt).replace('v87 batch','v95 batch').replace('v90 batch','v95 batch').replace('v91 batch','v95 batch').replace('v92 batch','v95 batch').replace('v93 batch','v95 batch').replace('v94 batch','v95 batch'), limit=3300)
        except Exception: pass
        try:
            if callable(globals().get('_v2129_batch_timing_text')):
                _v21395_send(_v2129_batch_timing_text(timings,batch_start,source_label), limit=3000)
        except Exception: pass
    except Exception as e:
        V21395_STATE['last_error']='batch:'+e.__class__.__name__
        if callable(_BASE_V21395_RUN_BATCH): return _BASE_V21395_RUN_BATCH(lines, source_label=source_label)
        raise
