def _v21396_count_positions():
    out = {'pending':0, 'open':0, 'closed_pos':0, 'quarantine_open':0, 'clean_open':0, 'carry_pending':0, 'new_pending':0}
    try:
        for pos in _v21396_positions().values():
            if not isinstance(pos, dict):
                continue
            st = str(pos.get('status','')).upper()
            if st == 'PENDING':
                out['pending'] += 1
                if pos.get('v21396_new_pending'):
                    out['new_pending'] += 1
                else:
                    out['carry_pending'] += 1
            elif st == 'OPEN':
                out['open'] += 1
                if _v21396_is_quarantined_open(pos):
                    out['quarantine_open'] += 1
                else:
                    out['clean_open'] += 1
            elif st == 'CLOSED':
                out['closed_pos'] += 1
    except Exception as e:
        V21396_STATE['last_error'] = 'count:' + e.__class__.__name__
    return out
