def _v21390_source_lines(cache=None):
    c = cache if isinstance(cache, dict) else (_v21390_cache() if callable(globals().get('_v21390_cache')) else {})
    rows = list(c.get('rows') or []) if isinstance(c, dict) else []
    source = str(c.get('source') or '') if isinstance(c, dict) else ''
    try:
        latest = list(globals().get('latest_fast_scan_items') or [])
        factory = list(globals().get('V21385_LAST_SNAPSHOT_ROWS') or [])
        rank = list(globals().get('COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS') or [])
        ws = len(globals().get('RANK_STATE_BY_TICKER') or {})
        cache_len = len(globals().get('shared_market_cache') or {}) if isinstance(globals().get('shared_market_cache'), dict) else 0
        age = None
        try:
            ts = float(globals().get('latest_fast_scan_result_ts') or 0)
            age = _v21396_now() - ts if ts else None
        except Exception:
            age = None
        if source == 'factory_v85' and rows:
            status = '✅ factory 저장 후보 있음'
        elif source == 'latest_fast_scan_items' and rows:
            status = '⚠️ latest 후보 표시 / factory 저장 전 paper 보류'
        elif _v21396_rank_display_source(source) and rows:
            status = '⚠️ rank 참고 후보 표시 / paper 연결 차단'
        else:
            status = '❌ 조회 후보 없음' if not rows else '❔ 후보 소스 확인 필요'
        age_txt = f' / latest_age {int(age)}초' if age is not None else ''
        return [status + f' / 기준 {len(rows)}개', f'- 조회소스: {source or "확인중"} / factory {len(factory)} / latest {len(latest)} / rank {len(rank)} / WS {ws} / 시장캐시 {cache_len}{age_txt}']
    except Exception:
        return ['⚠️ 조회소스 표시 오류']
