def _v21396_fast_rank_rows(limit=8):
    rows = []
    try:
        raw = list(globals().get('COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS') or [])
        seen = set()
        for row in raw:
            if not isinstance(row, dict):
                continue
            t = _v21396_ticker(row)
            if not t or t == 'BTC' or t in seen:
                continue
            seen.add(t)
            ch3 = _v21396_num(row.get('change_3', row.get('chg_3m')), 0)
            ch5 = _v21396_num(row.get('change_5', row.get('chg_5m')), 0)
            ch30 = _v21396_num(row.get('change_30', row.get('chg_30m')), 0)
            money = _v21396_num(row.get('turnover_5m', row.get('turnover_recent_5m', row.get('turnover', row.get('money_krw', 0)))), 0)
            strength = max(ch3, ch5, ch30)
            if strength < 0.35 and money < 80_000_000:
                continue
            score = strength * 8.0 + min(money / 100000000.0, 20.0) * 0.5
            rows.append({'ticker': t, 'change_3': ch3, 'change_5': ch5, 'change_30': ch30, 'money': money, 'score': score})
        rows.sort(key=lambda r: (r.get('score',0), r.get('money',0)), reverse=True)
    except Exception as e:
        V21396_STATE['last_error'] = 'fast_rank_rows:' + e.__class__.__name__
    return rows[:max(1, int(limit or 8))]
def _v21396_money_text(v):
    try:
        x = float(v or 0)
        if x >= 100000000:
            return f'{x/100000000:.2f}억'
        if x >= 10000:
            return f'{x:,.0f}원'
        return '대금확인중' if x <= 0 else f'{x:,.0f}원'
    except Exception:
        return '대금확인중'
