                pos['v21398_pending_wait_reason'] = reason_text
                pos['v21398_pending_last_check_ts'] = now
                pos['v21398_entry_detect_price'] = round(_v21398_num((info or {}).get('detect'), _v21398_detect_price(pos)), 8)
                pos['v21398_entry_precheck_price'] = round(_v21398_num((info or {}).get('pre'), price), 8)
                pos['v21398_entry_gap_pct'] = round(_v21398_num((info or {}).get('gap_pct'), 0), 4)
