        if seen:
            globals()['paper_positions'] = positions
            if callable(globals().get('save_paper_state_v258')):
                save_paper_state_v258()
        V21399_STATE['pre_v99_clean_open_seen'] = int(V21399_STATE.get('pre_v99_clean_open_seen', 0)) + seen
