def _execute_single_batch_command(cmd, args, idx, total):
    cmd_l = str(cmd or '').lower().strip().lstrip('/')
    try:
        if cmd_l in {'core','summary','quick','main','home'}:
            return _v21399_send_labeled(cmd_l, idx, total, build_core_text_v21399(), limit=9000)
        if cmd_l in {'trade','gate','candidate_gate','auto_summary','quality'}:
            return _v21399_send_labeled(cmd_l, idx, total, build_trade_text_v21399(False), limit=12500)
        if cmd_l in {'trade_full','quality_full'}:
            return _v21399_send_labeled(cmd_l, idx, total, build_trade_text_v21399(True), limit=18000)
        if cmd_l in {'paper_today','today_paper','paper_alerts','alerts_today'}:
            full=any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21399_send_labeled(cmd_l, idx, total, build_paper_today_text_v21399(full), limit=10000 if not full else 14000)
        if cmd_l in {'flow_check','flow','surgery_check','self_check','pipeline_check'}:
            full=any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21399_send_labeled(cmd_l, idx, total, build_flow_check_text_v21399(full), limit=10000 if not full else 15000)
        if cmd_l in {'candidate_reason','why_candidates','why_candidate','why_no_candidate','no_candidate','candidate_zero'}:
            full=any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21399_send_labeled(cmd_l, idx, total, build_candidate_reason_text_v21399(full), limit=9500 if not full else 14000)
        if cmd_l in {'missed','missed_full','missedfull'}:
            full = cmd_l in {'missed_full','missedfull'} or any(str(a).lower() in {'full','상세','detail'} for a in (args or []))
            return _v21399_send_labeled(cmd_l, idx, total, build_missed_text_v21396(full), limit=9000 if full else 5600)
        if cmd_l in {'deploy','deploy_check','upgrade_check','upgradestatus'}:
            return _v21399_send_labeled(cmd_l, idx, total, build_upgradestatus_text_v21399(), limit=10000)
        if callable(_BASE_V21399_EXEC_SINGLE):
            return _BASE_V21399_EXEC_SINGLE(cmd,args,idx,total)
        return _v21399_send_labeled(cmd_l, idx, total, f'⚠️ /{cmd_l} 처리 함수 확인 필요', limit=3600)
    except Exception as e:
        V21399_STATE['last_error']='batch_single:'+e.__class__.__name__
