def run_batch_command_lines(lines, source_label='/batch'):
    try:
        _v21399_backfill_pending_entry_marks(save=True)
        _v21399_mark_pre_v99_clean_open_seen()
        parsed=[]
        for raw in lines or []:
            norm=_normalize_batch_line(raw) if callable(globals().get('_normalize_batch_line')) else None
            if not norm: continue
            cmd,args,orig=norm
            if cmd in {'batch','run'}: continue
            parsed.append((cmd,args,orig))
            if len(parsed) >= globals().get('BATCH_COMMAND_MAX_LINES', 12): break
        parsed=_v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed=[('core',[],'/core'),('trade',[],'/trade'),('paper_today',[],'/paper_today'),('flow_check',[],'/flow_check'),('candidate_reason',[],'/candidate_reason')]
        batch_start=_v21399_now()
        _v21396_send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.99: v98 0표시 원인분리 + CPU/메모리 복구 + 진입가 연결보강', '- 고정 스냅샷: 자동매수 OFF / rank는 표시만 / 시작직후 0은 원인분리']), limit=4200)
        timings=[]; records=[]; total=len(parsed)
        for idx,(cmd,args,orig) in enumerate(parsed,1):
            st=_v21399_now(); status='OK'; rec={'cmd':str(cmd).lower().strip('/'),'sent':False,'body_ok':False,'fallback':False,'chunks':0,'error':''}
            try:
                out=_execute_single_batch_command(cmd,args,idx,total)
                if isinstance(out, dict):
                    rec.update(out); rec['body_ok']=bool(out.get('body_ok', out.get('sent', True)))
                else:
                    rec['sent']=bool(out) if isinstance(out,bool) else True; rec['body_ok']=True
                if not rec.get('body_ok'): status='BODY_MISSING'
                elif not rec.get('sent'): status='SEND_FAIL'
            except Exception as e:
                status=f'ERR {e.__class__.__name__}'; rec.update({'sent':False,'body_ok':False,'error':e.__class__.__name__})
                try: _v21396_send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}', limit=2500)
                except Exception: pass
            timings.append({'cmd':cmd,'after_start':st-batch_start,'elapsed':_v21399_now()-st,'status':status}); records.append(rec)
        try:
            if callable(globals().get('_v21387_batch_integrity_text')):
                txt=_v21387_batch_integrity_text(records, parsed, timings, batch_start)
                _v21396_send(_v21399_replace_version_text(str(txt)), limit=3200)
        except Exception: pass
        try:
            if callable(globals().get('_v2129_batch_timing_text')):
                timing = _v21399_replace_version_text(_v2129_batch_timing_text(timings,batch_start,source_label))
                timing += '\n\n' + '\n'.join(_v21399_resource_lines())
                _v21396_send(timing, limit=3800)
        except Exception: pass
    except Exception as e:
        V21399_STATE['last_error']='batch:'+e.__class__.__name__
        if callable(_BASE_V21399_RUN_BATCH): return _BASE_V21399_RUN_BATCH(lines, source_label=source_label)
        raise
