def _v213100_resource_summary():
    try:
        V213100_STATE['cpu_calls']=int(V213100_STATE.get('cpu_calls',0))+1
    except Exception: pass
    cores = os.cpu_count() or 1
    single = _v213100_cpu_single_core_pct()
