def run_batch_command_lines(lines, source_label='/batch'):
    try: V213101_STATE['batch_calls']=int(V213101_STATE.get('batch_calls',0))+1
    except Exception: pass
    parsed=[]
    try:
        for raw in lines or []:
            norm=_normalize_batch_line(raw) if callable(globals().get('_normalize_batch_line')) else None
            if not norm: continue
            cmd,args,orig=norm
            if cmd in {'batch','run'}: continue
            parsed.append((cmd,args,orig))
            if len(parsed)>=globals().get('BATCH_COMMAND_MAX_LINES',12): break
        parsed=_v21339_expand_batch(parsed) if callable(globals().get('_v21339_expand_batch')) else parsed
        if not parsed:
            parsed=[('core',[],'/core'),('trade',[],'/trade'),('paper_today',[],'/paper_today'),('flow_check',[],'/flow_check'),('candidate_reason',[],'/candidate_reason'),('cpu_status',[],'/cpu_status')]
        batch_start=_v213101_now()
        _v21396_send('\n'.join(['📦 묶음 명령 접수', f'- 출처: {source_label}', f'- 실행 {len(parsed)}개', '- v2.13.101: 체크표 상태판 + 루프지연/CPU/슬리피지 판정 강화', '- 고정 스냅샷: 자동매수 OFF / 기본판은 체크표 우선']), limit=4200)
        timings=[]; ok=0; total=len(parsed)
        for idx,(cmd,args,orig) in enumerate(parsed,1):
            st=_v213101_now(); status='OK'
            try:
                out=_execute_single_batch_command(cmd,args,idx,total)
                ok += 1
            except Exception as e:
                status=f'ERR {e.__class__.__name__}'
                try: _v21396_send(f'⚠️ 묶음 {idx}/{total} /{cmd} 처리 에러: {e}', limit=2500)
                except Exception: pass
            timings.append({'cmd':cmd,'elapsed':_v213101_now()-st,'status':status})
        total_elapsed=_v213101_now()-batch_start
        slow=', '.join([f"/{x['cmd']} {x['elapsed']:.1f}s" for x in sorted(timings, key=lambda z:z.get('elapsed',0), reverse=True)[:3] if x.get('elapsed',0)>=1.0]) or '없음'
        tail=['🧾 v101 batch 요약', f'- 출력무결성: 실행 {len(parsed)}개 / 실제본문 {ok}개', f'- 전체 경과: {total_elapsed:.2f}s / 느린 명령: {slow}', '', *_v213101_resource_lines(full=False), '', *_v213101_next_lines()]
        _v21396_send('\n'.join(tail), limit=5200)
    except Exception as e:
        V213101_STATE['last_error']='batch:'+e.__class__.__name__
        if callable(globals().get('_BASE_V213101_RUN_BATCH')): return _BASE_V213101_RUN_BATCH(lines, source_label=source_label)
        raise
