V213102_TRADE_TEXT_CACHE = {'ts':0.0,'text':''}
def build_trade_text_v213102(full=False):
    if full:
        return _BASE_V213102_TRADE_TEXT(True) if callable(_BASE_V213102_TRADE_TEXT) else '⚠️ /trade_full 생성 함수 없음'
    now = _v213102_now()
    try:
        if V213102_TRADE_TEXT_CACHE.get('text') and (now - float(V213102_TRADE_TEXT_CACHE.get('ts') or 0)) < V213102_TRADE_CACHE_TTL_SEC:
            V213102_STATE['trade_cache_hit'] = int(V213102_STATE.get('trade_cache_hit',0)) + 1
            return V213102_TRADE_TEXT_CACHE['text']
    except Exception:
        pass
    V213102_STATE['trade_cache_miss'] = int(V213102_STATE.get('trade_cache_miss',0)) + 1
    text = _BASE_V213102_TRADE_TEXT(False) if callable(_BASE_V213102_TRADE_TEXT) else '⚠️ /trade 생성 함수 없음'
    try:
        # 기본판 꼬리의 중복 체크표는 줄이고 v102 요약만 붙인다.
        marker = '📎 기본 요약'
        if marker in str(text):
            text = str(text).split(marker,1)[0].rstrip()
        text = str(text).rstrip() + '\n\n📎 v102 요약\n' + '\n'.join(_v213102_check_table_lines()[1:6]) + '\n' + '\n'.join(_v213102_entry_lines()[1:4])
    except Exception:
        pass
    V213102_TRADE_TEXT_CACHE.update({'ts':now,'text':text})
    return text

