def _v213103_lite_row(row):
    try:
        t=_v213103_ticker(row)
        label='관찰대기'; reason=''
        if callable(globals().get('_v21390_label')):
            label, reason = _v21390_label(row)
        snap = _v21390_snap(row) if callable(globals().get('_v21390_snap')) else {}
        ch1=_v213103_num((snap or {}).get('change_1m', (row or {}).get('change_1m')),0)
        ch5=_v213103_num((snap or {}).get('change_5m', (row or {}).get('change_5m')),0)
        fl=_v213103_num((snap or {}).get('from_low', (row or {}).get('from_low')),0)
        money=_v213103_num((snap or {}).get('money_krw', (row or {}).get('money_krw', (row or {}).get('turnover_krw'))),0)
        mtxt = f'{money/100000000:.2f}억' if money>=100000000 else ('대금확인중' if money<=0 else f'{money:,.0f}원')
        return str(label), f"- {t or '-'} / {label} / 1m {ch1:+.2f}% · 5m {ch5:+.2f}% / 저점 +{fl:.2f}% / 대금 {mtxt} / {str(reason)[:60] or '-'}"
    except Exception as e:
        return '관찰대기', '- 후보 표시 오류 ' + e.__class__.__name__

def build_trade_text_v213103(full=False):
    if full:
        try: return build_trade_text_v213102(True) if callable(globals().get('build_trade_text_v213102')) else build_trade_text_v213101(True)
        except Exception: return '⚠️ /trade_full 생성 실패'
    now=_v213103_now()
    try:
        if V213103_TRADE_TEXT_CACHE.get('text') and now - float(V213103_TRADE_TEXT_CACHE.get('ts') or 0) < V213103_TRADE_CACHE_TTL_SEC:
            V213103_STATE['trade_cache_hit'] = int(V213103_STATE.get('trade_cache_hit',0)) + 1
            return V213103_TRADE_TEXT_CACHE['text']
    except Exception: pass
    V213103_STATE['trade_cache_miss'] = int(V213103_STATE.get('trade_cache_miss',0)) + 1
    try:
        rows, source = _v21385_cached_rows() if callable(globals().get('_v21385_cached_rows')) else ([], 'none')
    except Exception:
        rows, source = [], 'error'
    groups={'살림검증':[], '상단관찰':[], '복기우선':[], '확인부족':[]}
    for r in list(rows or [])[:24]:
        lab, line = _v213103_lite_row(r)
        if lab == '상단관찰': groups['상단관찰'].append(line)
        elif lab == '살림검증': groups['살림검증'].append(line)
        elif lab in {'복기우선','복기대기'}: groups['복기우선'].append(line)
        elif str(lab).startswith('확인부족'): groups['확인부족'].append(line)
    b = _v213103_summary_data().get('b',{})
    lines=['🔎 v340 후보품질 /trade','', '✅ 기본판: 저장 스냅샷만 짧게 표시 / 상세는 /trade_full', f"- 조회소스 {source} / rows {len(rows or [])} / factory {b.get('factory',0)} / rank {b.get('rank',0)} / 시장캐시 {b.get('cache',0)}", '']
    for title,key,limit in [('1) 살림검증 후보', '살림검증', 5), ('2) 상단관찰 후보', '상단관찰', 3), ('3) 복기우선 후보', '복기우선', 3), ('4) 확인부족 후보', '확인부족', 2)]:
        lines.append(title)
        arr=groups[key][:limit]
        if arr: lines.extend(arr)
        else: lines.append('- 현재 기준 뚜렷한 후보 없음')
        lines.append('')
    lines += ['📎 기본 요약', *_v213103_score_summary_lines(), '', *_v213103_entry_lines()[:3]]
    text='\n'.join(lines).rstrip()
    V213103_TRADE_TEXT_CACHE.update({'ts':now,'text':text})
    return text

