def build_command_display_cache_once():
    try:
        now_ts = time.time()
        last = float(globals().get('COMMAND_DISPLAY_CACHE_LAST_REFRESH_TS', 0) or 0)
        rows = globals().get('COMMAND_DISPLAY_CACHE_LAST_RANK_ROWS', [])
        min_interval = max(12.0, float(globals().get('COMMAND_DISPLAY_REFRESH_SEC', 22.0) or 22.0))
        if last > 0 and (now_ts - last) < min_interval and isinstance(rows, list) and rows:
            globals()['COMMAND_DISPLAY_CACHE_DONE'] = int(globals().get('COMMAND_DISPLAY_CACHE_DONE', 0) or 0) + 1
            try:
                globals()['COMMAND_DISPLAY_CACHE_STAGE_LAST_SUMMARY'] = 'v105표시캐시재사용 0.00s'
            except Exception:
                pass
            return
    except Exception:
        pass
    if callable(_BASE_BUILD_COMMAND_DISPLAY_CACHE_ONCE_V213105):
        return _BASE_BUILD_COMMAND_DISPLAY_CACHE_ONCE_V213105()
    return None

# ---------- CLOSED 로그 기준 통일 / 중복 제거 ----------
def _v213105_now():
    try: return time.time()
    except Exception: return 0.0

def _v213105_num(v, default=0.0):
    try:
        if callable(globals().get('_v213104_num')): return _v213104_num(v, default)
        if v in (None, ''): return default
        return float(v)
    except Exception:
        return default

def _v213105_epoch(v):
    x = _v213105_num(v, 0)
    if x > 10_000_000_000: x = x / 1000.0
    return x

def _v213105_ticker(r):
    try:
        if callable(globals().get('_v213104_ticker')): return _v213104_ticker(r)
    except Exception:
        pass
    try: return str((r or {}).get('ticker','') or (r or {}).get('symbol','') or '').upper().strip()
    except Exception: return ''

def _v213105_close_ts(r):
    try:
        return _v213105_epoch((r or {}).get('close_ts', (r or {}).get('closed_ts', (r or {}).get('updated_ts', (r or {}).get('ts', 0)))))
    except Exception:
        return 0.0

def _v213105_entered_ts(r):
    try:
        return _v213105_epoch((r or {}).get('entered_ts', (r or {}).get('open_ts', (r or {}).get('created_ts', 0))))
    except Exception:
        return 0.0

def _v213105_position_key(pid=None, row=None):
    r = row or {}
    try:
        raw = str(pid or r.get('id') or r.get('pid') or r.get('pos_id') or r.get('position_id') or '').strip()
        if raw:
            return 'pid:' + raw
        t = _v213105_ticker(r) or '?'
        ent = int(_v213105_entered_ts(r) or 0)
        entry = round(_v213105_num(r.get('entry_price', r.get('avg_entry_price', 0)), 0), 8)
        return f'fallback:{t}:{ent}:{entry}'
    except Exception:
        return 'fallback:unknown'

def _v213105_closed_rows_raw():
    try:
        if callable(globals().get('_v21391_trade_log_rows')):
            rows = _v21391_trade_log_rows()
        else:
            rows = list(globals().get('paper_trade_log') or [])
    except Exception:
        rows = []
    return [r for r in list(rows or []) if isinstance(r, dict) and str(r.get('status','')).upper() == 'CLOSED']

def _v213105_closed_rows_dedup():
    rows = _v213105_closed_rows_raw()
    best = {}
    dup = 0
    for r in rows:
        key = _v213105_position_key(row=r)
        ts = _v213105_close_ts(r)
        old = best.get(key)
        if old is None or ts >= _v213105_close_ts(old):
            if old is not None:
                dup += 1
            best[key] = r
        else:
            dup += 1
    V213105_STATE['dedupe_rows'] = dup
    return sorted(best.values(), key=_v213105_close_ts, reverse=True)

def _v213105_kst_date(ts=None):
    try:
        import datetime
        try:
            from zoneinfo import ZoneInfo
            z = ZoneInfo('Asia/Seoul')
            if ts is None:
                return datetime.datetime.now(z).date()
            return datetime.datetime.fromtimestamp(float(ts), z).date()
        except Exception:
            # KST fallback: epoch + 9h
            if ts is None:
                return (datetime.datetime.utcnow() + datetime.timedelta(hours=9)).date()
            return (datetime.datetime.utcfromtimestamp(float(ts)) + datetime.timedelta(hours=9)).date()
    except Exception:
        return None

def _v213105_is_today(ts):
    try:
        t = _v213105_epoch(ts)
        if t <= 0: return False
        return _v213105_kst_date(t) == _v213105_kst_date(None)
    except Exception:
        return False

# v103/v100 today 계산도 v105 KST + dedupe 기준으로 통일
_v213103_is_today = _v213105_is_today

