def _v213104_close_position(pid, pos, price, reason, now=None):
    key = _v213105_position_key(pid, pos)
    try:
        if key in V213105_CLOSED_KEYS:
            V213105_STATE['duplicate_close_blocked'] = int(V213105_STATE.get('duplicate_close_blocked',0)) + 1
            try:
                if isinstance(globals().get('V213104_STATE'), dict):
                    V213104_STATE['last_error'] = 'duplicate_close_blocked:' + str(_v213105_ticker(pos))
            except Exception:
                pass
            return False
    except Exception:
        pass
    ok = False
    try:
        if callable(_BASE_V213104_CLOSE_POSITION_V213105):
            ok = bool(_BASE_V213104_CLOSE_POSITION_V213105(pid, pos, price, reason, now))
    except Exception as e:
        V213105_STATE['last_error'] = 'close_wrap:' + e.__class__.__name__
        ok = False
    if ok:
        try: V213105_CLOSED_KEYS.add(key)
        except Exception: pass
    return ok

