def _v21391_emit_paper_close_alert(row):
    key = _v213105_position_key(row=row)
    try:
        sent_keys = globals().setdefault('V213105_CLOSE_ALERT_KEYS', set())
        # 이미 같은 position의 알림이 이번 런타임에서 나갔으면 중복 알림 차단.
        if key in sent_keys:
            V213105_STATE['duplicate_alert_blocked'] = int(V213105_STATE.get('duplicate_alert_blocked',0)) + 1
            return False
        ok = bool(_BASE_CLOSE_ALERT_V213105(row)) if callable(_BASE_CLOSE_ALERT_V213105) else False
        if ok:
            sent_keys.add(key)
        return ok
    except Exception as e:
        V213105_STATE['last_error'] = 'close_alert_wrap:' + e.__class__.__name__
        return False

# ---------- OPEN 감시 상태표 실제값 보정 ----------
def _v213105_live_open_counts():
    out={'mem_total':0,'mem_watch':0,'mem_quarantine':0,'mem_bad_entry':0,'paper_open':0,'paper_new_open':0,'paper_quarantine':0,'oldest':0.0}
    now=_v213105_now()
    try:
        p = _v213101_paper_activity() if callable(globals().get('_v213101_paper_activity')) else {}
        out['paper_open']=int(_v213105_num(p.get('open'),0)); out['paper_new_open']=int(_v213105_num(p.get('new_open'),0)); out['paper_quarantine']=int(_v213105_num(p.get('quarantine_open'),0))
    except Exception:
        pass
    try:
        pp = globals().get('paper_positions') if isinstance(globals().get('paper_positions'), dict) else {}
        for pos in pp.values():
            if not isinstance(pos, dict) or str(pos.get('status','')).upper()!='OPEN':
                continue
            out['mem_total'] += 1
            q = _v213104_is_quarantine_open(pos) if callable(globals().get('_v213104_is_quarantine_open')) else False
            if q:
                out['mem_quarantine'] += 1
                continue
            out['mem_watch'] += 1
            if _v213105_num(pos.get('entry_price'),0) <= 0:
                out['mem_bad_entry'] += 1
            ent = _v213105_num(pos.get('entered_ts', pos.get('open_ts', pos.get('created_ts', now))), now)
            if ent > 0:
                out['oldest'] = max(out['oldest'], max(0.0, now-ent))
    except Exception:
        pass
    return out

def _v213104_close_watch_lines():
    try:
        st = dict(globals().get('V213104_STATE') or {})
        lc = _v213105_live_open_counts()
        lines=['🧪 OPEN 청산 감시']
        watch=int(_v213105_num(st.get('watch_targets'),0)); total=int(_v213105_num(st.get('open_total'),0)); quar=int(_v213105_num(st.get('excluded_quarantine'),0))
        closed=int(_v213105_num(st.get('closed'),0)); oldest=max(_v213105_num(st.get('oldest_open_sec'),0), _v213105_num(lc.get('oldest'),0))
        lines.append(f"- 최근스캔 감시대상: {watch}개 / 최근스캔 전체 OPEN {total}개 / 격리 제외 {quar}개")
        lines.append(f"- 현재 paper표본: OPEN {lc.get('paper_open',0)}개 / 정상·신규 {lc.get('paper_new_open',0)}개 / 격리 {lc.get('paper_quarantine',0)}개")
        if total == 0 and int(lc.get('paper_open',0)) > 0:
            V213105_STATE['watch_display_source_mismatch'] = int(V213105_STATE.get('watch_display_source_mismatch',0)) + 1
            lines.append('- 판독: ⚠️ 최근스캔 숫자와 paper표본 숫자가 달라 표시/메모리 소스 확인 필요')
        lines.append(f"- 최근 스캔: 호출 {st.get('scan_calls',0)} / 가격없음 {st.get('price_missing',0)} / entry없음 {st.get('excluded_bad_entry',0)} / 가격갱신 {st.get('updated',0)}")
        lines.append(f"- CLOSED 연결: v104 누적 {closed}개 / time_exit {st.get('time_exit_closed',0)} / stop {st.get('stop_closed',0)} / tp {st.get('tp_closed',0)} / 중앙보호 {st.get('guard_closed',0)}")
        lines.append(f"- 중복방지: CLOSED저장 차단 {V213105_STATE.get('duplicate_close_blocked',0)} / 알림차단 {V213105_STATE.get('duplicate_alert_blocked',0)} / score중복제외 {V213105_STATE.get('dedupe_rows',0)}")
        lines.append(f"- 가장 오래된 감시 OPEN: {_v213104_fmt_age(oldest) if callable(globals().get('_v213104_fmt_age')) else str(int(oldest))+'초'}")
        if closed > 0:
            lines.append('- 판정: ✅ OPEN→CLOSED 경로 작동 / 이제 집계·중복 방지 기준으로 관찰')
        elif watch > 0 or int(lc.get('paper_new_open',0)) > 0:
            lines.append('- 판정: ❔ 감시 중 / 아직 청산 조건 미충족 또는 표시소스 확인')
        else:
            lines.append('- 판정: ❔ 감시할 신규 OPEN 대기')
        last=list(st.get('last_closed') or [])[-4:]
        if last:
            lines.append('- 최근 CLOSED')
            for r in last:
                lines.append(f"  · {r.get('ticker','?')} / {r.get('reason','')}")
        waits=list(st.get('last_wait') or [])[-4:]
        if waits:
            lines.append('- 최근 감시 제외/대기')
            for r in waits:
                lines.append(f"  · {r.get('ticker','?')} / {r.get('reason','')}")
        if st.get('last_error'):
            lines.append(f"- 최근 상태: {st.get('last_error')}")
        return lines
    except Exception as e:
        return ['🧪 OPEN 청산 감시', f'- 표시 오류: {e.__class__.__name__}']

